/* 平成18年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h18.committeeSessions.push(...[{"id":"h18-20060626-7","meetingId":"h18-cm06","date":"2006年6月26日","dateIso":"2006-06-26","committee":"厚生委員会","time":"午前１０時０４分～午後４時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を114件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新体系に変わるというふうなところで、心障者会館とかがやき園のデイサービスは終了という形にせざるを得ないというところなんですけれども、それぞれ利用者の方がどれくらいだったのか、登録者と１日の利用人数、それからその利用者が例えば１週間のうちにどれぐらい通われているのかという利用実態というところを教えていただきたいと思います。","respondent":"西島障害者福祉課長","answer":"中には丸５日間という方もいらっしゃいます。それから、かがやき園のデイサービスですが、定員は５人です。登録は出たり入ったりがどうしてもありますけど、現在は１０人ということで、利用状況は先ほどお話ししたような状況とほぼ同じような状況です。","voiceIndex":16,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところで、この心障会館は区立の施設ということだと思うんですけど、区立の施設が社会福祉法人立の施設の事業の拡大というふうなところに問題なくなれるのかどうなのかという仕組み上のことを教えていただきたいのと、あと、それを続けるというところでは、条文上の規定というのは、デイサービスがこれに基づいてやりますよというのはどうなっていくのか、そのことについてちょっと教えてください。","respondent":"西島障害者福祉課長","answer":"一方、第二さつき園も同じ品川総合福祉センターが実施をしているということで、同じ法人が運営するということであれば、一体的な運営も可能だろうということで、第二さつき園に籍を置いて、実質的には心身障害者福祉会館で活動をしていただくという方策を考えたです。","voiceIndex":18,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それともう一つは、確認なんですけど、負担については既にデイサービスも９月３０日までは移行期間ということでしたけれども、既に４月１日から１割負担になっていて、それは今回の規定に変わったとしても負担そのものは同じだということで確認させていただいていいでしょうか。","respondent":"西島障害者福祉課長","answer":"通う日数によってはもちろん金額の変動は少しは出てくると思いますが、基本的には大きな変動はなくできるんではないかというふうに考えているところです。","voiceIndex":22,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、先ほどの質問の中で、第二さつき園は稼働率が悪いというお話がありました。今後その原因となることがはっきりされているのか、それとも今後指定管理者制度を使うことによって、稼働率がかなり上げられるような見通しができているのかどうかということをお伺いしたい。","respondent":"西島障害者福祉課長","answer":"ちょっとお聞きしているところでは、９０％ぐらいを超えれば運営としては問題ないというふうに聞いておりますが、９０％に行くように各法人も努力をしていただくと同時に、新事業体系に移ったときに、ではどの事業を選択できるのか。","voiceIndex":24,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"仕組みというか、予算算定等について変更になったということで、これから新しい方法を考えていかなくちゃならないんだろうと思います。教えていただきたいのが、デイサービスが法的にも廃止になったという経緯ですね。それと、今回新しい方法になったという目的というのがどういうものだったのかというのを教えてください。","respondent":"西島障害者福祉課長","answer":"デイサービスは基本的に在宅生活をしている方が毎日在宅ではということで、社会参加的な面も含めて１日そこへ通っていろんな人と触れ合いをしたいという側面と、週に２回ぐらい通ってリハビリという側面がございましたけれども。","voiceIndex":26,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"その辺はちょっと細かくはっきりと区別するということはボーダーも必ず、はざまにかかる人は必ずいるはずなので、そこはきちんと調査をして対処していただきたいなということで、要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほどのご説明の中で、新事業体系まで５年かかるというお話があったと思うんですが、５年の間に区がやっていくという形ですよね。品川区としては、これをどのぐらいの目途で考えていらっしゃるのかという点を教えてください。","respondent":"西島障害者福祉課長","answer":"今日、実は全国課長会がありますので、新しい情報がまた入ってくるんですけれども、国としては５年とは言いながら、できるだけ早く移行してほしいということで、国は国なりの考え方がありますので、ある意味では、どちらが有利か。","voiceIndex":29,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"意見","question":"その辺、円滑な移行をできるようにお願いしたいのと、それからこの条例二つ、施設条例が二つありますけど、今度大もとの条例が自立支援法になったときに、これはやっぱりどこかで一本化していくのかな。もとの条例の部分がありますよね。すぐではないのかもしれませんけど、その辺はどういうふうに考えていますか。","respondent":"西島障害者福祉課長","answer":"心身障害者福祉会館につきましては、心身障害者施策の一つはシンボル的な意味合いで、昭和５２年に設立をされまして、いろいろ設立の経過もございまして、地域との関係も、地域のご協力もいただきながら運営している施設ですが。","voiceIndex":31,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、西大井福祉園は通所更生ですよね。それで、心障会館は通所更生というのもありますよね。この第二さつき園の拡大じゃなくて、かがやき園のほうが通所更生の西大井福祉園の拡大というのであれば、心障会館もこの通所更生の拡大というわけにはいかないのか、そこら辺の仕切りはどうしてそうなるのかということを教えてください。","respondent":"西島障害者福祉課長","answer":"心障会館ですが、心障会館の稼働率は今定員３５人なんですが、稼働率が高いです。９５％をたぶん超えていると思います。","voiceIndex":33,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"よくわかりました。それで、この心障会館のほうは登録が２０人で、利用は大体１日１３人ぐらいだというふうなことと、かがやき園のほうは１０人の５人ぐらいだということなんですけれども、この登録の人数はそのまま全く変わらずに、それとか体制的にも変わらないで、今現に通っている方は基本的には変わらないということで確認させていただいていいのか、このことだけ最後にお聞かせください。","respondent":"西島障害者福祉課長","answer":"基本的に現在受けている、ご本人が希望すれば別ですが、私は通所更生に行きたいとか、あそこに行きたいとか、毎年一定の時期に調査をしますので、本人が希望すればともかく、現時点では現在のいるところで同じサービスを受けるということで考えているです。","voiceIndex":35,"id":"exchange-010"},{"speaker":"三上委員","kind":"質問・要望","question":"つけ加えさせていただければ、基本的な考え方は、要するにこういう障害を持った人たちが、社会で明るくとにかく表に出て生活できる、こういうことが趣旨で法律が改正されているとするならば、やはり、そういった支援体制というものは国がとる部分を含めても、さらに品川区がそれなりの手厚い支援体制をとっていかない限り、非常に難しい部分も個人によってはあるだろうということが考えられますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは法律の規定の中で整理をしなきゃいけないというふうなところの中で、デイサービスが廃止をされるという中での工夫をしながら今まで通ってこられている方がそのまま通い続けるという対応をしていただいているということで賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-012"},{"speaker":"木下委員","kind":"意見","question":"私も賛成いたします。法律の改正で、負担ですとか、どういう形になるか心配していたんですが、区のほうがその分賄うような形でやっていらっしゃるので賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"私どものほうも賛成いたします。やはり、法改正、国の流れによって変わっていく部分があるかと思うんですね。一番大切なのは、利用されている方々がどういう状況であるのか。やはり、自立という意味も当然必要になってくると思いますので、これからのきめ細かい配慮をしていただいて、品川区としてはサポートをできるだけしていただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-014"},{"speaker":"三村委員","kind":"質問・要望","question":"区の障害者施策に対して、今回の法律の変更に対して大変努力されているということは認めるものなんですけれども、自立支援法自体が実際にいろんな支援を受けながら外に出ていこうとするときに、応能負担ではなく、応益負担ということで、実際一番しわ寄せが来ているのは、実際に社会に出ていけるところの人たちに対して一番負担の多い法律になっているということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この条例に対しても賛成です。我が党は、本来自立支援法は、応能負担であるべきだということで、応益負担には反対してきたものですけれども、このことは今回改めて応能負担から応益負担に変わるというふうなことであれば、それは検討するというふうに思いましたけれども、既に４月から応益負担に変わっているということで、基本的には負担割合が変わらないというふうなところで賛成をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか質問させていただきたいんですが。利用時間ですが、朝は書いていないんですが、朝の早朝７時半から９時というのはどうなのかなというところですね。階層がありますので、なかなかしづらいと思うんですが、例えば一般的に１０階層ぐらいと比較して、預かり保育を仮に５時まで預かった場合、通常保育とどのぐらいの差があるのかというのがわかれば教えていただきたいと思います。","respondent":"高橋幼保一元担当課長","answer":"４点のご質問かと思いますが、まず利用時間について早朝には行わないかですが、これを実施するに当たりましては、区立幼稚園の施設を活用するというところでございまして、新たに施設を何かするということではなくて、今ある施設の中でできる範囲ということで。","voiceIndex":57,"id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"そういう場合に、就労している方を考えると、５時というのはちょっと短いかなという感じがするんですね。やはり、最低でも６時、６時半というのが基本ではないかなというふうな感じがするんですが、そうすると、保育園のほうの待機児解消のほうに少し貢献できるかなというふうに思っているんですね。これは幼稚園のほうの側の判断で利用できるという形になるのか、その辺いかがでしょう。","respondent":"高橋幼保一元担当課長","answer":"今お尋ねの２件ですが、幼稚園での預かり保育が５時では短過ぎるのではないか、待機児の解消にはならないのではないかですが、今いろいろな働き方がございまして、幼稚園のほうでも、問い合わせると４人から５人ぐらいはバイトをしている人もいますよという話の中で。","voiceIndex":59,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"わかりました。希望としては、もう少し延びてもよろしいかなという感じはしますけれども、それと最後に、預かり保育ですから、これは保育士はいらっしゃるのか、それとも全く幼稚園教諭だけがこの預かり保育を見ていくのか、やはり、１日過ごすということになると、保育という視点が必要かと思うんですけれども、その辺の体制はどういうふうにされるんでしょうか。","respondent":"古川児童保健事業部長","answer":"したがいまして、３時から５時というのは幼稚園の中での預かり保育の一つの限界である、このように考えております。","voiceIndex":61,"id":"exchange-019"},{"speaker":"三村委員","kind":"質問","question":"現状、公立幼稚園のほうの定員の状況とかを教えていただければと思います。","respondent":"高橋幼保一元担当課長","answer":"３５名でとまっています。平塚幼稚園が４歳、５歳が３５名の定員ということになってございまして、そのほか、二葉幼稚園の年少組が７０名の定員になっているところです。","voiceIndex":63,"id":"exchange-020"},{"speaker":"三村委員","kind":"質問","question":"私がお聞きしたかったのは、４歳のところ、３０人のところを３５人まで受け入れていると、そこのことを言っていただけで、３５名をオーバーしてということじゃなくて、今３０名、本来は区としては３０名のところを３５名まで多く受け入れているというところで、そういう弾力的な運用で何とかそれ以上のオーバー部分のところは、現在のところ出ていないとは思うんですけれども。","respondent":"高橋幼保一元担当課長","answer":"今後もそういった形で親御さんが選択していくというところで、どうしても拡大しなくちゃいけないということでは考えていません。できたら、本当は３５名より少ない学級編成か望ましいかなと考えているところです。","voiceIndex":65,"id":"exchange-021"},{"speaker":"三上委員","kind":"確認","question":"ちょっと一つ考え方だけは確認させてもらいたい。先ほど５時までということだったのかな、その５時以降の延長時間に対しても希望するということについては、そういう今の幼稚園児、在園児を対象とする人たちは今の範囲内の時間だけは延長しますよと、そういう対象の拡大をこの７園において９月と来年の１月に実施しますと、そういう理解でよろしいんですか。","respondent":"高橋幼保一元担当課長","answer":"委員のおっしゃるとおりです。先に説明したように、今ある園でできる限りの預かりをやるというところで、対象者も在園児でやるというところで、そういった中では、今ご確認していただいたとおりです。","voiceIndex":67,"id":"exchange-022"},{"speaker":"三上委員","kind":"確認","question":"そこのところだけ確認させていただきましたので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それともう一つ、現在の幼稚園の職員体制がどういう体制になっていて、預かり保育をやることによって、その体制がどう変わるのかということについて教えてください。","respondent":"高橋幼保一元担当課長","answer":"体制につきましても、先ほど言ったように１４名ということで、幼稚園の体制は園長、それから各学級編成４歳児１人、５歳児１人という３人体制の中でありますので、こちらの体制につきましては、有資格非常勤を入れて、幼稚園の先生と一緒に見ていただくということで。","voiceIndex":72,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、４歳、５歳児で１４名ぐらいと。その４歳、５歳児の１４名を大体一緒に４歳児の先生と５歳児の先生と有資格者の非常勤の方と３名で午後５時まで見るというような体制ということになるんでしょうか。","respondent":"高橋幼保一元担当課長","answer":"今後人数が１４名以上増えることになるようなことが起きましたら、その部分についてはまた人の検討はさせていただきたいと考えているところです。","voiceIndex":74,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それぞれの先生もいろいろ準備があるということで、有資格者の非常勤の方といずれかの先生の２人体制というものはきちんと確保されるというふうなことでいいのかということと、それと５時までとなると、かなり長時間幼稚園で保育が行われるということになりますけれども、休息の問題ですとか、おやつの問題ですとか、長時間預かるに当たっての保育内容というのは。","respondent":"高橋幼保一元担当課長","answer":"それで、３時なり４時ぐらいのおやつは出す予定です。保育内容については、今幼稚園の先生たちがどの部屋を使って預かり保育をするか、今ある施設の中で検討していただいています。","voiceIndex":76,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"先ほどの答弁を含めてですが、この資料の中に目的というところがあって、二葉、台場幼稚園はというふうになっていたものですから、幼保一元化ということで、先ほどのご説明、部長のご説明で趣旨はわかりましたけれども、先ほど課長の答弁の中にも、今後待機児解消も含めてというお話があったと思います。ですから、もうちょっと働いている人も、働き方によっては入れる可能性もあるわけですね。","respondent":"高橋幼保一元担当課長","answer":"それにつきましては、やはり、１１月に幼稚園のお子さんの募集があります。その部分において、預かり保育を教育課程、教育時間終了後に５時まで行っていますよということは明記してまいりたいと考えているところです。","voiceIndex":78,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"今保育園、幼稚園の幼保一体化ということで進んでいると思うんですね。これも考え方によっては、幼保一元化の一部ではないかなと私は理解していたんですが、そういう形でよろしいんでしょうか。ですから、ただ単に在園児ということの枠ではなくて、もっと広い意味で幼保一元化に向けての一つの方法ですよというふうな見方でよろしいんでしょうか。","respondent":"高橋幼保一元担当課長","answer":"幼稚園については、私立幼稚園がやっている今時点でできる、施設の中でできる預かりですので、幼稚園の資源を活用した預かり保育ということでとらえていますので、広く見た意味での幼保一体につながるものとは今のところ考えてございません。","voiceIndex":80,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"私立幼稚園がやっているから預かり保育をやるんだということではないとは思っていたんですが、やはり幼保一元化という形でカリキュラム、それから制度的なところも踏まえて今後品川区の幼稚園、保育園のあり方を考えていこうという流れの一つなのかなというふうに理解していたんですが、そういう考え方ではなく、あくまでもこれはサービスの一環だというふうなとらえ方でよろしいんでしょうか。","respondent":"古川児童保健事業部長","answer":"今後この幼保の流れが、例えば認定こども園という国の制度がまたできてきますけども、基本的にはこの三つの制度の中で、それぞれの制度をどう利用者がご自分のお子様によりよい教育環境、あるいは保育環境としてとらえていくか。","voiceIndex":82,"id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１点目は予算のところで、どのくらい予定をしているのかというところと、保育園に入れなくて幼稚園に預けたら仕事に出たいわという方がかなりいらっしゃるというところでは、一つの受け皿になっていくと思いますけども、子どもにとってどうなのかというところで、幼稚園における長時間保育であると先ほどご答弁がありましたけれども、子どもにとっての条件整備の基準があるのかどうか。","respondent":"高橋幼保一元担当課長","answer":"予算についてというと、今年度の予算については、実施時期が９月と１月ですので、１,５００万円程度を予定しています。","voiceIndex":84,"id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"予算は１,５００万円、今年度のところということなんですけど、人件費以外に整備費も若干含まれているんですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"我が会派として、目的の中に公立幼稚園における預かり保育、就労支援という問題、その充実、拡充を図るという点で賛成をしてまいります。その中で、ただ、先ほどご答弁にもありましたが、延長された時間の中の先生に対する負担とか、その辺で園児の安全ということだけは十分注意をしていただきたいということをつけ加えさせていただいて、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-032"},{"speaker":"三上委員","kind":"意見","question":"私も賛成いたします。現状の区有財産をどのように有効活用するかという目的にあっては、こういった形で使われていくということは大事なことだと考えています。これが将来的にいろんな形で発展していくということは、これからの問題でありまして、現状、そういった考え方でいくんだということであれば賛成したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"就労支援の充実、拡充というふうなところでは、やはり、必要だというふうなところで賛成です。ただ、子どもたちにとっては長時間保育という状況になりますので、職員の体制や子どもたちへの配慮を十分お願いをしまして、賛成といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-034"},{"speaker":"木下委員","kind":"質問・要望","question":"本当に就労支援の充実を図る、今まである現状の施設ですとか体制を生かした中で、できる限りのことをやるということだったんですけれども、本当にこれは要領の中で、幼稚園は、何時間しかやっちゃいけないということを書いていないということであれば、先ほどの早朝ですとか、あと時間の延長ですとか、そういう部分も施設というよりも、人の問題という部分も考えられるのかなと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"私もこの条例については就労支援の拡充ということでは賛成をいたします。やはり、午後の生活ですね、１日過ごすわけですので、やはり、人の問題もあるでしょうし、それから保育という観点からどういう内容であるべきなのかということは今後つくり上げていっていただきたいなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-036"},{"speaker":"三村委員","kind":"意見","question":"多用な働き方の支援ということで、この施策には賛成なんですけれども、先ほど言ったみたいに、保育園から異動してきたりとかといったことで、今まで幼稚園で受け入れられていた子どもたちの受け皿がなくなってしまうようなことだけはないように、どこの保育サービスも利用できていない、定員がオーバーしちゃったような場合は、どこの保育サービスも利用できていない子を優先するとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"議員提出第４号議案、品川区保育の実施等に関する条例の一部を改正する条例についての提案説明をさせていただきたいと思います。この３点です。１は９％引き下げの中身が書いてあります。これを無料にするために必要な予算が６００万円、年間ベースで総額１億円、そして、施行日が平成１９年１月１日ということですので、今年度分としては２,５００万円という予算が必要だということです。","respondent":"須藤委員長","answer":"提出者を代表いたしまして、鈴木ひろ子委員から説明がありました。この件に関しまして、ご質疑等ございましたら、ご発言をお願いいたします。","voiceIndex":97,"id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この改正はたしか平成１６年１０月でしたよね。その改定の際、たしか平成１６年第１回定例会で議案提出されたと思ったんですが、そのときの改定の理由について、もう一回理事者からちょっと改定の根拠みたいなものをご説明いただきたい。たしか公平性という観点から出たと思ったんですが、そこら辺についてもう一回ご説明いただきたい。","respondent":"小林保育課長","answer":"区の保育事業は、この間０歳児保育の充実のほか、各種のサービスを利用者の視点に立って進めてまいりました。他方、子育て環境の充実を考えるとき、今ご指摘のございました在宅子育て家庭への支援との公平性、また、子育てを支える区民の理解にも配慮する必要があります。","voiceIndex":99,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"ちょっと理事者のほうにお聞きしたいんですが、この保育料が改定になった後、例えば滞納率がかなり上がったりとか、あとは保育料が高くなって困るとかという苦情であるとかご意見とか、そういうのはいかがだったんでしょうか。","respondent":"小林保育課長","answer":"ただ、６カ月の周知期間を経て実施した結果、それが原因で徴収率が下がった事実はございませんし、ご負担については一定のご理解がこの間得られたものというふうに自負しています。","voiceIndex":104,"id":"exchange-040"},{"speaker":"三上委員","kind":"質問・要望","question":"２の第二子を半額にした場合、対象は１９０人という数字を限定した上で年間２,０００万円、それから３番目としては、第三子以上の児童、対象は２６人、この子どもたちを無料にするということになって６００万円という数字について、共産党が試算した数字と区のほうが現実に毎月徴収しているわけですから、この具体的な数字がこの数字でほとんど合っているのかどうかということについて。","respondent":"小林保育課長","answer":"もちろん人数につきましては、秋に向けて若干増えてまいりますので、実際の影響額はこれを若干上回るものと想定されます。","voiceIndex":106,"id":"exchange-041"},{"speaker":"三上委員","kind":"質問・要望","question":"この添付されている資料のいつも別表第１で、こういった料金の改定のときに必ずこういう表で計算されるんですけれども、私は判断する上で、いつもこの数字でいっちゃうとどうなのかなという疑問がいつもついて回るのは、要するにこの所得がどれだけあったのかというこの数字でやっていった場合に、年間所得というのがどれぐらいの金額になっているのかという。","respondent":"小林保育課長","answer":"最高階層はＤ２１ですが、その前のＤ２０、７５万円から９０万円の所得税を納めになっている階層におきましては、給与収入ベースで申しますと、１,２６０万円から１,４４０万円ぐらいの範疇にはまるのかなと考えております。","voiceIndex":108,"id":"exchange-042"},{"speaker":"三上委員","kind":"意見","question":"もう一つ、昨年か一昨年、厚生委員会で出された資料というのが何かあったと思うんだけど、この改正問題について、その資料というのを委員長、よろしければ、ちょっともう一度お配りいただければありがたいんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-043"},{"speaker":"三上委員","kind":"質問・要望","question":"どなたも質問しないので。この基準のＣ３という項目を見たときに。かつ、じゃあ受益についてということを考えていったときに、在宅子育て家庭の方は、受益額というのが６０万２,８１４円、比べて、保育園利用者は８３０万７,０００円という額の相違というのがとれるわけですけど、要するにここらあたりについての区の受けとめ方、保育料についての考え方とあわせて、ちょっとご説明いただきたい。","respondent":"小林保育課長","answer":"先ほどお尋ねがございましたように、保育料の改定につきましては、在宅子育て支援との公平性、負担をいだたく区民の納得ということを配慮しながらという形で方針をとってまいりました。","voiceIndex":117,"id":"exchange-044"},{"speaker":"三上委員","kind":"意見","question":"そうしますと、今在宅の皆さん方が受けている応益という部分については非常に少ないと、そういった確かに子育てという面から考えると、夫婦ともに働いていかなきゃならないという環境と比べるという、それは別としても、やはり家庭で育てていく人たちの応益部分については、もう少し拡大する必要があるという考え方はしていっていいということでいいわけですね。","respondent":"小林保育課長","answer":"ご指摘のとおり認識しています。","voiceIndex":119,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"そういうものには加味できないというところはあると思うんですね。ですから、金額ベースで言うと当然この差が出てくるのは当たり前なんですよ。これは働いている側とすると、いや、これだけでは評価はできないんじゃないかなというふうに思うんですが、その辺はいかがですか。どういうふうにこの数字を見ていけばいいのかなと思うんですが、いかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっとずれて申しわけないんですが、先ほどそういう形、数字だけを上げて、今保育料の話があって、保育料に対する施策の中の一端だと思うので、その考え方、この資料が出てきた関係上、これの読み方というのをもう少しご説明いただきたいなと思っているんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"意見","question":"平成１６年１０月に改正したときの在宅子育て家庭との公平性という問題から考えますと、今回の案件につきまして、当然子育て支援ということは十分承知しておりますし、我々の会派でもそのことは常に訴えておりますが、この議員提出第４号議案に関しましては賛同できないということで、我が会派の態度です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-048"},{"speaker":"三上委員","kind":"意見","question":"考え方としては、一昨年保育料が値上げされたと、こういった流れの中で、利用者の方からはそれに対して理解されているという部分についてのものが全体として受けとめているとするならば、それは確かに値段が安くなるということについては、だれでも喜ぶのは当たり前なんですけども、こういった税をどのように配分していくかという考え方の中にあって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-049"},{"speaker":"木下委員","kind":"質問","question":"私どもも賛成できないという立場です。これは前にも議論されていたところじゃないかなと思うんですよね。ですから、そういうのも含めまして賛同できないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"この議員提出第４号議案に関しては賛同できません。理由としては、この引き上げの際に、私たち独自でいろいろと調べてみたんですね。それから、いろんな要望等をお聞きした限り、確かに保育料を上げることに関しては、不満はあると思います、高くなるわけですから。今回の引き下げについては賛同できないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-051"},{"speaker":"三村委員","kind":"意見","question":"その一方、待機児という形で保育園を利用できない方、したいのにできない方については、一切そういった支援を受けていなかったり、受けていたとしても、ごくごく薄いものであったりということで、やはりまずお金をかけるべきは待機児解消というところで優先順位をつけてきたというふうに考えております。なので、こちらの引き下げについては賛成をしませんということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"提案をさせていただいた立場で、今審議の中でさまざま出された意見もありますので、改めて意見を表明させていただきたいと思います。今在宅家庭への支援ということに対しては、私たちももっともっと充実すべきだというふうに思っています。ただ、子育ての家庭に対して、在宅と保育園というのをこっち、あっちというふうに。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"はい、わかりました。最終的に子育てに対しての予算は、世界に比べても日本の子育ての予算はかなり低いという状況にありますので、在宅の子育てももちろん、そして保育園に通う子育ての予算ももちろん、そして、少子化が大変未曽有の状況になっている中、危機的な状況になっている中で改善させるためにということで提案をいたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-054"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域生活支援事業というところでは、先ほど課長のほうから説明があった今回の自立支援では、安定的な財源の確保というところが大きく入ったということですけれども、今回の地域生活支援事業に当たっては、補助金の制度というふうなことで、この補助金の制度も一般財源に繰り入れられるというふうなことになるということで聞いているんですけれども。","respondent":"西島障害者福祉課長","answer":"１点目のお尋ねですが、地域生活支援事業の現在で言えば品川区はどのぐらい予算化しているかですが、新しく地域生活支援事業になったときに、どういう組み立て方になるかにもよりますが、ちょっと大ざっぱな数字でお話し申し上げますと、相談支援。","voiceIndex":143,"id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そのところで、区としてはこの財源は今までどおりしっかりと確保して、今までどおりの施策はそのまま続けていくというふうなことで減らすとか、または今までよりも負担を増やすとか、そういうふうなところについては考えていないということでよろしいんでしょうか。","respondent":"西島障害者福祉課長","answer":"地域生活支援事業そのものについて現在検討中ですので、個々の事業についてどうこうというのは現段階ではお話しできませんけれども、先ほどお話ししましたように、現行のサービス水準は維持をしていきたいというのが基本的な考え方です。","voiceIndex":145,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"視覚障害の方でも６６名、それから知的障害の方でも１１名という利用で、あまり増えていないような状況なんですけど、ここについては、もっと使いやすくして、もっと利用しやすくして使えるようにしてほしいという声も障害者の方からいただいているんですけれども、このガイドヘルパーについては、地域生活支援事業をこれから計画するに当たって、見込みとしてはどのように考えられているのか。","respondent":"西島障害者福祉課長","answer":"このガイドヘルパーというのはどういう形でもっていくのかというところは、先ほどお話ししましたように、地域生活支援事業全体の枠組みの中で、全体の予算の配分あるいは利用の方法も含めて、総合的に検討して、またお示しをしたいというふうに考えているところです。","voiceIndex":147,"id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このガイドヘルパーに関しては、視覚障害の方からも前にお話をお伺いさせていただいて、もっと社会的な参加などにももっともっと使っていけるようにしていただきたいし、また、知的障害のガイドヘルパーももっともっと使いやすくしていただけたら利用したいというふうな声を聞いていますので、ぜひそういう拡大の方向でご検討いただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-058"},{"speaker":"木下委員","kind":"質問・要望","question":"午前中の品川区立知的障害者援護施設条例の一部を改正する条例におきましても、そういう形で費用負担がかかるという中で、逆に平均的な部分、逆に費用が下がったりしておりますというご説明がありましたように、区のほうとしては、それなりの支援というのを考えていただけるものだと思っているんですが、いかがでしょうかということと、確定されていないものに対して。","respondent":"西島障害者福祉課長","answer":"先ほど私、日常生活用具給付事業の数値目標を定めてくださいという２番目の項目ですが、これはちょっと請願者の趣旨がよく理解できない部分でございまして、日常生活用具につきましては、申請があって、条件が整えば支給していますので。","voiceIndex":150,"id":"exchange-059"},{"speaker":"木下委員","kind":"質問・要望","question":"本当にそういう意味でお話をお聞きしますと、品川区はそれなりにかなり努力をしていらっしゃるということですね。本当にまだまだいろいろ確定してから、いろいろな問題等、費用の問題等出てくるかと思いますけれども、そういう方々に対して応分なご配慮のほう、よろしくお願いしまして、質問を終了させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-060"},{"speaker":"三村委員","kind":"質問・要望","question":"先ほどこの法律の中で、就労支援を促進していくというようなお話があったんですけれども、実際にこれからどういう支援をされていくのか、また、品川区で障害の種別によって、知的だとか身体とか、いろいろ障害の種類があるかと思うんですけれども、どういった方が品川区の中で雇用されていて、身体の方が働かれているのはよく日常目にしているんですけれども、知的の方とかの状況を知らないんですけれども。","respondent":"西島障害者福祉課長","answer":"現在もハローワークと連携をとっておりまして、二月に１回ですけれども、六本木にあります品川区のハローワークのほうからこちらのほうに来ていただきまして、就労相談を実施しています。現在、知的と身体の関係を中心に就労支援センターで就労への取り組みをしています。","voiceIndex":153,"id":"exchange-061"},{"speaker":"三村委員","kind":"質問・要望","question":"福祉工場などの話が出たんですけど、そういった部分でされているのは存じているんですけれども、普通の区の庁舎内の仕事ですとか、そういった部分でという意味で、今度自立支援法なんかだと、実際に地域の場でということだったので、こういう庁舎内で、そういう福祉工場をつくっているから、そこで雇用しているからだけではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-062"},{"speaker":"三上委員","kind":"確認","question":"実際問題、ご相談されて受けとめていれば、こういうことなのかということがご説明にあったのかわからないし、紹介議員もここにだれもいませんから、そのことについて聞くわけにもいかないので確認できませんけれども、そういった部分について、もうちょっと何らかのそういった相談事というか、話し合いの場というのがあれば、そこらあたりはクリアされているのではないかなと、こういうふうに受けとめると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-063"},{"speaker":"三上委員","kind":"質問","question":"そのやりとりがどういうような形でやっているのか、簡単でいいですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-064"},{"speaker":"三上委員","kind":"質問・要望","question":"そうすると、今この請願代表者の方を別として、視覚障害者協会と表現したらいいんでしょうか、そちらの皆さんからは同趣旨の要望書が出されたということで、それに対しては区としてはどういうふうにお答えされたんでしょうか。","respondent":"西島障害者福祉課長","answer":"ただ、この従前のサービスを下回らないようにというところの部分については、再三議会等でもお答え申し上げていますように、現行のサービス水準は下回らない形で自立支援法に対処してまいりたいというふうに考えてありますので、その辺については明確にお答えするつもりです。","voiceIndex":162,"id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この自立支援の問題では、負担がどう変わっていくのかというのが大きな問題だと思うんですが、今課長のほうから、例えば日常生活用具の給付は、この事務事業概要にも出ているわけですけども、平成１７年で１３９件というふうなことでご報告ありましたけど、現在日常生活用具の給付の費用負担がどうなっているのかということを一つ教えていただきたいのと、それから。","respondent":"西島障害者福祉課長","answer":"日常生活用具は、先ほどお話ししましたように、地域生活支援事業総体を決めていく中で検討していく内容ですけれども、この品目につきましては、今までは東京都との協議が必要でしたけれども、これから区の単独事業になりますので、現在使われているもので不要なものは落とす。","voiceIndex":164,"id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"この日常生活用具に対しての自己負担というのは、今度の地域生活支援事業が１０月から開始するに当たっては、今までと同じ考え方でいくということでいいんでしょうか。そこのところだけちょっと確認をお願いします。","respondent":"西島障害者福祉課長","answer":"地域生活支援事業につきましては、どのような事業を、どのような形で展開するかということを総合的に検討してまいりますので、その中で負担についてもどういう割合でやっていくのかということについて検討していきたいというふうに考えてありますので。","voiceIndex":166,"id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"じゃあ、先ほども要望で申し上げましたけれども、改めてこの請願にあるようにガイドヘルパーにしても、それから日常生活用具にしても、今までどおりの応能負担というふうなことで、負担が増えないようなやり方をぜひとっていただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-068"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"それを一つ伺いたいのと、ガイドヘルプサービスに限ってなんですが、今利用されている方が３月までの支援費制度のときに、どのくらい負担をされていて、その方が４月以降自立支援法になったときに、この負担割合がどう変わってきたのかというのをちょっと具体的にわかったら教えていただきたい。","respondent":"西島障害者福祉課長","answer":"ですので、１０月以降については、では区としてどうやるのかというお話につきましては、他の方のサービスの負担との均衡とか、全体的な、もちろん区単独でやるといいましても、財源の問題というのは無視はできませんので、総合的に勘案をして、負担の割合。","voiceIndex":170,"id":"exchange-069"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"すみません、２,５００万円余というところの、国と都と区の割合がどうなっているのかちょっとわからないので、そこを教えていただきたいのと、あとガイドヘルプサービスに関しても、現状では３％ということなんですけれども、金額的に幾らぐらい負担をしているのかというのをちょっと教えていただきたいと思います。さっきのところを答えていただきたいのと、新しい機械がたくさんできていますよね。","respondent":"西島障害者福祉課長","answer":"後段のところはご意見ということで、負担割合のところだけでよろしいでしょうか。現在は、支援費制度の枠組みですので、国２分の１、都４分の１、区４分の１です。","voiceIndex":172,"id":"exchange-070"},{"speaker":"飯沼副委員長","kind":"質問","question":"さっき３％のところで、実際に幾らが幾らに変わったのかというお伺いをしたので、そこがわかったら。","respondent":"西島障害者福祉課長","answer":"ですから、１０時間お使いになれば、４５０円、２０時間お使いになれば９００円、そのような数字になるんではなかろうかというふうに思います。","voiceIndex":174,"id":"exchange-071"},{"speaker":"三上委員","kind":"質問・要望","question":"私は結論を出すことについてはやぶさかじゃありませんが、ただし、先ほどの質疑のやりとりの中から、視覚障害者協会、こちらのほうから出されている要望について今取りまとめているという動向があるとするならば、私はそれがまとまった段階で判断してもいいのかなと。ですから、本日のところは継続しておいていただいてもいいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-072"},{"speaker":"木下委員","kind":"意見","question":"私、三上委員と同じように継続でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":181,"id":"exchange-073"},{"speaker":"西本委員","kind":"質問・要望","question":"私のほうとしては、今日決を採らせていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-074"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私どもも視覚障害者の団体の方ともお会いして、要望もお聞きをしております。その上で、品川区、どっちかというと先進的な障害者施策をとっている中で、現行を維持したいという気持ちも十分理解できる部分もあると思うんですが、ただ、その上で、私どもとしてはこの請願の趣旨を理解するということで、趣旨採択ということで、うちの結論とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-075"},{"speaker":"三上委員","kind":"意見","question":"結論を出すということでありますので。先ほど来、日常生活用具給付事業の数値目標ということについて、非常に不明であるという点から考えて、どう努力したらいいのかということについて、これは区の理事者の皆さんにたがをはめるというわけにはいかない。こういうことであるならば、ぜひいろんな状況を判断していただいて、ご努力いただくという意味から、趣旨採択ということでお願いしたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":187,"id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そんな中で、品川区はこれからガイドラインに沿って検討も進めていくというところですけれども、ぜひこの請願の方の趣旨をくんでいただいて、ご検討いただきたいというふうなところで、今日の請願に対しては、採択ということでお願いしたいと思いますが、趣旨採択ということで一致できるんであれば、趣旨採択でも結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-077"},{"speaker":"木下委員","kind":"意見","question":"私としましては、趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":189,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"この請願を読みますと、請願の理由のところを読みますと、非常にこれからの制度ということも含めまして心配されているんだろうなというふうに思います。項目のほうも、もう少し具体的なところが欲しかったかなという部分もありますけれども、お考えのほうは十分に理解できますので、これを踏まえて、これからの制度づくりをしていただきたいなというふうに趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-079"},{"speaker":"三村委員","kind":"質問","question":"今回、請願の趣旨の１のところ、現行水準維持というところで、品川区が大変努力されているとは思うんですけれども、実際に制度の安定的な運用という面では、都ですとか、国ですとかへの働きかけや何かが必要だと思いますので、できれば採択というふうに思っているんですけれども、今まで皆様のご意見をお聞きしましたところ、趣旨採択であれば一致できるかと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-080"}]},{"id":"topic-03","title":"平成１８年請願第６号、東品川３丁目愛宕倉庫跡地に開設予定のホテルの営業許可に関する請願","agenda":"平成１８年請願第６号、東品川３丁目愛宕倉庫跡地に開設予定のホテルの営業許可に関する請願","exchanges":[{"speaker":"三村委員","kind":"質問","question":"先ほど学校ですとか、保育園ですとかの意見照会をされたということだったんですけれども、どういった意見が上がってきているのか、その内容について、教えていただけますか。","respondent":"高橋品川区保健センター衛生課長","answer":"今のところ、６カ所意見照会しております。意見照会している場所につきましては、都立八潮高校、区立城南小学校、区立城南幼稚園、それから区立東品川公園、私立八潮幼稚園、私立どんぐり保育園です。今のところ戻ってきているのが５カ所でございまして、基本的には問題ない。","voiceIndex":198,"id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の説明で、ちょっとよくわからなかったところがあったのでもう一度確認させていただきたいんですけど、営業許可を与えないことができるというところで、構造がだめだというふうなことと、設置場所が適さないということと、１００メートル以内に学校等の教育施設があるというふうな場合は、営業許可を与えないことができるというふうなところなんでしょうか。","respondent":"高橋品川区保健センター衛生課長","answer":"その１００メートル以内の教育施設等ですが、清純な環境が著しく害される恐れがあると認めるときということになっておりまして、先ほどの設置場所が公衆衛生上不適当であるとか、構造設備が政令の基準に適用しないということとは区別されております。","voiceIndex":200,"id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、区としては学校等が１００メートルにあって、清純な環境が著しく影響を受けるというところということでは判断できないということで考えているということですか。","respondent":"高橋品川区保健センター衛生課長","answer":"著しく清純な環境が害されるおそれがあると認めるときというのは、例えば風俗的営業が明らかなときとかということで、著しくということになっておりますので、その辺については考慮いただきたいと思います。","voiceIndex":202,"id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その営業許可を与えないことができるというそのところはわかりましたけども、品川区としては、そういう著しく清純な環境が侵されるというふうなことではなくても、この指導要綱の指導基準に沿えば、概ね１００メートル以内に教育施設がある場合は、原則として旅館業を認めないとするものということで、要綱の指導基準というふうになっていると思うんですけれども、ここに対しては。","respondent":"高橋品川区保健センター衛生課長","answer":"指導基準ですので、この要綱の趣旨を業者のほうに説明しまして、ご理解をいただくということで翻意を促すということをやってきたものです。","voiceIndex":204,"id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それが１点と、それから、ここの請願のところでは、品川区が幾度も指導したにもかかわらず申請書が出されましたというふうなことで、先ほども課長のほうから指導を１月から行ってきたというふうなことだったんですが、住宅課の事前協議の日程と、それから保健所のほうの指導というのがどういうふうに日程的にされてきたのか、また。","respondent":"須藤委員長、高橋品川区保健センター衛生課長","answer":"所管がちょっと違うところがあるので、わかる範囲のところで結構です。逆に変に説明しちゃうと誤解を得ますので、今、衛生課長のほうでおわかりになる範囲でお答えを願いたいと思います。というのは、同じ物件に対しまして、何人かの方がいらっしゃいましたので、来るたびに指導要綱を指し示しまして、具体的な説明でぜひこの辺の考えをお願いしたいということで、区の立場、いわゆる区民の立場を説明したところです。","voiceIndex":206,"id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は住宅課のほうとも連携をとってぜひ進めていただきたいなというふうに思うんですけれども、それとあわせて、区として今回のこのホテルについて、この指導要綱では、一般的な旅館業というふうなことで定めていますけれども、区としてはこの「スーパーホテル」というホテルをどういうホテルだというふうに認識されて、そして、できればそれを取りやめてほしいということで指導されているのか。","respondent":"高橋品川区保健センター衛生課長","answer":"私のほうでちょっとインターネットで調べてみたところ、全国５８店舗を展開するビジネスホテルということで、宿泊のみに特化したということで、自動チェックイン機を使って人件費を抑えて、低価格の宿泊場所ということで展開しているホテルというふうに考えております。","voiceIndex":209,"id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこら辺のところの認識についてもちょっとお伺いしたいんですけども。そういうふうなところについては、区としては認識されていますでしょうか。それで、本当に地域のお母さん方も、子どもたちのもしもたまり場になったりとか、それからまた、子どもたちがその被害に遭ったりしたら大変になるというふうなことで、かなり心配をされていますけれども、そういうところに対してのご見解はいかがでしょうか。","respondent":"高橋品川区保健センター衛生課長","answer":"ホテル営業の検査のときにつきましても、宿泊名簿等につきましてはチェックの対象になっていますので、その辺については、今後も見守っていきたいと、もし営業許可をして、営業開始になれば、そういうことになっていくかと思います。","voiceIndex":211,"id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、やっぱり品川区に来たら、品川区の要綱を守ってくださいというふうなことで、ぜひ強力に指導していただいて、品川区がこんないかがわしい疑いのあるホテルを地域のこれだけ多くの方が心配をして、子どもたちの環境を守りたいというふうに言っている中で、きちんとした立場で指導をして環境を守っていただきたいというふうに思うんですけど、いかがですか。","respondent":"谷田部健康課長","answer":"それと同時に、私ども清純な環境を維持していくためには、やはりこういうような請願が出されているという事実も踏まえて、これは行政指導の中で相手側に伝えていくべきものだろうというふうに思ってありますので、今回このような請願の結果等を踏まえまして。","voiceIndex":213,"id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、地域でこれだけの大きな声になっているということと、品川区がこれだけの要綱を持っているということと、このホテルがこういうような実態だというふうなことを踏まえて、ぜひ地域の皆さんの要望に沿える形でどうしてもよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-089"},{"speaker":"三村委員","kind":"確認","question":"今行政指導で伝えていくというようなお話だったんですけれども、最初に１月に業者が来たときに説明をされたということだったんですけれども、業者というのは具体的にどちらなのか。平成１８年５月２４日、品川区保健センター衛生課に対し、このような事実があったのかを確認いたしました。","respondent":"高橋品川区保健センター衛生課長","answer":"現在につきましても、住民の方の要望、また区のほうにも要望が出されておりますので、その辺については、随時日本開発のほうに説明をさせていただき、また翻意できないかということで指導をしています。","voiceIndex":216,"id":"exchange-090"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひ、その際に間に入っている会社だけではなく、その先にどういった説明をされているか、その辺の確認のところもきちんとしていただきたいと思います。先ほど説明会の話があったんですけれども、３回目のときに出席をしたんですね。業者の方は、区の行政指導には従いますというふうにおっしゃっておりましたので、ぜひきちんと区の意向を業者のほうに伝えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-091"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ここが現状の、まだ品川はないですけど、ほかのところで、こういう名簿をそろえているかどうかというのは、確認を事前にすることはできないんでしょうか。この部分で引っかかっていれば、既に品川のこの旅館業法でおろすことができなくなってくる可能性もあるんではないかと思うんですが。","respondent":"高橋品川区保健センター衛生課長","answer":"厚生労働省のほうで宿泊者名簿の設置を通知でかなり出しています。","voiceIndex":219,"id":"exchange-092"},{"speaker":"鈴木（真）委員","kind":"確認","question":"何人か指導要綱を確認に来たというお話があった中で、その方たち、会社の名前は先ほどおっしゃったから、当然会社からの依頼を受けてきているんでしょうけど、すべて委任状ですとか、この方は本当に資格を持って、ちゃんとその先へ伝わっていったのかどうか、そこら辺の確認はとられているんでしょうか。","respondent":"高橋品川区保健センター衛生課長","answer":"委任状につきましては、コンサルのところからは写しをいただいております。ただ、この委任状を提出しないと、この申請書を受け付けないということではございませんが、今のところ委任状を確認しております。","voiceIndex":221,"id":"exchange-093"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば、要綱をもう一度、要綱で出ている部分だから、それ以上やりようがないのかもしれないけど、ペーパーベースでこの辺を指摘しておくとか、そういうことはできないんでしょうか。","respondent":"高橋品川区保健センター衛生課長","answer":"それと、先ほどペーパーのものなんですが、行政指導をしたときに、相手方からぜひこのところについては紙での提出をお願いしたいということになれば、この行政の中の情報提供の中にも相手方から要求に沿ったときには。","voiceIndex":223,"id":"exchange-094"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"行政として、法律を執行していく立場とさっきご答弁がありましたけど、その中で、これからも指導基準ですとか要綱の、殊に第４条２項ですか、地域住民との間のトラブルの解消というのは、非常に大きなこれからの課題になっていくと思うんですよね。この上で、この辺のところ、行政指導を続けていっていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-095"},{"speaker":"西本委員","kind":"質問","question":"幾つか質問したいんですが、品川区の旅館業の営業許可に関する指導要綱の中に、安全面とか、あとセキュリティの問題とか、先ほどちょっとフロントの設置が義務づけられているというほかの情報だと思うんですが、そういうのがあったんですが、品川区にはそういうセキュリティに関する規定みたいなものはないんでしょうか。","respondent":"高橋品川区保健センター衛生課長","answer":"セキュリティという問題ではないんですが、指導要綱の中にも、フロント、帳場を通る構造とすることということとか、利用者との対応に使うフロント、帳場等は営業者と利用者がお互い上半身を見せる構造であることとか、著しく羞恥心を与えるような構造設備を避けることとか。","voiceIndex":226,"id":"exchange-096"},{"speaker":"西本委員","kind":"確認","question":"そこまで区として安全ですから、地域の安全を守らなければいけない、それから子どもたちが頻繁に通っているという中では、通行も子どもたちもたくさんある、それから概ね１００メートル以内に教育施設があるということでは、風紀の問題もそうですけれども、セキュリティの問題、安全面の問題というのをもう少し踏み込めないんだろうかというふうに思うんですけれども、いかがでしょうか。","respondent":"高橋品川区保健センター衛生課長","answer":"先ほどフロントの設置ということでは、図面では、入口からすぐ目の前、入口に入るとすぐ目の前がフロントという構造になっておりますので、その辺については安全かというふうに思います。","voiceIndex":228,"id":"exchange-097"},{"speaker":"西本委員","kind":"確認","question":"その変えていることによって、当然人件費なんかも削減して安くなっているという構図だと思うんですが、そういう仕組み的なものもきちんと確認をした上でセキュリティはどうなんだろうかというところまでお聞きになることができるんじゃないかなと。将来的にはどういう方向に持っていくつもりなのかということは確認しながら、幾らでも指導はできる範疇ではないのかなと思うんですが、いかがでしょうか。","respondent":"高橋品川区保健センター衛生課長","answer":"セキュリティの問題と図面との関係ですが、ちょっとこれに当たりまして、私「スーパーホテル」の都内にありますホテルを２カ所視察というか、見学に行ってまいりました。","voiceIndex":230,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問・要望","question":"下手をすると、努力義務なので、話し合いに応じなくてもいいというふうに考えがちな部分があってはいけないので、ですから、やっぱり気持ちがわかってもらえるように、やはり、住民側の要求があった場合には、きちんとそれに応じて話し合いを続けていって、納得いく形で進めていただきたいという指導をぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-099"},{"speaker":"三村委員","kind":"質問・要望","question":"ただ、この会社の場合は、現状はお客さんの多い時間帯はフロントに人はいるけれども、将来的には自動チェックインシステムでテレビカメラで確認すればというような社長の「上質サービス企業に迫る」というようなコメントの中で、人を配置しなくてもできるようにしていきたいだとか、あとは２４時間チェックインが可能にしていきたいとか、そういったことも書いてあるんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-100"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"もうちょっと担当課だけじゃなくて、もうちょっと地域の安全、安心というのは品川区の掲げているところですから、どう区の各部署のところで知恵をあわせたら、ここのところがとめられるのかという知恵をぜひ出し合っていただきたいと思うんですが、部長になるでしょうか、ご答弁、よろしくお願いします。いかがでしょう。","respondent":"谷田部健康課長","answer":"現在、現行法の体制の中で考える、私ども旅館業法の許可という部分でしか今回相手方に対する計画の変更を含めた地域住民の皆さん方の意向がどの程度相手方に伝えられるかといったら、この法律でしかない。","voiceIndex":234,"id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこの業者がどういう業者なのかということを見ることがすごく大事なんじゃないかなというふうに思うんですね。そういうふうなところで、ぜひ住宅課とも連携しながら、そういう不備のほうもないのかどうなのかというのも精査をして、連携してぜひ要綱を守ってここのところからは撤退をしていただくというふうな方向でぜひ強力に進めていただきたいという要望を最後に申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-102"},{"speaker":"三上委員","kind":"意見","question":"要するに、教育施設については、学校関係が受けとめている考え方がどういうふうに受けとめているかということと、そういう学校施設があるから新たな建築物を建てちゃならんということにはならない。その建築物のあり方としてどうなのかということが近隣の皆さん方が受けとめていることであって、だから、そこのところの違いというのを私はちょっと感じているところなんですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":237,"id":"exchange-103"},{"speaker":"三上委員","kind":"意見","question":"私は本日のところは継続していきたいなと考えています。一つはやはり、「スーパーホテル」というもの、そのものが多少なりとも理解してきたと思っていますけれども、現実どういうものなのかということを１００％承知しておりませんので、それについての判断はちょっと本日のところはできないということで継続にしていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":240,"id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は結論を今日出していただきたいと思います。というのも、こういうところでは、どんどん進んでいくというふうなことになっていきますので、早いうちに結論を出して、業者に対してもそれが住民の側からの力になるような形で今日結論を出していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-105"},{"speaker":"木下委員","kind":"意見","question":"三村委員が説明会に行った際に、業者のほうが行政のほうのお話、指導というのは聞きますよというふうに言ったと先ほどお話があったように、本当に聞くかどうかはわからないんですけれども、そういう地域住民の方々の懸念の部分を本当に聞いてくれるかどうなのか、区のほうからそういう住民の声を業者のほうに伝えていただいて、あと業者のほうがどういう対応をするのかというのはまだわかりませんので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":242,"id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"私は本日結論を出したいと考えています。それは時間がないと思うんですよね。ですから、やはり後押しするという意味も含めますと、やはりここで一度決を採らせていただいてという時期かなというふうに思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-107"},{"speaker":"三村委員","kind":"質問・要望","question":"私のほうでも、やはり今日決を採っていただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":244,"id":"exchange-108"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"基準の中の、これは第４条の２項に出てくる地域住民とのトラブルという問題、また３項の中の地域住民の生活環境の悪化を未然に防ぐ、これは実際どこまで悪化というのはわかりませんけど、その悪化という不安を持っていることを業者に対してこれからも行政指導という形でしていただいて、翻意を、ひるがえすような形をとっていただきたいなという意味で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-109"},{"speaker":"三上委員","kind":"質問・要望","question":"建物が建ってしまったならばということはあるけども、これは建築基準法の建前からいったならば、これは建てるなというわけにはいかないという前提から考えたときに、業者とのそういった行政指導をきちっとどういうふうにやっていくかということを踏まえた上で、それはきちっとやっていっていただきたいと、これは保健所の立場として明確にそれはやっていただくということを前提として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":249,"id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私はここの請願事項は極めて当然だなというふうに思います。品川区の指導要綱には、指導要綱および同指導基準に対して明確に違反をしているわけですから、この請願事項に対しては私は採択ということで、お願いしたいと思いますけれども、趣旨採択ということで一致ができるんであれば、趣旨採択でも結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-111"},{"speaker":"木下委員","kind":"質問・要望","question":"継続でというお話をさせていただいたんですが、採択ですので、本当に住民の方々の不安を解消するためにも、要綱に沿った形で強く要望していただいて、業者の方の考え方を少しでも変えていただきたいという願いを込めまして、趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"要は、旧東海道の周辺をこういう教育関係施設があるということでは、どういう環境にしていったらいいのかという中での、やはりこういう施設はあまり好ましくないというようなものが地域の方たちの中でしっかりと根づいていただいて、それがいろいろこれからいろんな業者が入ってくると思うんですね。私としては、お気持ちは非常にわかりますので、趣旨採択という形にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-113"},{"speaker":"三村委員","kind":"質問・要望","question":"先ほど意見をいろいろ言わせていただいたんですけれども、ぜひ指導要綱をきちんと守ってほしいということを業者のほうに伝えていただきたいと思いますので、できれば採択をというふうには思っていたんですけれども、先ほどと同じように趣旨採択ということであれば、全会一致を見ることになると思いますので、趣旨採択でも構いません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-114"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3148#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":73155,"voices":258}},{"id":"h18-20060626-8","meetingId":"h18-cm06","date":"2006年6月26日","dateIso":"2006-06-26","committee":"建設委員会","time":"午前１０時０３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を74件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５３号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第５３号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"それと、品川区内の区営というと、２５カ所全体であると思うんですけれども、今回対象になっている２０施設ということで、その辺を教えていただきたい。指定管理者は期間５年間というところで、導入時期が６段階にずれているということで、こういう手法について、おそらくほかはないと思うんですけれども、その辺のところをちょっと教えていただきたいと思います。","respondent":"松嶋交通安全担当課長","answer":"２点目につきまして、品川区営の駐輪場、これは先ほど条例の改正の部分でご説明をしたんですけれども、現在、区営は３５カ所ありまして、そのうちの２０施設に今回導入をするということで、この２０施設につきましては、先ほど建設委員会資料として出しましたこの裏面の一覧表。","voiceIndex":8,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"全体、区内で３５カ所あるということで、有料が２５カ所で、無料が１０カ所だと思うんです。その有料２５カ所の中で、今回、この２０施設が対象ということで、この表を見ればわかるんですけれども、残りの有料５カ所と、無料１０カ所の管理については、現行どういうふうに考えていけばいいのか。その有料の５カ所、その辺の考え方を教えていただきたいと思います。それを。","respondent":"松嶋交通安全担当課長","answer":"大崎駅につきましては、これは全体の中で、今、再開発を実施をしておりまして、地下駐輪場の予定もあります。したがいまして、現在の段階では極めて流動的であって継続性がないということで、これは今回の導入には入れておりません。","voiceIndex":10,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"ちょっとそれよりも全体のことで、先ほど条例のほうの説明のところで、第１６条で一時的に駐輪場を設置することを想定している、そういうことが想定されるというような説明があったんですが、それは具体的にはどういう意味なのかということがよくわからなかったので、まずその２点をお願いします。","respondent":"松嶋交通安全担当課長","answer":"例えば、武蔵小山、西小山であれば、東急の高架化だとか、下神明であれば２６号線の整備、戸越公園につきましては駅の改良を検討しているということでありまして、それぞれに新たな駐輪場ができる予定です。","voiceIndex":14,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"じゃあ、１点目のほうの回答のところで、これからそういう交通機関の事情に伴って新たな駐輪場ができるということも、それは区営なのか、そういう事業者との協議の、どういう立場の駐輪場になるのかということと、あと、さっき別表のほうで、２０カ所一括の指定管理者を予定していると言われていましたけれども、今後そこのところが、新しくできたところが駐輪場になった場合には、この２０カ所と同じように。","respondent":"松嶋交通安全担当課長","answer":"続きまして、無料駐輪場が新たな整備をされた後ということなんですけれども、これはそのまま指定管理者制度をこの今回の２０施設のようにすんなり行くわけではございませんので、そのときに改めてプロポーザルは実施をしたいと思っておるところです。","voiceIndex":16,"id":"exchange-004"},{"speaker":"井上委員","kind":"確認","question":"そうすると、今回の２０カ所一括とこれからのものについては分けて考えるということで、それでいいのかどうかの１つ確認と、あと、ここのところで、２０カ所ということですけれども、ブロックで分けて指定管理者何社かというふうに指定管理者をするようなことも考えて、利用者サービスの向上というか、そういう企業間のノウハウなんかを比較して。","respondent":"松嶋交通安全担当課長","answer":"それごとにやっていったほうがいいんじゃないのかとか、そういった検討もしたんですけれども、これは１社にするということが、１社で導入する理由がすごくメリットがあるという考えのもとで１社にしていきたいです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"利用が悪くて使い勝手が悪いということで、でも、料金が安いのであれば利用率が上がるというような、いろいろな民間企業のノウハウというのがあると思うんですけれども、そういうところの具体的なところになると、裁量があるのか、改修にした場合には、改修の限度額をどうするのかという、そういう具体的なものはもう前のときの指定管理者制度にもそういう議論が出てきてはいますけれども。","respondent":"松嶋交通安全担当課長","answer":"例えばこういう改修をやったときに莫大な費用がかかるとかということも可能性として考えられますので、利用料金制はとりませんけれども、ある一定額の改修につきましては、限度額というものをある程度定めて、それを超えるものは区が負担をするとか。","voiceIndex":20,"id":"exchange-006"},{"speaker":"井上委員","kind":"意見","question":"途中で１回切りますけれども、１つだけ。そういうふうな利用料金制をとらないということであるならば、品川シーサイドのように利用率が少ないところとか、今まで区がそういう改善策をとられてこなかったんだと思うんですけれども、そういう利用の少ないところに対して事業者が受けるメリットというのはあまりないと思うんですけれども、そういうところはどのように考えているのか、考え方だけお願いします。","respondent":"松嶋交通安全担当課長","answer":"例えば、先ほど１社の話が出たんですけれども、業者のほうがその利用率の高低によって少ないところにどういったものをという話になろうかと思いますけれども、それにつきましては、例えば、話が前後しますけれども、先ほど１社ということにメリットがあるわけで、例えば。","voiceIndex":22,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"今の課長答弁の中で、戸越公園駅に新たな駐輪場ができる、急行がとまるのでというように聞こえたんですが、その点、間違いないでしょうか。","respondent":"松嶋交通安全担当課長","answer":"これは、戸越公園に急行ということではございませんで、現在のところ、電車が出てしまうので、そこのところの改修がどうしても必要になってくるだろうです。","voiceIndex":24,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"ニュースを見ていましても、公的分野の民間開放、丸投げの罪悪が今、噴き出していますよね。区にお考えを伺いたいのは、この公的分野の、今回は区営の駐輪場ですけれども、民間に開放することに当たって、不正、腐敗を防ぐ仕組みには何が必要だと思っているのか、まずそのお考えを伺いたいんです。なので、まず不正、腐敗、どのように考えているのかお聞かせいただきたいと思います。","respondent":"松嶋交通安全担当課長","answer":"日報、月報、それぞれによって上げてもらいまして、その辺が不正ができないように十分にこちらで監視をしていきたいと考えております。","voiceIndex":26,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"もう一度お伺いしたいことと、あともう１つ、先ほどの質疑のやりとりの中で、どのぐらい経費が削減できるのかという議論がありましたけれども、とりあえず今現在、どれぐらいの区の管理費というんですか、区の経費がかかっているのかということが１点、やりとりの中で、どういうところで経費削減をするのか、民間のノウハウの話の中で、人的なもの、光熱水費のところを具体的に挙げておりましたけれども。","respondent":"松嶋交通安全担当課長","answer":"１点目、それぞれ癒着しているという可能性も今後出る可能性はありますよというお話ですけれども、そういった意味でも、選定委員会をつくって、それぞれがそれぞれの業者、提案してきた業者、それをよく精査をして。","voiceIndex":28,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、伺いたいのは、区営でやっているものを民間にやって、それがやるわけだけれども、結局、その民間は一定の利益を上げなければ会社として運営できませんよね。今でもシルバー人材センターやいろいろな委託先とか、それはあるでしょうけれども、わざわざその形を壊して、真ん中に１つ会社を置く、その指定管理者の先ほどから言っている３つの導入の理由がよくわからないので説明いただきたいんです。","respondent":"福田まちづくり事業部長","answer":"現在、２つの企業がこの駐輪場の業務委託を受託しておりますけれども、我々はそこではなくて、広く公募をするという方針を持っております。それから、透明性のことですけれども、これは選定委員会の結果については公表いたします。選定委員会そのものは公表いたしません。","voiceIndex":30,"id":"exchange-011"},{"speaker":"中塚委員","kind":"意見","question":"だから、民間だからいいじゃないかとか、安ければいいじゃないかとか、これ、安かろう、悪かろうの流れをどう住民の信頼にこたえて目的に沿って事業を進めていくか、そのことを僕は話しているんですよね。不正、腐敗の話もそうです。仕組みとしてきちんと担保されているのかというところだと思います。そういう中でどうあるべきなのかということを指定管理者の中で延べました、意見として。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"二、三伺いたいんですが、ちょっと細かいところからなんですけれども、先ほど、戸越公園駅のところでは、急行が通る関係があって、今後、構造的に改修が必要になる、そういう見通しだというふうなお話だったんですけれども、中延のところが廃止するという話、ちょっとそこのところを具体的にどういう中身なのか、ちょっとお伺いしたい。","respondent":"松嶋交通安全担当課長","answer":"これはまだこれから検討するところですから、ちょっとじゃあどこへという話ではないんですけれども、それはまだ検討の段階です。","voiceIndex":34,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと確認したいのは、中延のエレベーターとの関係での説明なんですけれども、この中延は３カ所あるんですけれども、実際にどこをこれによって廃止されることになるのでしょうか。","respondent":"松嶋交通安全担当課長","answer":"中延の第１、場所的にちょっと今、地図をお持ちしていないのでちょっとわかりませんけれども、もし必要であれば後でお答えします。","voiceIndex":36,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問・要望","question":"第１だと、定期のほうだったか。ちょっとじゃあ、それは後で。どこかというのは、ちょっと後で確認させていただきたいと思います。","respondent":"松嶋交通安全担当課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"そうなると、通常ですと民間のノウハウというか、これを活用するときにいろいろ言われている、民間の競争原理、これがどういうふうに働くのだろうかと思うんですけれども、そこのところはどうなるんでしょうか。","respondent":"松嶋交通安全担当課長","answer":"これは第１次は書類審査。それで、ある程度、その第１次審査での応募の数にもよりますけれども、おおむね３社ぐらいに絞りまして、第２次審査で、このときにはヒアリングを実施してやっていきたいと考えております。","voiceIndex":42,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"一般競争入札だと、価格は私どもも審査するときにこの価格で落札したと、ここは高かったから落ちなかったなというのはわかるんですけれども、それが非常にわかりづらい形になるんじゃないかなと思うんですけれども、具体的にわかりやすい基準をどうつくるかということと、もう１つ、例えば、落とされた企業が次に頑張ろうというふうになったときに、じゃあ、その採用された企業はここがよかったんだな。","respondent":"福田まちづくり事業部長","answer":"そういう具体的な検討の中で、民間の活力、これを発揮してもらいたい、これが我々の考えです。","voiceIndex":44,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"意見","question":"例えば、今回、２０カ所ですけれども、将来的には３５カ所になるのかわからないんですけれども、将来的には全部、区側の説明では１社にしていくということになると、そこが本当の意味で効率的にやっているのかどうなのか、やっぱりそれは実際上、比べてみない限りはできないんですよね。これが市場原理だと思うんです。そこのところでもうちょっとわかりやすくお願いしたいと思います。","respondent":"福田まちづくり事業部長","answer":"何を選考するか、それは企業がどういう状況にあるかということもそうですし、それから、多分、実績などということについても評価していくのだろうと思いますが、１つの基準の分野と申しますのは、どういう案を区に持ってくるか、我々はそれを比較検討する。","voiceIndex":46,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところは言っておきたいと思います。そうなると、非常に、まさに管理経費の縮減というところで行きますと、実際に同じ仕事をやっていて、形態が変わったことによって労働条件がぐんと悪くなるということなんかもあり得るかなと思うんですけれども、そういう場面は実際にあり得ると考えているのかどうなのか、ちょっとお伺いしたいんです。","respondent":"岩田まちづくり事業部次長","answer":"ちょっとお答えになるかどうかわからないんですが、今日の説明資料の裏面にも書いてありますけれども、この有料化を図ったのが５年前の平成１４年からなんですが、このとき大井町を口火にやり始めました。このときに公募型プロポーザルで業者を選定し始めました。","voiceIndex":48,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"確認","question":"次長は、いい方向に行くとは言うんだけれども、なかなか実際にそうなのかなというのは心配なところだと思います。それはそれで言っておきたいと思います。最後の１点なんですけれども、ちょっと確認しておきたいことがあります。その対応というのはどういうふうに考えているか。ほかのところも同じになりますけれども、どういうふうに考えているのでしょうか。最後お聞きしたいと思います。","respondent":"松嶋交通安全担当課長","answer":"まさに委員ご指摘のとおりでございまして、この部分が全くなくなってしまうということで、これは例えば中延第２、第３のほうに鞍がえができるのかどうか、もしくは西口の東急有料駐輪場がありますので、そういったもので何かできるのか。","voiceIndex":50,"id":"exchange-020"},{"speaker":"藤田委員","kind":"質問","question":"これは例えば、業者はおそらく保険に入ると思いますけれども、例えば自転車が壊されてしまったとか、こうした場合の保険というんですか、責任、どの辺までが区の範囲で、あとはすべて指定管理者がやるのか、この辺の線引きというのは、やはりどういうふうになるのかなということを疑問に思っているんですが、それだけちょっとお話しいただけると。","respondent":"松嶋交通安全担当課長","answer":"区はどうするかと言ったら、そういったものをやらなかったりした場合に、その管理者に対しての設置者としての責任を負うということで考えております。","voiceIndex":52,"id":"exchange-021"},{"speaker":"井上委員","kind":"意見","question":"基本的には指定管理者制度に反対するものではありませんけれども、先ほど言った指定管理者のメリットとして、１社にすることも含めて、システムを同様にしたりというようなことがあったんですが、今、当日だと番号を押して料金を支払うことになっていると思うので、そのところはシステムを同様にするということは、今、この２０駐車場の中で入っている業者というか、機械のほうなんですけれども。","respondent":"松嶋交通安全担当課長、岩田まちづくり事業部次長","answer":"そうすれば、莫大な金額も当然出てきますよという話です。そういうことですので、どちらにしても、機械については新しいものに変更していかざるを得ないだろうというふうに考えております。","voiceIndex":55,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"今のお話、ここに導入時期が違うというところで、機械を変更していくということは、指定管理者の業務委託も含めて、機械が入る場所のプロポーザルだということになると思うんですけれども、業務だけではなく、システムがいかにすごく大きな今度は指定管理になると思うんですけれども、そういうことですか。","respondent":"岩田まちづくり事業部次長","answer":"だから、西口を利用される定期の方もそちらでご購入をしていただくという形で、ステーションごとに券売機が置いてありますので、こういったものについては、やはり特にコンピューター関係が入っていますので日進月歩ですから。","voiceIndex":58,"id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"そうすると、そのシステムも含めて契約をしていくということで、次の５年間たった後に、もう１回新たな指定管理者を導入するというときには、平成２４年３月までですから、一番遅いところは平成２１年４月に機械を変更するということになると、３年ぐらいで、また２年間残るということは、そういった方たち、以前にやっていた指定管理者が優先的にみたいなところとか出てくる、その既得権みたいな。","respondent":"岩田まちづくり事業部次長","answer":"それで判定をしたいというふうに考えております。","voiceIndex":60,"id":"exchange-024"},{"speaker":"井上委員","kind":"提案","question":"当日券で言えば、パソコン仕様なので、それにすごい経費がかかるわけで、そういうまずは区としてここの利用率の少ないものの検討してクリアした後として管理を導入すべきだというふうに思うんですけれども、そこはしないまま何かいい案があれば受けますよというわけにはいかないと思うんですけれども、そこのところの対策はまずはどうしていくのでしょうか。","respondent":"松嶋交通安全担当課長","answer":"そうしますと、いろいろなやり方だとか、そういったものを自分たちのノウハウというものを持っている可能性は極めて高いわけで、例えば、今、お話のように、当日利用の場合はラックがなくては絶対にだめだということではなくて、じゃあ。","voiceIndex":62,"id":"exchange-025"},{"speaker":"井上委員","kind":"提案","question":"提案以前に、区としてそういう対策も考えられることだと思いますので、第４回定例会には指定の議決というふうになってしまいますけれども、そういうことで提案があったら、区として裁量ができるとか、すごく利用勝手の悪いところは、昨年も、一昨年も提案をしていますけれども、料金制度を低くして、遠くて同じ料金だったら、そんなところにはとめる人はいないよという議論はあるかと思いますから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-026"},{"speaker":"中塚委員","kind":"意見","question":"意見表明ですけれども、この第５３号議案には反対です。理由は、議論の中でも公平性や透明性が担保されていない。指定管理者の選考も不明確だし、民間の活力と言いますけれども、なぜ１社かというのも理解しがたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-027"}]},{"id":"topic-02","title":"平成１８年請願第４号、南品川３丁目５番地１５号の防災広場に関する請願","agenda":"平成１８年請願第４号、南品川３丁目５番地１５号の防災広場に関する請願","exchanges":[{"speaker":"宮崎委員","kind":"確認","question":"今回は木のすぐ横の大きなマンション計画なんですけれども、そういうものは全く制限されないものなのかどうなのか確認したいんですけれども。","respondent":"藤田道路公園課長","answer":"幹周りが５ｍ３５、高さが２５ｍということで、樹齢は約６００年ほどあるという大変立派なイチョウです。","voiceIndex":74,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"協議のほうはおそらく話し合いをというのは業者のことだと思うんですけれども、その話し合いをしている、それはそれで結構だと思うんですけれども、その場合、何か規則とか、何かそういうものが根拠となるものがあるのかなと思うんですけれども、品川区内もいろいろ歴史的な建造物だとか、今回は大イチョウですけれども、そういうものをどういうふうに守って後世に伝えていくのかというところの規則。","respondent":"齋藤住宅課長","answer":"ただ、あまりにやってしまうと今度は木が枯れてしまう。そこで我々教育委員会も住民の方のほうも、枯れないように何とかできないかということで苦労している、こういうことです。","voiceIndex":76,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"緑を保つというか、そういうことでの大きな大原則があるということだと思うので、そういう意味で、実際にここをある意味でそういう制限がかかっているということがやっぱり大前提だと思うんですよね。そこの点は、私はもっと規則というか、簡単に言うと規制です、もっとわかりやすいものをつくっていくことも必要ではないかなと思うんですけれども、そこら辺のところは区のお考えというのはどうでしょうか。","respondent":"福田まちづくり事業部長","answer":"私の私有財産権を規制するものです。ところで、この私有財産権というのは、我々が今ここに住んでいる社会の基本的な財産権です。ですから、これを法律で、あるいは条例によって規制しようというのであれば、それはよほど慎重に検討しなければならないと思っています。","voiceIndex":78,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"だけれども、やっぱりそういうことを今まで規則がなかった、約束がなかったということは確かにそうだと思うんですけれども、やっぱり区のほうの問題意識としてどうなのかとやっぱり今、問われているのではないかなというふうに思うんです。ちょっとあまり具体的な中身ではなくなってしまったところもあるんですけれども、感想も含めて質問させていただきました。何かあったらどうぞ。","respondent":"岩田まちづくり事業部次長","answer":"したがって、旧東海道についてはこれから規則に区が入り込んで、委員がおっしゃったことも含めて、こういったことがいろいろ考えられますよということをきちっと区が説明をし。","voiceIndex":80,"id":"exchange-031"},{"speaker":"松澤委員","kind":"質問","question":"今お話を聞いていますと、教育委員会のほうでイチョウを守るための話し合いをしなさいということで、先ほどおくれているということですけれども、その具体的中身、どのようなことを教育委員会が話をしているのかということ、あるいは、建主のほうがある程度それを考慮したいと考えているのか、単に答えが出ないので窮して長引いているのかどうか、この辺のところはどうですか。","respondent":"齋藤住宅課長","answer":"教育委員会には、うちの道路公園課でとめているというわけではございませんで、事業者のほうで、若干話し合いの場が持たれているという現状ですので、話し合いの場は持たれていると聞いてあります。","voiceIndex":82,"id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"それは容積率の関係になってきますけれども、当事者の中に地権者がそこへまた住むということですものね。地権者は建物にしましても、古い建物ですから、相当昔からいるのでしょうから、地元品川を愛する人も若干そういう思いと景観をどうのこうのと言っても、もうあの辺は高い建物が建って、今さら協議して４階しかいけませんよというのは無理ですから。その辺はどうですか。","respondent":"齋藤住宅課長、岩田まちづくり事業部次長","answer":"法律上、そのようなことを申し上げる権限はございません。ただ、話し合いの場を持つように、こういうことは条例に基づいて設定はできますけれども、権限はございません。この天然記念物のイチョウの木につきましては、本請願の内容とちょっと離れるんですが、当然、区も今ある緑を残すというのが区の政策の柱になっておりますので、これだけ大きな記念物ですから。","voiceIndex":86,"id":"exchange-033"},{"speaker":"松澤委員","kind":"質問","question":"このまま時間がどんどん経過して、請願とはちょっと関係ありませんけれども、時間切れなので私たちはやりますよとやられてしまったのでは、実際に法律的には何のあれもないんですから、そういう前にやはり地域の方たち、地権者の方たち、本当に真剣に真摯に話し合ってもらって、私もこれ、請願を出されて初めてこんな状態なんだ、今日見に行って初めてイチョウの木はこんなに立派だったんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-034"},{"speaker":"本多委員","kind":"意見","question":"そのときの防災機能というところから考えて、近隣には青物横丁の防災倉庫の防火水槽とかがあったり、もっと防災機能を上げていかなければいけないという、そういう視点から本当にこの地域の人口が増えているというところで、防災広場を、そういう近隣のいろいろな貯水槽とか、そういうものとあわせて、この地区の防災機能を上げるというところで改めて見解を聞きたいと思います。","respondent":"久保田防災課長","answer":"ということは、先ほどまちづくり事業部のほうから説明したとおりです。あわせて、この当時、防火水槽、区全体で８５０ぐらいありました。","voiceIndex":90,"id":"exchange-035"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、このイチョウも６００年というところで、地域性を考えると、東海道４００有余年ということで、品川の顔の一部にこの地域ということで、その４００年以上、もっと古くて６００年というところですから、そういった部分を、権利の話は十分先ほどから出てわかるんですけれども、そういった部分では、まちづくりを考えて、しっかりこういうケースごとの対応を改めてお願いしたいと思うんですけれども。","respondent":"藤田道路公園課長","answer":"ご存じの事業におきましては、今回、イチョウが天然記念物なんですけれども、周りの樹木については、一応保存樹林というような形になってありますので、それに合わせた形でちょっとお話ししますけれども、基本的には指定をした後に適正な管理をしていただくために。","voiceIndex":92,"id":"exchange-036"},{"speaker":"本多委員","kind":"質問・要望","question":"緑比率の話も当然考えて、この請願につきましては、やはりこの権利の話だけではなくて、行政としてもできる限り対応していただきたいという意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"請願の趣旨は防災公園にしてほしいということですけれども、そこには近隣に住んでいる方々、そうじゃない、長くこの大イチョウの木を見て育った方々、いろいろな人の思いが込められた、そこの防災公園にしてほしいというふうに唱えているのかなというふうに理解しているんですけれども、ちょっと僕が聞きたいのは、先ほどこの木に関しては枯らしてはいけないというのは当然だというお話がありましたけれども。","respondent":"藤田道路公園課長","answer":"その一方で、今まであった木、これを切ってもいいのか。それはちょっとまた違うのかなというふうに私自身は考えてあります。今まであったものを大切にし、なおかつ新しく増やしていく、これが緑の条例の中で私どもは考えていますし、進めていくものです。","voiceIndex":96,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"今の説明の中で、今ある木を切ってはならないと。ただ、その趣旨は何なのかということを区はどういうふうに思っているのかなと思うんです。だから、今あるものを切ってはならないという、ただそれだけの趣旨ではないと思うんですよね。もっと中身のある、趣旨のある条例ではないのかなというふうに僕は思っているわけですけれども、違うんでしょうか。","respondent":"藤田道路公園課長","answer":"もう一つ、地域のシンボル的なというふうなお話もございましたけれども、そういった観点で景観法というものができていて、景観法の中で、景観重要樹木というような形での税の優遇とか、そういったような制度も、今、私どもも要望しておりますし。","voiceIndex":98,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"だから、紛争予防条例に対等でない立場をきちんと同じテーブルに載せるために建築主に対して説明であり、良好な住環境を確保する責任を建築主に求めているわけですよね。やっぱり建物があると、その被害、工事中の日陰や木も含めて、やっぱり周りは一定の影響を受けるから、だから紛争予防条例が建築主に対して一定の責任を説明、住環境への配慮を求めて、その関係をどう理解していいのかなと。","respondent":"齋藤住宅課長、岩田まちづくり事業部次長","answer":"話し合いの場を持つようにということでお願いをしております。現在、事前協議が長引いているのも、こういった区のお願いのあらわれだと思います。もちろん教育委員会も事業者側からこういう対処方法をしますよ、根っこの養生をこういうふうにしますよということは十分聞いた上で、その樹木の専門家の意見を聞きながら、必要であればアドバイス等は行うんだろうと思いますけれども。","voiceIndex":100,"id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"私が住んでいる北品川のところでは８階建てがあったりしても斜面規制がかかっている部分で、まち並みを歩いている部分で言えば、まだ空が見えているというような状況で、青物横丁までそういった極端な高い建物はなっていませんけれども、実際に建てようと思えば１２階まで建てられるということで、斜面規制もなくなって真っ直ぐな建物が立ったときに、どれだけ閉塞感みたいなものがあるかということで。","respondent":"阿部都市計画課長","answer":"ただ、現在のところ、区としてはそこをどうするか。目標はありますけれども、具体的に高さを制限すると。そこでは私権の制限もありますので、なかなか難しいというふうに考えます。","voiceIndex":104,"id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"例えば渋谷区だとか、新宿区も高さ規制を首長がもう始めようというふうな姿勢、私権というよりもそういうまちづくりをもうこれは違うよねというところで変えていこう、地区計画は地区の同意がなければできませんけれども、高さ規制は行政がこういう方針でやろうよという形で出して、そこに地域の住民の議論が巻き起こってできるものというふうに聞いていますが、その辺はどうなんでしょうか。","respondent":"片田建築課長","answer":"確かに他の区、中央区等々で、新宿のほうでも一定程度の高さを制限するというところがありましたけれども、これは高度地区の考え方とか、それを一部適用したところの考え方として認識していますので、やはりこの辺での地域の考え方。","voiceIndex":106,"id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"それを今いる私たちがどう守っていくかということは、すごく考えてこれからまちづくりをしていかなくちゃいけないと思うんですけれども、今、地域の方たちの合意とか、そういうものが一番大切という中では、高橋区長あてに同様にこの地域の方たちから５,８００名ぐらいの署名を添えられて陳情が出されているということで、こういったところの天然記念物のイチョウを守っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-043"},{"speaker":"藤田委員","kind":"質問","question":"８階がだめなら５階でもだめと。いろいろなところの話し合い。そうした中で、議会には請願、また今お話がありましたように、区長に陳情が出されたという経緯なものですから、非常に当委員会でこの問題についての審査はどこにポイントを置いていいのかというのは、非常に難しい部分があります。ですから、これは私たちとしてはこれは十分関係者で話し合ってもらわなきゃいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-044"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと１点確認したいんですけれども、現在は教育委員会が業者のほうとお話しされていると思うんですけれども、今、いただいた資料、「ご近隣の皆様へ」という、この資料の中では、いろいろ対策、いろいろこういう対策をやりますというふうな中で、いろいろ火災防止、電波障害とかたくさんあるんですけれども、このイチョウの木に対する対策というのはここにないんですよね。","respondent":"齋藤住宅課長","answer":"事業者はご存じだと思います。ただ、文化財に指定されていた樹木だというふうには認識はなかったと思います。来て相談されて初めて品川寺のイチョウの木が指定されている木だというふうに理解したと思います。","voiceIndex":110,"id":"exchange-045"},{"speaker":"宮崎委員","kind":"質問","question":"ただ、大きな一流企業ですから、こういう文化財というものは当然それなりの考えというのは対応してくれるんじゃないのかなというふうに思うんですけれども、そこのところはやっぱりわかる範囲でいいんですけれども、かなり今説明のところではそれぞれの制限になると財産権の侵害であるとかというお話なんですけれども、そうすると、今。","respondent":"齋藤住宅課長","answer":"品川寺としても、住友林業といろいろご相談されて、いろいろ検討されているようですので、それで話し合いの場を持って、何とか枯れないように切らなくて済むように、隣の方も計画が進むように、隣地の所有者の方も。","voiceIndex":112,"id":"exchange-046"},{"speaker":"宮崎委員","kind":"意見","question":"私も最初に言いましたように、やっぱり基本的に当人同士の民民の話というのはあるんですけれども、私はやっぱりまちづくりを品川区がどう考えるかというところを、私は今ここに文化財があるということもありまして、やっぱり区としてどう考えるかというのは、やっぱりそこは問われているところだなというふうに思います。それと、もちろん企業側です。それが問われていると思います。以上、感想です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-047"},{"speaker":"松澤委員","kind":"質問・要望","question":"請願の結論ですけれども、請願書、防災広場にしてくれ、これだけを見ますと、私たちとしては防災面では、２ですから、どう考えても品川区の必要な財源を危険度２のところで使うのかということになると、なかなか採択というところまでいかないと思います。願意に沿い難いですから。果たしてそれでいいのかなという思いが大変します。私は趣旨採択ということができるなら趣旨採択というふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-048"},{"speaker":"大西副委員長","kind":"質問・要望","question":"要するに面談を重ねていったと、それが物別れて中身がどうであっても、およそ２回、３回との話し合いは行ったということにおいての恐さも私の推測ですから、正確なところはわかりませんが、そういうところもあろうかというふうに思います。そういうところで、行政としての知恵を出していただき、あの地域を守るための施設なり、そういう考え方を持っていただくべきではないかなと。","respondent":"岩田まちづくり事業部次長","answer":"したがって、品川区の今の時点では、地主さんとの交渉をする余地もない段階ですので、きょう、議会の姿勢を決めていただきまして、その後、区のほうでどんな対応をできるか、委員長、副委員長のご趣旨に沿えるかどうかわかりませんが、いろいろ検討してみたいと考えています。","voiceIndex":117,"id":"exchange-049"},{"speaker":"大西副委員長","kind":"質問・要望","question":"ただ、私は本請願を出された住民の方々の気持ちを行政側も汲み取り、今の状況をお話しされ、そしてまた行政として自分たちのできる範囲内ではこういうものも持ち合わせているというものもサジェスチョンしても私は住民側にとっては一つの考え方もできてこようか、切り口として出てこようかというふうに思われますので、私は品川区民の財産。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-050"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、やっぱり住民の皆さんの気持ちを主に受けとめていきたい、何回も同じ発言になるかと思うんですけれども、ぜひ区のほうも今の意見を酌み取っていただいて対応していただければと。あわせて地権者の方、事業者の方もやっぱりこういう重要なイチョウの木を、また住民の方々もぜひ酌み取っていただければなと、感想も含めて言いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-051"},{"speaker":"藤田委員","kind":"質問・要望","question":"私も趣旨採択というところです。竹だとか細い木をずっと。ですから、人間歩くときには上を向いて歩かないわけです。大体この目線で歩いている。ですから、あの地域の人たちがもうちょっとそういうことも参考にしていただいて、みんなで品川寺の周辺がよくなればいいなというふうに思っておりますので、ぜひ区としてもできることなら最大限の行政指導をしていただきたいと、このように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-052"}]},{"id":"topic-03","title":"の「平成１８年度 区民・都・区合同立会川環境美化運動について」","agenda":"の「平成１８年度 区民・都・区合同立会川環境美化運動について」","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"毎年何人ぐらい参加されているのかというのを教えていただけますか。","respondent":"原田下水道河川課長","answer":"毎年総勢で１５０人ぐらいです。","voiceIndex":130,"id":"exchange-053"}]},{"id":"topic-04","title":"の「区営住宅（空き家）入居予定者登録募集について」","agenda":"の「区営住宅（空き家）入居予定者登録募集について」","exchanges":[{"speaker":"井上委員","kind":"質問","question":"以前に建設委員会で区営住宅のところで、建物ごとの登録をしているというようなことを伺ったかと思うんですけれども、この建物に入りたいわけではなくて、困窮度のある人が品川区内だったらいいんだというようなこともできるような仕組みに変えることも検討してほしいというのが建設委員会で出たかと思うんですけれども、そのことについて何か改善されたとか。","respondent":"齋藤住宅課長","answer":"要するにこの住宅は、例えば中延住宅はだれでもいい住宅だというふうに、あいたら呼ぶというふうに審査をするのではなくて、住宅ごとに住みたいというご要望がありますから、その方との調整というのが、あきが少ないのにできない、それが実態です。","voiceIndex":137,"id":"exchange-054"},{"speaker":"井上委員","kind":"質問","question":"そういうふうな募集をしていてと言ったんですけれども、例えば中延住宅だけがどんどん減っていくと、いろいろな状況で入居されることができる可能性があるわけで、でも、ほかのところを希望した人のほうが、その前に登録をした段階でどういう状況かというのはデータとしてあると思うんですけれども、そういうことを審査するわけにはいかないですけれども、保育園の入園のポイント制みたいなものとか。","respondent":"齋藤住宅課長","answer":"それとゼロから２５の階層の方には、いろいろ条件があるんですけれども、あらかじめそれを審査して、下の層の方を優先的に入っていただくということは、必ずしも公平には当たらないというふうに考えておりますので、委員のおっしゃった制度を取り入れることは。","voiceIndex":139,"id":"exchange-055"},{"speaker":"宮崎委員","kind":"質問","question":"ちなみに、昨年度、今、空き家１２戸ぐらいとおっしゃっていて、昨年は何人申し込んで、何人登録できて、そして何人入れたのかということか、どういう状況だったんでしょうか。","respondent":"齋藤住宅課長","answer":"去年の８月から今年の８月までが公募期間になっておりまして、今のところ、お二人が引っ越しされて、１２人の方がお亡くなりになりました。今のところ、１４人の方が入居しています。応募の戸数は、家族向けが５００世帯で、単身が約２２０世帯ぐらいです。","voiceIndex":141,"id":"exchange-056"},{"speaker":"宮崎委員","kind":"質問","question":"いずれにしても、転居をしたり、亡くなられた方もおりまして、１４ぐらいしか空かない中で、競争率が非常に高くなっているということですけれども、改めて、区営住宅、都営住宅の移管なんかも含めて、区営住宅の増設等についてどういうふうな考えなのか、改めて伺っておきたいと思います。","respondent":"齋藤住宅課長、福田まちづくり事業部長","answer":"現在、新たな区営住宅の新設についての考えはありません。いつかもお答えいたしましたけれども、品川区の区営住宅対１世帯、この比率を近隣区と比較をしてみますと、品川区はその平均値を上回っている状況にあります。","voiceIndex":143,"id":"exchange-057"},{"speaker":"宮崎委員","kind":"提案","question":"そういうお話だったらあえて聞きますけれども、やっぱり、住民の要望ということで、近隣区と比較ということよりも、住民の要望を非常に考えるべきだということを改めて提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":146,"id":"exchange-058"},{"speaker":"松澤委員","kind":"質問","question":"区営住宅についてはわかったんですけれども、区民住宅は現在、どれくらいの入居率ですか。","respondent":"齋藤住宅課長","answer":"区民住宅につきましては、前回の建設委員会でご報告いたしましたが、９８％くらいの入居率でございまして、併設型区民住宅では空きが１０戸出て、建設型が２戸です。借上型のほうにつきましては１４戸ぐらいということになっております。","voiceIndex":147,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点目の、この辺は予定登録者の募集をするんですけれども、昨年募集して、今年も募集する、それに同じ人が募集する割合、そういうのは調査されているのかどうか教えていただきたいのと、募集する人の年齢、そういうのはつかんでいらっしゃるのか、つかんでいたら教えていただきたいんですけれども。","respondent":"齋藤住宅課長","answer":"入居者のデータはとっておりますが、入居登録者等のデータはとっておりません。","voiceIndex":149,"id":"exchange-060"},{"speaker":"井上委員","kind":"質問","question":"すみません、区営住宅じゃなくて区民住宅のほうで申しわけないんですが、借上型の１４戸というのは、よく予特、決特で出てきていますけれども、これについては、最近、空きの変動があるのかどうなのかということ、いろいろと改善すべきで、埋まるように何とか対策をとるべきじゃないんですかというご意見があったような気がするんですけれども、最近の推移みたいなものと、あと、これに対する対策。","respondent":"齋藤住宅課長","answer":"空きは、若干増えているのが現状です。空きの最大の原因は、近傍・近隣の民間家賃との差が高いということについて、区といたしましても、オーナーの方に働きかけをいたしまして、下げる方向で交渉を頑張っているです。","voiceIndex":152,"id":"exchange-061"},{"speaker":"井上委員","kind":"質問","question":"具体的に増えているというのは、今現在１４戸で、その少し前の４年くらい前のデータというのは、今あったりするんですか。","respondent":"齋藤住宅課長","answer":"すいません、区民住宅のほう、ちょっと持ってきていません。","voiceIndex":154,"id":"exchange-062"},{"speaker":"井上委員","kind":"確認","question":"じゃあ、後でいいです。それの確認なんですが、家賃が民間よりも高いということですけれども、この空いている部分というのは、毎年か毎月毎月、区がそこを補てんしているという状況ですか。","respondent":"齋藤住宅課長","answer":"はい、そのとおりです。","voiceIndex":156,"id":"exchange-063"},{"speaker":"井上委員","kind":"質問","question":"そこに対して何らか、家賃を下げてください、下げませんということでは、契約が何年間というのであるんだけれども、そのことに対して、このままでいいとは思っていらっしゃらないと思うんですけれども、どういうふうに考えていらっしゃるんでしょうか。","respondent":"齋藤住宅課長","answer":"ところが、今ＵＲ都市機構は家賃１５年分の貯金があれば入れる。こういった新しい収入基準も既にやっておりますので、区でもそういったことを導入して、今は収入がないけれども、資産があるから入れるということも検討しております。","voiceIndex":158,"id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"そもそも、この借上住宅というのは、目的が住宅を増やしてほしいというものなのか、それとも、区民に対して優良な住宅をあっ旋するというというものなのか、区民住宅の借り上げというのは何かを補てんするためにこういう制度ができたのか、そのところは何なんですか。","respondent":"齋藤住宅課長","answer":"その後、バブルがはじけて家賃が下がってまいりまして、近傍・近隣との格差がなくなってきたということで、現在の、委員からご指摘いただいた部分が出てきているです。","voiceIndex":160,"id":"exchange-065"}]},{"id":"topic-05","title":"の都営住宅（地元割当）入居者募集","agenda":"の都営住宅（地元割当）入居者募集","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"同じような質問なんですが、特に地元割当、今回２戸ということで、ここ数年間、地元割当って一体何戸ぐらいになってきているのかというのがわかったら教えていただきたいんです。年度ごとでもいいんですけど。","respondent":"齋藤住宅課長","answer":"大体、２戸か３戸です。","voiceIndex":167,"id":"exchange-066"},{"speaker":"宮崎委員","kind":"意見","question":"前はたしかもうちょっとあったような気がして、２戸というのは珍しいぐらいだったんじゃないかと思うんですけど、最近はこのぐらいが当たり前みたいな感じなんですよね。そういうところを聞いているんで、欲しいとか欲しくないということじゃなくて、実際の動きがどうかということ。","respondent":"齋藤住宅課長","answer":"３件ぐらいしかありません。","voiceIndex":171,"id":"exchange-067"}]},{"id":"topic-06","title":"の平成１８年度マンション管理セミナー（第１回）の開催","agenda":"の平成１８年度マンション管理セミナー（第１回）の開催","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"６０名なんですけど、これより多く来た場合、どうするんですか。","respondent":"齋藤住宅課長","answer":"若干であればいすを用意して対応したいと思います。１０名、２０名であれば対応できます。","voiceIndex":178,"id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"マンションの管理の中で、相談の中で、先ほどもお話の中で理事長も持ち回りとのお話がありましたけれども、そのほかにもどんな相談内容が多いのか、割合などももしわかりましたら教えてください。","respondent":"齋藤住宅課長","answer":"こういったお話もありますし、あと、定期修繕費用負担の方法と、どのタイミングでどの業者に、１０年目、２０年目、外壁改修や、共有部分の改修をお願いするという、こういったお話が来ております。","voiceIndex":180,"id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"修繕費用負担の方法、１０年後、２０年後にどういう修繕をするかというお話で、１点だけ区のお考えを伺いたいんですけれども、いわゆるマンション自体はマンションに住んでいる方の意志合意も大事ですけれども、マンション自体が持っている地震のときの被害とか、マンションの倒壊、そうなってくると、避難路をふさぐ、周辺の方も含めて、被害が拡大するわけですよね。","respondent":"齋藤住宅課長、片田建築課長","answer":"実は、品川区では、震災のときに倒壊の危険のあるマンションというのはありません。現在、そこまでの深刻なご相談というのはないのが事実です。マンションの耐震ですけれども、５月からは民間のマンションについて、構造の相談ということで、毎週水曜日、開設しています。管理業協会との連携の中で、専門家に来ていただいて、９時から１４時までということでやってあります。","voiceIndex":182,"id":"exchange-070"},{"speaker":"大西副委員長","kind":"質問","question":"ちょっと１つだけお伺いしたいんですが、この管理組合の方々がこれに相談に来るということですけど、例えば、賃貸マンションの場合に、そこに住んでいる住民たちに対するモラルの低下のことを管理組合を通じて言うということが、賃貸マンションの場合は管理組合はできてないというふうに想像するのと、例えば、東品川の三丁目には住宅都市整備公団の、あの部分については１,０００世帯なんだけれども。","respondent":"齋藤住宅課長","answer":"ところが、町会に入れるためにいろんな活動をしなきゃいけないわけで、３年ぐらい活動してみて、それで、活動実績があれば、町会としての位置づけしてもいいですよ、こんなような話になっておりまして、委員のご質問の趣旨とずれているかもしれませんけれども。","voiceIndex":186,"id":"exchange-071"}]},{"id":"topic-07","title":"の大崎駅東口第３地区における地区計画区域内事業の現況","agenda":"の大崎駅東口第３地区における地区計画区域内事業の現況","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今回、１点目のＣ地区と、２点目のデッキの拡幅ですけれども、税金や補助金の関係はどういう関係にあるのか教えていただけますか。","respondent":"上野都市開発課長","answer":"Ｃ地区の開発につきましては、補助金の投入はございません。それから、今回のデッキの拡幅工事につきましても、組合側の自費工事で行う予定ですので、補助金の投入はございません。","voiceIndex":194,"id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"Ｃ地区のほう、ペデストリアンデッキが横に、それぞれ左右に最後に出ていますけれども、それはそれぞれの再開発につなげるためのものなんでしょうか。どういうものなのか教えていただきたい。","respondent":"上野都市開発課長","answer":"お手元、地元説明会資料を１枚めくっていただきますと、２の開発概要といたしまして、Ｃ地区の業務棟の左右にペデストリアンデッキを整備する計画となっています。","voiceIndex":196,"id":"exchange-073"},{"speaker":"宮崎委員","kind":"質問","question":"議案審査との関係もあるんですけど、戸越公園のところの駅というか、急行化で地元にもいろいろ説明がされて、東急側からされているようなんですけど、区のほうでも内容がわかっていたら。今日はもう時間がないので、あしたにでも説明していただければなと思います。東急から地元には説明が行っているようなんですけれども、やっぱり議会のほうにあっていいんじゃないかと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-074"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":61488,"voices":207}},{"id":"h18-20060626-9","meetingId":"h18-cm06","date":"2006年6月26日","dateIso":"2006-06-26","committee":"文教委員会","time":"午前１０時０３分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５４号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第５４号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"１つだけ。直接かからないかもわからないんだけど、学校医、歯科医と薬剤師も含めてだけど、以前問題になったこういう仕事をする人たちの確認、前、高齢で仕事をされていない薬剤師がそのまま指定されていたことがあったんですよ。そういうチェックというのは何年かに一遍とか、あるいは失礼な方法かもわからないけれども、確認の連絡をとるとか、そういうことはされているんですか。","respondent":"古里学務課長","answer":"その報告についても、必ず全学校私どものほうに上がってまいりますので、上がってこない場合は調査がいっていないということになりますので、そういうチェックは、そういう形で執務記録あるいはそうした調査の報告によって、必ず働いていただいているという確認はとってあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"学校長が近くの先生にお願いしますという形で決めていくわけでしょう。教育委員会が、Ａ先生をＢ小学校の学校医、あるいは歯科医、あるいは薬剤師という形で指名するんですか。その仕組みをちょっと。","respondent":"古里学務課長","answer":"その時点で前年度、事情によって、病気等で退任をされる、あるいは退任をしたいというご希望があった向きにつきましては、そのようなことを入れて医師会のほうに推薦をお願いして、推薦に基づいて私どもと学校と相談して、委嘱をするという手続をとってあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"確認","question":"そうすると、そういう方の何というか、グループでお願いしている。それで、毎年の役割というか、仕事がなされていることで確認がされている、そういう理解ですね。もう１点だけ。小中一貫校ができて、学校そのものは１つで、一体型というか、そこには中学校の学校医、小学校の学校医、２人ずつ契約というか、配置されているんですか、その辺だけ最後に聞かせてください。","respondent":"古里学務課長","answer":"今、日野学園がスタートいたしましたが、法律上は、それぞれ小学校、中学校は併存をしているという形になってありますので、結論から申し上げて、学校保健法に基づいて、小学校、中学校それぞれ配置をしております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、品川は４・３・２とやっていっても２人ということになるわけですね。全国的に小中は６・３という形の中でいけば２人という、そういう考え方でいいですか。","respondent":"古里学務課長","answer":"この辺はまた学校教育法が、義務教育学校という法改正があり、それに伴った改正があったときに、それに合わせて検討すべき事項は検討していきたいと考えてございまして、現在では学校保健法に基づいているということで、ただ、今後日野学園における検討のあり方の中では。","voiceIndex":11,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"親指と人指し指をほかの指と差別化するというのは、法律で決まったことだからこれはやむを得ないことだし、ある意味では当然かなと思うんだけど、その思想、考え方で、今までの法律でそういうふうにランクづけをアップすると。８級にするというんですか。それを今度変えたのは、世界的な流れなんだという説明があるんですけど、そこらをもう少し詳しく説明していただけるとありがたいんですけれども。","respondent":"古里学務課長","answer":"それを見ましたところ、最終的な結論としては、お医者さんを含めてそういう検討をして上で結論を出したと聞いてあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"指にしてみれば人権問題だと言うかもしれないけど、自分の指だからあれなんだけど、一般的に言えば、例えば親指を失うより小指を失ったほうがダメージは、一般的な話ですけどね、少ないとは思うんですけれども、そういうのがあって災害補償のランクづけがあったと思うんですけれども、諸外国の事例というのは手元にありますか。","respondent":"古里学務課長","answer":"それらしい情報については手持ちはございません。いずれにしましても、この災害補償法の大もとの論議の結果ですが、上位法にそういう規定が出てきたというところから所与の改正を行うですので。","voiceIndex":15,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"品川での学校関係でも、公務災害というのは件数ですと大体どれぐらいあるのか、状況がわかったら教えていただきたい。","respondent":"古里学務課長","answer":"これは昭和３７年からという類型でございまして、何年度にどの件数が起こったかというところまでは、ちょっと把握してございません。","voiceIndex":17,"id":"exchange-007"},{"speaker":"武内委員","kind":"確認","question":"ちょっと確認だけしたいんですけれども、これは公務災害についての改定なんですけれども、先ほどもいろいろご説明があったとおり、民間のいわゆる労災が変わったということに基づいてこういう形になっているということでよろしいんですか。","respondent":"古里学務課長","answer":"労働基準法およびそれに基づく労働者災害補償保険法が最上位規定でございまして、そちらが変更になったということから、所与の自治体で順次改定作業に入っていったです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"武内委員","kind":"意見","question":"手の指についてそういう形で変わるということで、わかるような気もするんですね。足は、おそらく足の親指というのはいろいろ運動する場合にもすごく大事なところだと、変わっていないと思うんですけれども、多分そういうことで変わっていないのかなと思うんですけれども、手だけということでよろしいんですね。","respondent":"古里学務課長","answer":"今回の件につきましては、手にかかわる障害と、それから複視、目のほうですね。二重に物が見えるという障害が残ったという、この２つの点についての改正でございまして、足のほうについては情報がございませんので、ちょっと勉強不足で済みません。","voiceIndex":21,"id":"exchange-009"}]},{"id":"topic-02","title":"平成１８年度「通学区域の弾力化」に関するアンケート調査結果","agenda":"平成１８年度「通学区域の弾力化」に関するアンケート調査結果","exchanges":[{"speaker":"武内委員","kind":"意見","question":"ご説明いただいた３ページ、４ページ、７ページで、３ページで言うとＱ２の５の学校の特色ある教育活動を考えるというところの小中一貫教育、これが平成１６年から１８年にかけて、それぞれ中学生、小学生、保護者と伸びてきたというご説明をいただいたんですけれども、そのとおりだと思うんですが、この平成１６年から１７年で一たん少し率が下がって。","respondent":"古里学務課長","answer":"この数字をどういうふうに見るのかというところが私の今の報告には全く入っていないんですけれども、これはかなり特徴的な部分ですので、平成１７年度の数字を見ないで、１６年と１８年を比較するという形で、今回検討させていただいた。","voiceIndex":29,"id":"exchange-010"},{"speaker":"武内委員","kind":"質問・要望","question":"じゃ、またわかったときに、何かの機会にまた教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"そういう影響なのかどうなのか、伸びた要因をどう区教委として判断しているのか、わかったら教えていただけますか。","respondent":"古里学務課長","answer":"沢田委員もおっしゃいました日野学園のスタート、大井、それから６校構想の発表等もありますけれども、私どもいろいろな場面で、保護者の方が窓口にいらっしゃいますけれども、この教育要領の発表以降。","voiceIndex":32,"id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"ここに変化が出ているというのは、施設一体型の一貫校だからというのはわかるんですけれども、その辺はどうなんでしょうか。一貫教育をやるということを全区に言って、安心してくださいというか、期待してくださいと区のほうはアピールをしたんだけれども、実態的には一貫校に関心がずっと高まっているということのあらわれじゃないのかなと思うんですが、いかがでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"もう１つ考えられるのは、実際にこの平成１８年４月から各小学校や中学校が具体的にどういうことをやるかというのを、かなり地域や保護者に発表してきていますので、学校によっては、あの中学校と４月からこういうことをやりますということを言っていますので。","voiceIndex":34,"id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"ここで聞いていいかどうかわからないんですけど、学校選択で八潮南中がゼロになったということを、私、前回出なかったので、前回話になっていればそれは結構なんですけど、区教委としての分析、それからどうしてそういうふうになったのかということをぜひ聞きたいんですが、ここはアンケートのことなので、聞くのがいいのかどうなのかと思うんですが、いかがでしょうか、取り扱いとして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"長くなってあれなので、別のときのほうがいいのかなと思うんですけれども、最終的にはゼロになったわけですけど、最終の一歩手前で、行きたいと言っていた人が、ゼロになるなら、私が１人になるならばほかを選ぶしかないと、そういう場面があったんだと思うんですけど、その辺の状況はどうなのか。その辺について、今日はちょっと別のところなんですけど、もしあったら出していただきたいと思います。","respondent":"古里学務課長、吉村小中一貫教育担当課長","answer":"八潮地区の問題については、別途改めて報告をします。その時点で、そういった点についてもまたご論議いただければと思います。今のご質問ですけれども、人数がどの程度まで少なくなったということがあると思うんですけれども、１けたであるとか、５人を切ってくるであるとか、そういった状況になったときには、当然学校としては。","voiceIndex":39,"id":"exchange-015"},{"speaker":"林（宏）委員","kind":"意見","question":"基本的にアンケートの紙を渡して、家で書いてきてもらう。子どもの場合は学校で書き入れるということが可能なんでしょう。その辺はどうやってしたのかと、Ｑ２のところは複数回答とか、あるいは３つまでとか、そういう何か条件があったのか、その辺を最初に聞かせてください。","respondent":"古里学務課長","answer":"学校のほうでは一切集計をせずに、学務課のほうへ持ってきた時点で集計をしているというふうにしています。それからＱ２つきましては、Ｑ３もそうなんですけれども、複数回答、特に数の制限は設けてございません。","voiceIndex":42,"id":"exchange-016"},{"speaker":"林（宏）委員","kind":"意見","question":"プライバシーという問題はちょっと置いておいて、子どもたちの場合だと、学校で、そうなったらおかしいんだけど、書いて回収すれば１００％に限りなく近い数字が得られると思うんだけど、それをしなかったのは、プライバシーだけなのか、ほかに何か。もう少し子ども自身の考え方を尊重してあげれば、別々に回収するというのも１つの方法じゃなかったかなと思うんだけど、その辺について聞かせてください。","respondent":"古里学務課長","answer":"技術的な問題以外に、回答内容の問題についても少し検討をするべきものではないかと思います。ちょっと今、軽々にここでは何か申し上げられるということではありませんけれども、検討させていただきたいと思います。","voiceIndex":44,"id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"小学校１年生では無理だろうということで、保護者の方だけにした。そうなってくると、６年生の意思を尊重してあげるという意味でやれば、親子で相談しながら記入するのも１つの教育の部分かなとも思いますけど、ぜひ検討してください。保護者への質問と書いてあるから保護者なんだね。これは６ページが、私立とは限らず、区立以外を選択した、５ページと６ページは親子という意味で見ればいいのかな。","respondent":"古里学務課長","answer":"全く同じですので、左側が保護者の回答、右側が児童の回答というふうになってあります。","voiceIndex":46,"id":"exchange-018"},{"speaker":"林（宏）委員","kind":"意見","question":"ここは親子が結構数字が違う部分があるね。この部分の３７４名の方が書いてくれたわけですけれども、区立小中学校の設置者として、品川区教育委員会はどういうふうに受けとめていらっしゃるのか。総括的でもいいですし、個別にここが非常に興味深いという形でもいいので、その辺をお答えください。","respondent":"古里学務課長","answer":"児童自身のアンケートのほうでも、進路を考えているか、それから学校の伝統を選ぶというところが、自分の学力と合っているかというところが、学力を考えてというところに対応するところから見れば、ここら辺が上位に来ているというところが。","voiceIndex":48,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"意見","question":"不可能な数字なんでしょうけど、品川では全員が区立小、区立中に入学というのが、教育委員会としては１つの目標と言ったらちょっと大げさだけれども、そうあってほしいということを考えて、品川の教育ということをいろいろお考えになっているはずだと僕は思っています。小中一貫というのをやるときに、この区立以外を選択する人たちにとっては、魅力がないというふうに受け取っていいのかな。","respondent":"吉村小中一貫教育担当課長","answer":"ただ一番私どもが注目しているのは、例えば私立のほうの５ページの中学校の親が学校の特色ある教育活動を考えてというのは２７.２７％ですよね。これは実は公立学校のほうの特色が今回２１.５５％ですから、今までと比べるとかなり肉薄してきているんですね。","voiceIndex":50,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、区立中学校を選ぶ基準というのかな、今言われた学校の特色、それと国立の場合はちょっと区立と比べようがないんだけど、私立を選ぶ人が区立と比べて、学校を見比べるということにたえられる区立中学校になってきたというふうに教育委員会は自負するのか、一般的に言えばそういう品川の中学校になってきたというふうに幾らか考えてもいいわけですかね。","respondent":"吉村小中一貫教育担当課長","answer":"それがようやくここへ来て、５年、６年、７年たってきたときに、ようやく２割を超えてきたということにおいては、やはりこの間、教育委員会、学校が努力してきたことがある程度保護者や地域の方に評価されてきているということは言えると思います。","voiceIndex":52,"id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"もう１回言います。この数字、２７と２２を同じにするのは教育委員会の目標ですか。単純な数字だから一概にどうという話じゃないけど、このアンケートを見ている限りでは、そこの数字を並べたい。並べたいというか、同じように上げていきたいというのが。","respondent":"若月教育長","answer":"個人的なことで申しわけありませんが、熱がありまして、しゃべると皆さん方にうつると思って、今日は黙っていようと思ったんですが、大事なところでありますので、これだけ申し上げます。","voiceIndex":54,"id":"exchange-022"},{"speaker":"林（宏）委員","kind":"意見","question":"教育長の思い、品川の教育関係者の思いがそこにあるというのは理解をします。でもせっかくとったアンケートは、数字を出させるアンケートになるわけです。思いを出させているわけじゃない。だから、目標ではないというけれども、こういうアンケートをこれからも毎年やっていかれるとしたら、ある意味こういうところに結果が出てくるというのは、１つの成果だと僕は思うんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-023"},{"speaker":"築舘委員","kind":"質問・要望","question":"品川区立以外の公立中学校へ入学するということでアンケートをとられていますけれども、これは本当に少ないですけれども、この場合は、品川区にいて、品川区以外の中学へ行くのか、それとも引っ越しとかそういうことでの都合でそっちへ行くのかということと、それから品川区の区外から品川区立小学校、中学校へぜひ入らせてくださいというような要望というか、そういうのはあるのかどうか。","respondent":"古里学務課長","answer":"それと既に転居が決まっていて、ほかの区立中学校へ入るという者についても、このアンケートに集計をされていると聞いてありますので、文字どおりこれは品川区以外の公立中学校、いろいろな形の公立中学校がありますが、そちらへ入学するという数字だと考えております。","voiceIndex":57,"id":"exchange-024"},{"speaker":"築舘委員","kind":"質問","question":"今後小中一貫になると、ますます小学校に入る時点で中学までのことも頭に入れてみんな入るようなことを考えるんじゃないかと思うんですけど、そういう点のことでの、まだ小中一貫はまだ始まったばかりなので将来的にはわからないことですが、中学校の選び方と小学校の選び方というのは多少違ってくると思うんですけれども、その辺のことはアンケートに出ているんでしょうか。","respondent":"古里学務課長","answer":"ただ従来の指定校に入学するというのがまだ６６％という点からは、それぞれの学校が学校の特色ある教育活動あるいは教育改革に、きちんとすべての学校が取り組まなければいけないということを逆に言っているのかなというふうにも思っております。","voiceIndex":61,"id":"exchange-025"},{"speaker":"沢田委員","kind":"意見","question":"そういう人たちが公立学校へ行ったことがむしろ学力形成、人格形成のためによかったんだという状況ができれば、学校選択制の、品川全体で見て公立が選ばれたというのは、ある意味では誉れなんじゃないかなと思うんですけれども、そこらのいろいろ複雑に入り組んだあたりをどう考えたらいいのか、視野に入れていないというだけじゃなくて、思いがあれば聞きたいんですけど。","respondent":"吉村小中一貫教育担当課長","answer":"そのことを重点的にこの小中一貫教育では取り組んでいきたい、こんなふうに思っております。","voiceIndex":63,"id":"exchange-026"},{"speaker":"林（宏）委員","kind":"意見","question":"Ａ学校に従来の指定がされている親あるいは子にとって、その学校がほかの特色があって選んだというよりも、ここへ行きたくないからほかを選んだという意味だろうと思うんですね、１７番の設問に対する答えというのは。７ページの小学校１年のときの親の考え方ね。プライバシーの問題があってわからないのかもわからないけど、行きたくないと指定された学校は知っておくべきだと思うんだな。","respondent":"吉村小中一貫教育担当課長","answer":"今は全体のデータですけれども、これから個別のデータを分析して、そういった要因がどこにあるのかというのをこれからやっていくところでございまして、今まさに準備しております。","voiceIndex":65,"id":"exchange-027"}]},{"id":"topic-03","title":"伊藤中学校の心障学級の設置","agenda":"伊藤中学校の心障学級の設置","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"確認だけします。今、品川区に中学校はどこにあるのかということと、希望的観測しかできないのかどうかわかりませんけど、可能性、申請して認可というか、おりる可能性について教育委員会はどう考えていますか。","respondent":"河野指導課長","answer":"現在、区内の中学校に設置されている心障学級は全部で５校に設置していますが、そのうち現在、八潮中学校については在籍者がゼロということで、休級です。","voiceIndex":72,"id":"exchange-028"}]},{"id":"topic-04","title":"小中一貫教育全国サミット","agenda":"小中一貫教育全国サミット","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"開くコンセプトというか、趣旨が１ページに書かれて、最後の行だよね。義務教育学校設置に向けた法改正に資することを趣旨にということで開かれる。そうすると、日本の義務教育が９年制、枠は９という数字は変えないんでしょう。とすると、４・３・２という形が文部科学省が、見開きの右下に答申も出ているんだけれども、方向はそうなってきているんだというふうに理解しておくほうがいいんですかね。","respondent":"吉村小中一貫教育担当課長","answer":"その根拠としまして、そこの中教審の答申も出ておりますけれども、もう１つ、小中一貫教育ということに関して、例えば品川区の特区を、８０２という特区を受けて、教育課程を柔軟につくっていいよという特区なんですけれども、これについては今、平成２０年度を目途に。","voiceIndex":78,"id":"exchange-029"},{"speaker":"林（宏）委員","kind":"意見","question":"賛助会員のほうは個人まで含めた、いわゆる民間の人を幅広くという考え方なんでしょうけど、この協議会に出ていって、賛助会員の場合、どこまでどういう参加の仕方ができるのか、それから正会員の場合は小中一貫校の設置を目標にしている自治体しか入れないとか、もうちょっと細かく説明をお願いいたします。","respondent":"吉村小中一貫教育担当課長","answer":"そして第３回目もまたそのほかの自治体ということで、これはある程度、何年か継続的に続けていくということで考えております。","voiceIndex":80,"id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"賛助会員のほうは、例えば団体に入っていると５,０００円の年会費を納めて、協議会の、こういうサミットじゃなくて、勉強会というか、何カ月かに一遍やるときに１人参加できるというふうに考えておいていいわけですか。それとも個人個人、１人ずつ、Ａさん、Ｂさん、Ｃさんと入っているという人は、別々の個人的な賛助会員というふうにとらえられるんですか。","respondent":"吉村小中一貫教育担当課長","answer":"は会報を通じて全国の情報を共有するということで、全国に広がりを見せてくると、定期的に集まって協議をするということはなかなか難しいので、基本的には年１回の連絡協議会、そして年１回の全国サミットということを中心に活動していくというふうに考えております。","voiceIndex":82,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりました。見開きのほうに移って、１つは左側のシンポジウムについては、地方分権と義務教育改革、どちらかというと校長であったり、教育委員会であったりというような対象を考えていらっしゃる。幅広い人が来るからこういう、真ん中はそれぞれ分科会ということなんだけれども、一番のターゲットはどういうところに置かれてこれを開かれるんですか。","respondent":"吉村小中一貫教育担当課長","answer":"先ほど言った小中一貫教育、義務教育学校の設置に向けた云々というところになりますと、より具体的な検討が必要になってきますので、そういった部分については午後の分科会でやり、最終的に全体として。","voiceIndex":84,"id":"exchange-032"},{"speaker":"沢田委員","kind":"質問","question":"今の質疑の中で、国のほうは小中一貫教育、あるいは一貫校というんですか。それは規定の方針だというふうに中教審答申でしたかね。それはどういう理由で盛り込んでいるんですか。","respondent":"吉村小中一貫教育担当課長、若月教育長","answer":"ですから、それを今回、昨年の１０月２６日の答申の中に具体的に盛り込んで、検討を進めていきますよと。義務教育学校の設置に向けた検討を具体的に進めていきますよということで今、話が進んでいるです。今、担当課長が答えたとおりなんですけれども、これは何も決まっているわけでも、ゴーだと文部科学省のほうで結論を出しているわけでも何でもないんですが、方向性としては、要するに今の６・３制そのものはそのものとして存続させる。","voiceIndex":86,"id":"exchange-033"},{"speaker":"沢田委員","kind":"質問・要望","question":"今度の教育基本法の改定に当たって、１７条に教育振興計画を教育委員会がつくっていくと。その中の教育課程審議会での議論だったでしょうかね、案として、教育振興計画には何を盛り込むのかというのが議論されて、例えばこんな案ですよといって出されているのが、１つは小中一貫教育、もう１つは学校選択、それから一番トップにかかっているのは学力テストの全国的な実施なんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-034"},{"speaker":"築舘委員","kind":"意見","question":"その場合には連絡協議会に加えていくのか、それともどういうふうになるのかというのが１点と、それから品川区では動員というか、やっぱり少しでも多くの人に知ってもらいたいということがあると思うんですね。教師の皆さんはもちろんでしょうが、保護者の方とか、自治体の方とか、さまざまなところに呼びかけをされるとは思うんですが、どういったところを対象に呼びかけするか、以上２点。","respondent":"吉村小中一貫教育担当課長","answer":"小中一貫教育全国連絡協議会については、先ほど事務局になっている４つ以外に、今のところあと４つと申し上げましたけれども、これについては期限を切るのではなく、ずっと募集は続けていくということで考えておりまして、そういった準備。","voiceIndex":90,"id":"exchange-035"},{"speaker":"築舘委員","kind":"質問","question":"そうすると、分科会のところに三笠市とか郡山市というところも入っているんですけど、そういう市も小中一貫ということでやっているということですか。","respondent":"吉村小中一貫教育担当課長","answer":"ここの分科会を実践する自治体については、かなり進めている自治体と考えていただいて結構だと思います。","voiceIndex":92,"id":"exchange-036"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"私ども会派のほうで検討しまして、ここに載せていただいている特別支援教育ということと、図書館サービスの向上という２点について要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-037"},{"speaker":"沢田委員","kind":"質問","question":"もともと１回しか学びの時期というのはないですから、失敗は許されないんだけれども、ものすごいスピードで実践し、検証しながら進むというより、一気呵成に進んできたことが、取り返しのつかないことになるんじゃないかというのが１つありまして、私自身も文教委員として、広島の呉だとか、北海道の今度発言する三笠だとか、京都だとかをずっと見てきたんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-038"},{"speaker":"本間委員","kind":"質問・要望","question":"２つ目、小学校における英語教育についてということですが、これは国際理解教育とも絡めて、小学校の１年から英語教育についても学習することが、一部世論では、小学校１年生からの英語教育が、ともすると早過ぎるのではないか、そこまでする必要があるのかどうかというふうな巷の議論等々もある中で、本当の意味での小学生における英語教育、国際理解教育とも合わせて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-039"},{"speaker":"築舘委員","kind":"意見","question":"それから子どもの安全対策については、最近親が子どもを殺害するとか、そういった形のことが起きておりまして、地域も絡んでの市民科という教科もできましたけれども、そういった形の子どもの安全というのはしっかりと見ていかなければいけないということで、提言をしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-040"}]},{"id":"topic-06","title":"今定例会の一般質問に関する所管質問ですが、今定例会の一般質問の中で、文教委員会にかかわる項目","agenda":"今定例会の一般質問に関する所管質問ですが、今定例会の一般質問の中で、文教委員会にかかわる項目","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"築舘委員がおられますけれども、この間、一般質問でやった八潮の小中一貫校の構想で、ちょっと聞き取れなかった点があるんですけど、２中学校、３小学校、八潮地区を一体化する方向に決まったかのような答弁があったんですが、これは大変大きな問題をいろいろ含むと思いますので、どんな状況になっているのか、もう少し詳しく説明いただければありがたいなと思います。そのことを聞きたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-041"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"まだでき上がっているわけでもないし、契約については総務委員会だから、それはそれで僕らがここで議論する必要はないんだけど、学校改築については、文教委員会に、ここを直せとかそういう話ではなくて、知っておかなきゃいけない部分ですから、明日報告をいただきたい。だから、その資料提供だけでもしてほしいと思うので、ぜひお願いをしておきたいと思うんですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-042"},{"speaker":"沢田委員","kind":"意見","question":"前回やっていたら大変申しわけないので結構なんですが、先日、都教委で学力到達度テストをやりましたよね。新聞でも報道されているんですが、その結果がどうなのか、どう見たらいいのかというのを、明日忙しければ後日でも構わないんですが、どこかで説明をお願いしたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4574#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":31546,"voices":117}},{"id":"h18-20060626-5","meetingId":"h18-cm06","date":"2006年6月26日","dateIso":"2006-06-26","committee":"総務委員会","time":"午前１０時０３分～午後３時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２、議案審査","agenda":"の２、議案審査","exchanges":[{"speaker":"山村委員","kind":"質問","question":"外国旅行の旅費のところなんですが、鉄道賃と船賃があるんですけれども、これは飛行機の場合はどう変わっているんですか。これがどれに該当するのか教えてください。","respondent":"榎本人事課長","answer":"今回、この条例の改正の中で等級が変わったのが鉄道賃と船賃ということで、航空賃につきましては、３等級以上も２等級以上も、分かれる場合に管理職、係長と同じ等級となりますので、級別で分けておりませんので、今回は改正がなかったという形です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"基本的なところでよくわからないんですけれども、職員の給与に関する条例の改正というところはわかるんですけれども、そのことと市町村合併に伴ってというところがちょっとよく理解しがたいところなんですけれども、その辺のところをもう少し。","respondent":"榎本人事課長","answer":"市町村合併ということで名称を整理したという形です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"言葉なんですけれども、外国旅行というのはよく聞きますが、内国旅行というのは、普通、国内旅行とか、そういうのは聞くんですけれども、役所の中では内国旅行というのが一般的なのかというのが１点と、それと海外旅行に関しては、年度でいいんですけれども、毎年、直近でいいんですけれども、大体何人ぐらいの職員の方が海外旅行には行っているんでしょうか。","respondent":"榎本人事課長","answer":"もう１つの外国旅行の事例ですけれども、去年がたしか議会の海外調査の同行に理事者が行っているという部分が去年あります。それから、その前につきましては研修で行っているということで、一応、研修の中で年１組、大体二、三人が外国旅行に行くという事例があるです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"支度料についてお聞きしたいんですけれども、これは何年ごろこういう制度ができたのかということをちょっと１点聞きたいのと、当時、年代が大分前の時期には、こういう支度料というものも必要な時期もあったのかと思うんですけれども、現在、例えば衣服を調えるとか、そういう小物を用意するとかという意味合いだと思うんですけれども、現在。","respondent":"榎本人事課長","answer":"今の２点目の支度料の関係ですけれども、支度料の関係につきましては、やはり海外に旅行に行くという場合には、大体公務で行く場合には、相手方の、対応するところに応じたものをきちんと用意していかなければいけない、要はどういうレセプションなり。","voiceIndex":13,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"総務委員会ですから、これから約１年やっていく中で契約についての議案というのを多く取り上げてくると思うので、最初なので質問しますが、品川区でという意味ではなくして、いわゆる談合とよく聞かれますが、談合というのはどういうものか、まず説明をしてくださいますか。","respondent":"中島経理課長","answer":"談合についてのご説明ですけれども、今、国の国交省の関連の工事で談合が多くやられていて、さまざま処分等も受けてありますけれども、談合というのは独占禁止法の中で、いわゆる談合禁止という規定がございまして、これはいわゆる工事を発注する段階に。","voiceIndex":26,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"独占禁止法が出てきましたけれども、法律では、当たり前ですが、談合というのはいけないよ、してはいけないという形になっていると思うんですけれども、実質、相談をして、価格を決めて、入札するというのは、何が問題なのでしょうか。","respondent":"中島経理課長","answer":"要するに、法に定めている入札でもって最低価格の業者が落札しますよという大前提の公平な契約行為に違反するということが一番の問題ではないのかなと考えております。","voiceIndex":28,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"具体的に、予定価格がありますよね。いわゆる、その考えで、談合をしなければもっと安い値段で工事ができたのに、談合をすることによって、仲間内といいますか、業者の大体の値段がわかるわけですから、談合で高い価格で工事等を落としてしまうというか、とってしまうということが問題だということでしょうか。","respondent":"中島経理課長","answer":"いずれにしましても、受注業者が事前に相談して価格等、発注件数等を決めるということは、いわゆる法の趣旨の公平な価格競争というものに反するというのが一番の問題であると考えています。","voiceIndex":30,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"初めての、これからいろいろ契約案件が出てくると思いますので、ちょっと私もお聞きしたいんですけれども、区で今、予定価格を提示しておりますが、これは区で予定価格の積算をしているのかと思うんですけれども、どこの部署でやっているのか、また、その積算の単価の基準ですか、それは何かその原本とか、何か書類があると思うんですけれども、それはどの資料に基づいているのか。","respondent":"中島経理課長","answer":"発注をする場合、いわゆる起工と言われている作業があるわけですけれども、これは普通の契約でいくと仕様書みたいなものです。それをつくって金額、予定価格等を算出するわけですけれども、そのもととなっている基準は、国土交通省からの積算基準というものがあります。","voiceIndex":34,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"いわゆる実際は国交省の基準より何％か低い基準で出しているとか、そういうことなんでしょうか。品川区の施設に関して、お願いします。","respondent":"宍戸施設担当課長","answer":"その辺の研究、検討は、国も都も、あるいは区も非常に熱心にやっておりまして、その差額については小さいというか、限りなく民間に近い金額で今は発注していると考えています。","voiceIndex":38,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"もう１点だけ、実際、くいを打つなり何なり、それから鉄筋の太さとか量とか、コンクリートの厚みとか量とか、いろいろ出てくると思うんですけれども、そうするとかなり専門性を持っている人が積算しないと難しいのかなというような感じもするんですけれども、一応、品川区の施設担当ではそういう専門の知識を持った経験者というんですか、そういう方がいて積算をされると考えていてよろしいんでしょうか。","respondent":"宍戸施設担当課長","answer":"それを我々職員も、一級建築士がおりますので、チェックするといったような形で金額を決めているところです。","voiceIndex":40,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"逆に、小さな資本金の会社のほうが高く今回は出ていますけれども、実際、一般常識として、資本金が低いイコール経費がかからない、イコールもっと入札金額は低く出してくるんじゃないかなというような感じを受けるんですけれども、その辺をちょっと、ほぼ似ているというのがあって、大企業のように出しているというふうな感じも受けるんですけれども、ほとんど入札金額が近い範囲で。","respondent":"中島経理課長","answer":"今、資本金と入札価格のご質問がございましたけれども、資本金が大きいところというんですか、が必ずしも入札価格が安くなるといったことは一概には言えないのではないのかなと考えています。","voiceIndex":42,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"この範囲でおさまって、なおかつちょっと金額が上下するというのは不思議なような気もするんですけれども、それは別に当たり前の話でしょうか。","respondent":"中島経理課長","answer":"その際、いろいろな工事のやり方を検討しまして、当然、企業ですから、利益をどのぐらい出すというのを考えた上で、予定価格以内の入札価格を決めてくる。","voiceIndex":44,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"なぜその予定価格というのは出さないといけないんでしょうか。それぞれ例えば１０社なら１０社、２０社なら２０社、場合によっては全国に見積もりを発注すると、見積もりを皆さん出してください、その中で安い会社を選んで、なおかつ、ほんとうに積算根拠がしっかりしているということで皆さん選んでいくと思うんですけれども、最後、その１点だけ、なぜ予定価格を決めなきゃいけないんでしょうか。","respondent":"中島経理課長","answer":"予定価格の公表は、先ほどもちょっとお話ししましたけれども、要するに契約の透明性とか、公平性を確保するというのが一番の目的なのかなと考えています。","voiceIndex":46,"id":"exchange-013"},{"speaker":"藤原委員","kind":"確認","question":"委員長のご配慮で、最初だから聞かせていただきますが、質疑を聞いていて、ほんとうによくわかってまいりました。予定価格があるんだから、それで区がちゃんと審査をするわけですから、工事に関しても安かろう悪かろうにはならないわけですよね。だから予定価格より安くなったほうがいいのは間違いないと思うんですが、まずそこは確認したいんですが、お願いします。","respondent":"中島経理課長","answer":"私ども発注者側とすれば、それはよい仕事を安くしてもらえれば、それが一番いいと考えています。","voiceIndex":49,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"この目黒川右岸低地部というこの議案なんですけれども、これは予定価格の何％でこの７番目の業者は落としているんでしょうか。","respondent":"中島経理課長","answer":"予定価格が１２億４,２２６万４,０００円に対しまして、１１億５,５００万円ですので、いわゆる落札率といいますけれども、これは９２.９７％になってあります。","voiceIndex":51,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"例えば、申し込んだところが１０社あったと、その１０社がどこだかわからなければ、談合というのは起きようがないわけですよね。今のシステムで、例えば１０社だったら、その１０社はわからないシステムになっているのか、もしくはわかってしまう逃げ道というか、調べようによっては１０社がわかります、それとも全くどこがやっているのかわからないんです、それはどっちでしょうか。","respondent":"中島経理課長","answer":"それでＡグループの大きい会社とどの会社と組みますかというのを明らかにした上で、事前に２社で組んでもらった形で参加していただくということになってありますので、すべての会社が、どこが参加しているかというのはわかるようになってあります。","voiceIndex":53,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"何回も同じことを言いますが、品川区でという意味じゃなくして聞きますが、わかってしまうということは、競争の透明性とかもあるから談合をしてはいけないわけですから、その入札に参加した会社の良心というか、やってはいけないんだということに期待をしなければ、システム上、談合をとめるということはできないということですか。","respondent":"中島経理課長","answer":"ただ、今、談合は問題になっておりまして、独占禁止法もだんだん厳しくなっているというようなこともございまして、今、企業の中で一番言われているのは、いわゆるコンプライアンスと言われていますけれども、法律なり規定なりをきちっと守っていこうと。","voiceIndex":55,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"契約内容でお聞きしたいんですけれども、今回の工事の場合、その１、その２、その３とかとつながっていくシールドを主体にした工事ということですけれども、どちらかというと、一番大きいのはそのシールド機ですか、シールドマシンみたいなものにかかわるものが大きいものかもしれませんけれども、今回の契約から次の契約、その３があるとすればその３という契約になったときに、同じ工事をやって。","respondent":"原田下水道河川課長、石田委員長","answer":"例えばシールド工事を例にしますと、シールドマシンがありまして、横に発電機があって、シールドマシンを動かしてトンネルを築造していくわけですけれども。だからその説明をしないと、今の話じゃ全然、全部使い捨てになっちゃうから、シールド掘進機そのものの東京都の、ストックするとか、それが使えたら。それは今回の工事の中で通常どおり使って、損傷が得にひどくなく、またすぐ次の工事に使えるということがあれば。","voiceIndex":57,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"ということは、この１１億５,５００万円の価格の中に、減価償却分というのか、ここで使う機械が新しいものか古いものかはわかりませんけれども、予定価格をつくるときに、その辺がどういうふうに加味されるのかをちょっと教えていただけますか。","respondent":"原田下水道河川課長","answer":"その次にどこかで使う場合は、それを使って、一回別の現場で使ったものを使うという判断のもとで設計で金額を定めて使っているということになります。","voiceIndex":61,"id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、ちょっと次の工事がよくわからないんですけれども、その３工事でまたシールド、全体計画のまだ半分ぐらい残るんですかね。そのときには、今回のように、概要書にあるように、このシールド機というのは含まれないことになっていくと解釈していいんですか。シールド機に限らず、転用する機材ですが。","respondent":"原田下水道河川課長","answer":"例えば、その３工事でいけば、今のところシールドマシンは設計金額に入れてません。","voiceIndex":65,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"そのときに、今、この整備事業は水位が上がらないという前提で、結局、湾に流すということなんですけれども、近い将来なのか遠い将来なのかわからないんですけれども、今、世界各地で水位が上がっているということならば、いずれ流れなくなれば、その貯留管というんですか、その管の中にたまりっ放しという事態も将来起こり得るというふうな考え方でよろしいんでしょうか。","respondent":"原田下水道河川課長","answer":"ただ、海の水位が確かに最近少しずつ上がっているということは聞くんですけれども、まだ確かにそれほど見て実感するほどでもないですから、ほんとうに劇的に地球温暖化の問題によって大きく海面が上昇することになったら、確かにそこまでは見込んでいませんので。","voiceIndex":67,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、発想として、放流というよりはやっぱり貯留ということが、今現在じゃないですけれども、すぐということじゃないですけれども、やはりそういう事業のほうがいずれは大切になってくるような状況もなる、それとも別の方法論というのがやっぱり出てくるんでしょうかね。その辺は何か将来的なビジョンとして、こういうふうに考えていますよというのは出ているんでしょうか。","respondent":"原田下水道河川課長","answer":"目黒川の水質の問題ということで、目黒川周辺は下水道が合流式下水道で整備されていますから、雨の日に雨が川に放流されるというのは、その中に汚水も一部まざった状態で放流していると、そういうことですから、一度普及が終わって、その次の段階として。","voiceIndex":69,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"そうじゃなくて、将来、今の放流事業のほかに何か新しい事業というのも、いずれ水位が、今、問題が出たのでついでにお聞きしたかったんですけれども、その先々の考えというのは何か出ているんでしょうか。構想というのは。","respondent":"原田下水道河川課長","answer":"水位が上がることに対して、その次にどういう事業をするかというところまでは検討しておりません。","voiceIndex":71,"id":"exchange-023"},{"speaker":"菊地委員","kind":"質問・要望","question":"契約の内容でお聞きしたいんですが、今回は第２期解体という、１,９３０m2入っていますけれども、前回、本体の契約をした際、解体工事というのはまた別の契約だったのですけれども、この辺の振り分け方というのか、考え方を教えていただきたいというのが１つです。","respondent":"宍戸施設担当課長、中島経理課長","answer":"そういう意味では、責任が一体的になっていたほうが後々の何か問題が生じたような場合にも対応していただきやすいというようなことがございまして、今回、外構にあわせて解体を発注するように経理課長と相談したという経緯があります。そういった意味では、今回はたまたま区外の業者が落札したです。","voiceIndex":84,"id":"exchange-024"},{"speaker":"菊地委員","kind":"意見","question":"解体については、近隣に大変な迷惑をかけた工事だったというので、確かに私も苦情的なところを聞いていますけれども、この辺のちょっと、さっき分けたために責任の有無があいまいになったという話がありましたけれども、そのことと、今回一緒に解体工事を発注したこととはまた違うのではないかなというような気がするんですけれども、そこは行政。","respondent":"宍戸施設担当課長、中島経理課長","answer":"解体業者の対応の悪さという意味ではない責任の一本化というのが図れるという意味で申し上げたところです。工期が年度内に限られているというようなこともありますので、そういった意味では、品川区内の業者に限定してやったときに、果たして責任を持った工事ができる業者がいるかどうかということもありますので。","voiceIndex":87,"id":"exchange-025"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう１つ、これは意見なんですけれども、これも調整云々と言われちゃうと確かに全然見えないところですから、何とも言いようがないんですけれども、ただやっぱり最低限、今みたいな厳しい状況の中で、ほんとうに区内の業者ができるといえば、こういう学校ですとか、超高層をやれといったって無理な話ですから、学校ですとか、こういう公共施設というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-026"},{"speaker":"菊地委員","kind":"意見","question":"意見表明すると、総務委員会ですので、直接の内容についてどうのこうのというのは聞けない内容ですけれども、というのは、私は小中一貫校、それから一貫教育というものはまだまだ区民の理解を得ていないという部分をたくさん持っているものだと思いますし、教育の内容についても、やっぱり競争教育激化をさせている、こういう立場におりますので、本体工事についても反対をしておりますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-027"},{"speaker":"山村委員","kind":"質問・要望","question":"ちゃんと確認していただきたいと思います。それと、最近、防火扉の話があったと思ったんですが、そこら辺はいかがですか。","respondent":"宍戸施設担当課長","answer":"防火シャッターですけれども、面積の区画などの際、小山小学校でも使うことを予定しております。昨年の１２月に建築基準法が変わりまして、シャッターにつきましては、障害物があればセンサーで感知して一たんとまるということになってあります。","voiceIndex":103,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"すとんと落ちているんですけれども、当たり前の話ですけれども、先ほどの初めの質問で、安かろう悪かろうは審査が厳しいからないですよということは、大体お返事はわかりますけれども、やっぱりこれでまず大丈夫でしょうかという質問と、なぜそこにいくかというと、２億７,２００万円余の予定価格で、六千何百万円も落としちゃって、工事はほんとうに大丈夫なんでしょうかという思いがあるんですけれども。","respondent":"中島経理課長","answer":"１点目の大丈夫ですかというご質問ですけれども、これは予定価格からいたしますと、落札率が７６.８６％となっています。","voiceIndex":107,"id":"exchange-029"},{"speaker":"須貝委員","kind":"意見","question":"実際、今回、小山小学校改築工事、新築ということで始まるわけですけれども、一般的に、役所でつくる建物あるいは役所で使う公共物、公共の建物に対して、一般の区民は役所でつくる建物については、耐震等、安全基準をさらに上回って、安全基準度の高い建物をつくっているんだと私らも思っていたわけなんですけれども、特に耐震基準に対して、今回。","respondent":"宍戸施設担当課長","answer":"耐震基準なんですけれども、昭和５６年にいわゆる新耐震基準というのができまして、それまでの建物の強度という考え方に、バランスですとか、あるいは地震の強度の想定につきましても、それまでより大きいものを想定して、基準が大きく変わりました。","voiceIndex":109,"id":"exchange-030"},{"speaker":"須貝委員","kind":"意見","question":"その割合的に、今の新耐震基準に対して何割ぐらいの、先を見越して新耐震基準をさらに上回った割合で想定して建てていると思うんですけれども、その割合というのは今、出ませんか。大体これぐらいのめどでというものが。","respondent":"宍戸施設担当課長","answer":"余裕は見ての設計はしていると思いますが、きちっとクリアをしているという内容です。","voiceIndex":111,"id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"現在、クリアしているということですけれども、やはり今、震度７、震度８とか震度９とか、そういうせっかくつくるならば、これから３０年、４０年、場合によっては５０年先を見越してつくるかと思うので、また、地域の皆さんの避難場所にもなりますので、その辺は十分考慮して、まだこれから取りかかるわけですから、耐震基準をさらに上回るものを設計して建ててほしいと思います。","respondent":"中島経理課長","answer":"発注の問題ですけれども、例えば、超スーパーゼネコンに発注すれば、できない工事ではないという、ただ、私どもこの間ずっとご説明しておりますが、契約の基本はまずは業種単位に発注していくというのが基本になってあります。","voiceIndex":113,"id":"exchange-032"},{"speaker":"菊地委員","kind":"質問・要望","question":"設計段階の話なのかもしれないんですけれども、現地で説明を受けたときに、マルチルームというのがすまいるスクールの部屋になっていくという話だったんですけれども、現地を見たときに、今のすまいるスクールというのはかなりのスペースをとって運営をされているようなんですけれども、現状のスペースと、これから新しい設計でのスペースの違いをまず教えていただきたい。","respondent":"宍戸施設担当課長","answer":"すいません、ちょっと面積比較という意味では資料を持ち合わせていないんですが、考え方ですが、すまいるスクールも、そのすまいるスクールの時間帯にはアリーナですとか、のびのびスペースですとか、学校の一定のエリアを使う、それから。","voiceIndex":115,"id":"exchange-033"},{"speaker":"菊地委員","kind":"意見","question":"ちょっとあんまり中身に入ると、ここでは答えられない中身になっちゃうんだと思うんですけれども、３００人からの、今、児童数で３００人弱ぐらいになっているんですけれども、区の施設としてどうなのかなという感じがしましたので、使い方として、ちょっとこれから何かでご報告があるのかもしれませんけれども、その辺はちょっとぜひご報告を願えればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-034"},{"speaker":"若林副委員長","kind":"質問","question":"それからもう１点は、区道を挟みまして、敷地内の床の、いわゆる歩道橋という言い方でいいんでしょうか、橋をかけておられますが、例えばこれはアリーナが地下にあるということで、景観の問題も含めて、例えば地下を掘った、地下通路をつくったときには、それはご検討されたのかどうか、また、検討された場合には、どのぐらいの金額がかかるのか、この２点ほどをお聞かせいただければと。","respondent":"宍戸施設担当課長","answer":"この度建築基準法が改正になりましたので、天井高については３ｍを切る形に今後はなっていくのではないかなと考えております。まだ何ｍにしようというふうな具体的な数字までは申し合わせはしておりません。","voiceIndex":118,"id":"exchange-035"},{"speaker":"菊地委員","kind":"質問・要望","question":"２点お聞きしたいんですけれども、公園は今回ですべて終了するということですけれども、今回の場合、下はポンプ所ということで東京都の下水道局が管理するんですか。","respondent":"中島経理課長、日下部企画財政課長","answer":"それと、橋本産業の関係ですけれども、申しわけございません、私は詳しく承知しておりませんので、後ほど誤解を招いてしまうといけませんので、私からのお答えは控えします。確かにこちらの道路から入るような進入路といいますか、そういう形の設定ができておりませんので、天王洲側あるいは反対側から回り込むと、もうそういう形をとらざるを得ない、そういう状況です。","voiceIndex":134,"id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"ポンプ所なんですけれども、ちょっと整備された状況というのがよくイメージできないんですけれども、ポンプ所外構に沿って、今ある道路のほうからエレベーターがついてみたいな図面がありましたけれども、管理の形態として、もちろん中は、建物の中についていえば、もちろんポンプ所ですから東京都の下水道局が管理するんでしょうけれども、区として管理するのはどの部分に当たっているのか。","respondent":"日下部企画財政課長、中島経理課長","answer":"その上部に公園が造成されているという形ですから、いわば上下分離で、下はもちろん下水処理と、上部の公園に相当する部分については、あくまでも区で一括して管理をすると、そういう形です。企画財政課長の補足ですけれども、屋上部分ですけれども、これは区と下水道局の間で、屋上等を公園として利用するということになっておりますけれども。","voiceIndex":137,"id":"exchange-037"},{"speaker":"菊地委員","kind":"質問","question":"今、課長がおっしゃった部分と大分違う話なんです。都市計画公園として整備をするということをしてきたということと、そういう契約は交わしていないという話をしているんです。どっちが正しいでしょうか。","respondent":"日下部企画財政課長","answer":"私の発言がちょっと誤解されるような表現をしておりました。経理課長の発言がまさしく、いわば都市計画公園とは分離する形でという形、そちらのほうが正しい中身です。失礼いたしました。","voiceIndex":140,"id":"exchange-038"},{"speaker":"山路委員","kind":"質問・要望","question":"公園の部分ですけれども、先ほど見せていただいたんですが、平成８年に一般質問でお願いしていたあずまやとか、高齢者の方が座るところということで、その後検討して、それがだめで、昨年の決算特別委員会でお尋ねしたときに、ハーブと健康器具もつくっていただきますが、パラソルか何かをつけるという答弁をされていますね。","respondent":"中島経理課長","answer":"大変申しわけありません。承知しておりません。後ほど管理工事課長に確認して、改めてご答弁させていただきたいと考えています。","voiceIndex":142,"id":"exchange-039"},{"speaker":"塚本委員","kind":"意見","question":"駆体の上に公園が乗る、ほんとうに新しい考え方で、あの辺に公園が集積して、回遊型のいい公園になると考えていますけれども、そういうことによって経費がかさむことになってはやっかいですが、あれはどういうコストアップがあって、それはどっちが負担しているのかということが１点と、それから、エレベーターの運転費、維持管理費はおよそどんな概算をしているのかという点を。","respondent":"中島経理課長","answer":"公園として整備するわけですので、先ほどもちょっと菊地委員からの説明もございましたけれども、維持管理は当然品川区の責任で行うということで、エレベーター等につきましても、品川区で管理していくです。","voiceIndex":144,"id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"コストアップ、駆体はもちろん強くしなきゃいけないという、メンテ費も余計にかかるだろうということはどういうふうな考えを持っているんですか。","respondent":"日下部企画財政課長","answer":"大変申しわけないんですが、私もちょっとその辺について実情を把握しておりませんので、その辺は早急にまた調べまして、ご報告をさせていただきたいと思います。","voiceIndex":146,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1722#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":36045,"voices":157}},{"id":"h18-20060627-6","meetingId":"h18-cm06","date":"2006年6月27日","dateIso":"2006-06-27","committee":"区民委員会","time":"午後２時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、燃やすようになった経緯等々、いろいろと説明がありましたけれども、まず一つ目に伺いたいのは、東京都と国の方針がどういうことだということで、それを受けて、品川区もサーマルリサイクルをするようになったという趣旨なんですが、今までやってきたリサイクルと、国の方針を受けて変わってきたという、そこのところを改めて、品川区はどういうふうにお考えになって、方針転換をされたのか。３点です。","respondent":"中山資源循環推進課長","answer":"１点目の、２３区の方針、変更の考え方ということですけれども、組合との交渉というのは、確かにプラスチックの熱利用を含め、東京都においては、最終処分場の計画がもう、埋立不適物と定める、そういう意味じゃ出口の報告が出ている中で、２３区はどうするかですけれども。","voiceIndex":7,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、どんなに口をそろえて、こういう理由がある、ああいう理由があるんだとおっしゃったにしても、そういう区民をもう現実につくっているという、そこのところはどういうふうに見ていくのか、そこを聞きたいし、やっぱりごみを出さないという努力、ここが根本から崩れてきていると思うんです。その点についての見解を、１点目のところでは伺いたいと思います。だから、そういう点で見解を。","respondent":"中山資源循環推進課長、岩崎環境清掃事業部長","answer":"今おっしゃったような、そういうふうにとられるということがないように、それはモデル実施以降も、説明をやっていかなければいけない、そういう意味で分別の後退になってはならないという認識です。先ほど来の質問の中で、国と東京都という流れについて、とりあえずの説明があったんですけれども、きのう、東京都の審議会がありまして、それを手に入れましたら、今の論点についても触れられているので、個人的に説明したいんです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"ちょっと今のところで、国だとか、東京都が一定程度、先に答申という形で、そういう見解を出して、言葉は悪いですけれども、各自治体に押しつけると、私は、そういうふうに受けとめますけれどもね。そういう答申の中身について。ですから、やっぱり燃やして有害物質になるようなものを排出させるという選択は絶対にやめるべきだと思うので、改めて、そのことだけ強く申し上げて、とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"本田委員","kind":"意見","question":"理事者の説明の中で、よく理解できないところがありましたので、お尋ねします。３ページ、廃プラスチックの処理の現状のところで、品川区から出されている廃プラスチックが、可燃ごみの中にも入って、現実に燃やされているという説明がありました。ちょっとその辺が、先ほどの説明では、よく理解できないところがありましたので、もう一度、数字を含めてご説明を願います。","respondent":"中山資源循環推進課長","answer":"これが約６割が最終処分量です。したがいまして、平成１６年度の最終処分量の実績としては、年間約９０万ｔ。この表にありますように、平成２２年度以降、分別変更されますと、４０万ｔになっていく、もしくはそれ以下の数値になっていくです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"サーマルリサイクルにした場合に、廃プラスチックの割合が、１４ページに、既に実施している各都市の例が幾つか書いてありますね。別の資料では、１０％ぐらいと言っているのを見たことがあるんですけれども、どのぐらいを推定しているのか、その辺はどうでしょうか。","respondent":"中山資源循環推進課長","answer":"２３区で、今、ワーキンググループを使って、その辺の検討を進めております。今、本田委員からもございましたように、可燃ごみの中のプラスチックが約１０％に増えると見込んでおります。","voiceIndex":15,"id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"つまり、このリサイクルをかなり積極的に進めていくんだという裏があって、こういう低い数値を見込みとして出しているのか。ほかは１５％、今言われましたように、福岡市では１９％というふうに高いわけですけれども、１０％というのは、見込みが低いんじゃないでしょうか、そこはどうとらえているんですか。","respondent":"中山資源循環推進課長","answer":"品川区の場合は、拠点回収で白色トレーの回収もあるわけですけれども、一部の区では廃プラスチックのモデル実施をもう始めている。これもコストであるとか、実際の出口がどうなのかというような検証が必要なわけですけれども、この辺を検証していく。","voiceIndex":17,"id":"exchange-006"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから、その思想は私は重要なことだと思います。それでも有限ですね。その後、どうするんだと、品川区から出されたごみをどこで処理するのか。ですから、我々今生きている者が精いっぱいできることといいますか、今の日本の化学の高い水準を使いながら、できることをやらなければならないと思っています。そういう点を施策の中でしっかりと押さえてやっていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"土井委員","kind":"質問・要望","question":"これはまさしくもったいない話でございまして、石油と全く同じものですから、これはやっぱりそういう回収の仕方も含めて、しっかりやるべきものだと思うんです。あんなものはマテリアルしてめちゃくちゃにしてしまったら、またつくるのに金がかかるんですから、非常にもったいない話なんです。だけれども、それが行われていない。これは当然のことだというふうに思っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"堺委員","kind":"確認","question":"確認しておきたいのは、請願第９号の中に、下から４行目のところで、「区はモデル回収地域を決め進める方向で５月３１日住民への説明を行いましたが、昼の時間帯で１度だけの説明会で」と書いてあるんです。平成２０年度から本格実施するに当たって、品川区は、他の３区と合わせてモデル実施をして、そういう中で、いろいろな検証をしていく。その辺でまず、お聞かせいただけますか。","respondent":"中山資源循環推進課長","answer":"再度、確認ということで、こういう趣旨も含めた周知を現在行っているところです。それから、現在、７月２０日、２６日と予定しておりますけれども、該当地域で実施して以降、実際に区民の方も含めて、再度ご説明を考えております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"堺委員","kind":"質問・要望","question":"先ほどの説明の中でも触れられておりましたが、念のためちょっと確認をしておきたいのは、請願第７号の要旨の１のところには、「廃プラスチック焼却には、生活や健康面で大きな不安があります。それから重ねて、品川区としては、今回、このモデル実施については、品川清掃工場で燃やすんですか。品川清掃工場が先般でき上がった際にいただいた資料にも、公害防止基準が出ていますよね。","respondent":"中山資源循環推進課長","answer":"今までのこういう対応を含めて、区民にご安心をいただくように、清掃工場のほうにも伝えていきたいと考えております。","voiceIndex":24,"id":"exchange-010"},{"speaker":"堺委員","kind":"質問・要望","question":"そうすると、先ほども委員がおっしゃっておられましたように、きょういただいた資料の中の１５ページ、実証確認の基本的な考え方の中にもいろいろ、こういうところを確認し、解析をしていくんだと出ております。そういう積み重ねによって、区民の皆さん方が安心し、ご理解をいただけるだろうと思いますので、この辺については、重ねてきちっと公表、公開していただきたいと要望しておきたいと思います。","respondent":"中山資源循環推進課長","answer":"実際にもうめどが立たないということですから、これは４０年、５０年、６０年、１００年としていかなきゃいけないということです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"堺委員","kind":"確認","question":"ちょっと経費の面で確認をしておきたいんですが、いただいた資料の１５ページには、中間処理過程で約５２億４,０００万円の経費削減となるとありますが、この廃プラサーマルによる効果として弾き出しているんですけれども、いただいた資料によりますと、約４０億８,０００万円の経費削減、これは平成２１年度の、対平成１９年度との比較となっているんですけれども、となると。","respondent":"中山資源循環推進課長","answer":"毎年、この変更による継続的な比較効果が出てくるという数字です。","voiceIndex":28,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"皆さんのいろいろなご意見を伺いながら、私は質問を１点だけしたいんですけれども、プラスチック類を生産している事業者に対する責任を果たさせるという、排出者責任、拡大生産者責任のところなんですけれども、そういう意味合いにおいて、国あるいは東京都の役割分担をそれぞれしていくということは承知しているんですが、そういうところの指導は、どこまで、どういうふうになっているのかということを。","respondent":"中山資源循環推進課長","answer":"拡大生産者責任そのものは法の定義にはございませんけれども、そういう趣旨というのは、先ほどの容器包装リサイクル法、あるいは各リサイクル法の中で、現実に、利用者負担によるリサイクルの仕組みとして、家電リサイクルですとか、パソコンリサイクルですとか。","voiceIndex":30,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"そういう担保なしには、サーマルリサイクルはいいですよとは、私は言えないと思うんです。もっともっと、品川区はこういうふうにやってきているし、こういうふうにやりたいと思っているんだということを、このごみ行政の分野でも、資源の問題でも、やっぱり声を大にして言っていただきたいということを、あわせてお願いしておきながら、そういう意見を述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"最終処分場が２０年延びるということで、４０年ぐらい先に延びたら、その後はわからないということで説明を伺いましたけれども、素朴なところで、区民が、自分たちの生活から排出したごみがどのように流れていて、どのように処分されるかというのは、役所の方たちが説明をされて、区民はどれだけの問題意識を持っているのか。","respondent":"中山資源循環推進課長","answer":"ですから、今回のごみの分別変更を含め、一層こういうごみ処理の現状であるとか、できるだけわかりやすく説明し、決して分別が停滞することのないように、きっかけにしていきたいと考えております。","voiceIndex":36,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"今の時点では、やはり私たち末代までの心配をする、しないは個人のあれですけれども、先ほど、お伺いしたように、最終処分場はもう使えなくなってしまうんだと、東京都のごみが最終処分されて埋立地のキャパシティがなくなってしまうんだというような問題意識というのは、実際のところ、区民は持たれていないと、今は考えてよろしいのか。","respondent":"中山資源循環推進課長","answer":"ですから、かなり総数としては、ごみ量として反応している部分については、認識は浸透したと思いますけれども、いま一歩のところについての工夫をしていく必要があると考えています。","voiceIndex":38,"id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"両方とも、区民からの意見、要望を取り入れてくださいということで、きのうもお話があったんですが、説明を十分に果たしていただきたい部分がありますし、一般の生活をされている方、今までの行政側のご苦労があって、ごみを分別するという、分別収集ということに関しては非常に意識を持つようになりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-017"},{"speaker":"大沢委員","kind":"意見","question":"今、皆様、さまざまなご意見をいただきましたが、私ども、本日、結論を出すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-018"},{"speaker":"本田委員","kind":"質問・要望","question":"要望として一つありますけれども、結論はきょう出すのがいいでしょう。区民のサイドから見れば、なかなかこういう実態というのはわからないものが多いものですから、できれば簡潔なそういう説明も、産業界の取り組みなどについても、要望と同時に、今、どこまで進んでいるのかなどについて開示いただければいいなと、お願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"本田委員","kind":"質問・要望","question":"そういう要望についても、ぜひ行政サイドは取り組んでいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"堺委員","kind":"意見","question":"私も、きょう、結論を出すということをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-021"},{"speaker":"堺委員","kind":"質問","question":"今、委員長は請願第７号とおっしゃっているんですけれども、請願第７号と９号と別々にするんですか。質疑は一緒にして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-022"},{"speaker":"堺委員","kind":"確認","question":"説明も一緒にして、質疑も一緒にやったので、取り扱いも一緒でもいいかなと思ったんですが、ちょっと確認をしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"請願第７号については、３項目あるということで、２点目の拡大生産者責任については、先ほど、本田委員も、国の資料をお持ちになって、そういう状況もぜひオープンにしていただきたいという要望もおっしゃっていましたけれども、やっぱり私もそのとおりだと思うし、品川区は、国を通じて関係のところで言っているというお話ですけれども、なかなかそこは、率直に言って不十分なところだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-024"},{"speaker":"堺委員","kind":"質問・要望","question":"この件については、たしか本会議の初日でも、紹介議員の関係者の会派の方から出してもらうように取り上げられていたと記憶しているんですが、その辺も踏まえまして、またきょうもいろいろ議論をしている中で、請願者の方々が言わんとしている点については、ある程度理解できる部分もありますが、私も何点か要望した点もありますし、それも入っていますので、全体的には、この請願そのものについては、私は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"今後はやはり、先ほど、私、質問させていただいたように、区民へ十分な説明をされて、大気汚染という一番心配な重要な部分のところに十分に留意されて、この事業を進めていただきたいと思いますが、この部分に関しては、もう既に行われていることですので、願意に沿いがたいということで意見を表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"土井委員","kind":"質問・要望","question":"この大願意のところには、とてもとても沿いがたいと考えています。そういう中で、そのほかの項目についてはいろいろと説明もありましたし、また皆さんのほうからもいろいろな要望、意見等が出されているわけで、説明の問題とか、情報開示の問題等々は、当然きちんとやっていただけるということが大前提になっておりますから、その意味では、願意に沿いがたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-027"},{"speaker":"本田委員","kind":"質問・要望","question":"私も一括して、採決をしていただきたい。先ほども意見を申し上げましたが、何よりも、この請願とは考え方が違います。環境行政をしっかりと進めていただきたい。報告についても、申し上げました。特別区長会の決定については、このことを真摯に受けとめておりますので、しっかりと環境行政を進めていただきたいという立場です。","respondent":"川西委員長","answer":"ご意見をいただきましたので、平成１８年請願第７号について、採決をいたします。本件については、挙手により採決を行います。本件につきまして、採択とすることに賛成の方は挙手を願います。","voiceIndex":69,"id":"exchange-028"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、プラスチックごみの焼却は中止をしてくださいという、非常に強いご要望がありますが、まさにそれに関してはいろいろと議論の余地があると思われますので、願意には沿いがたいという判断をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-029"},{"speaker":"堺委員","kind":"質問","question":"私も、先ほどの質疑の中で、住民に説明し、それについては、先ほどの出た結果については公表し、公開してほしいと申し上げました。ただ、先ほどもご意見が出ておりましたように、この請願の願意は、プラスチックごみの焼却の中止ですから、この件については、請願第７号と同じように、私としては願意に沿いがたいと判断しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"これを進めていけば、それだけ自治体負担が増えるという仕組みにならざるを得ませんので、そういう点でも、ぜひ、ごみは焼却しない、リサイクル等々のさまざまな策を、ほんとうに講じていかなきゃいけないと思いますので、私としてはぜひ採択していただきたいと考えています。","respondent":"川西委員長","answer":"今、ご意見をいただきました中で、採択、あるいは不採択と両方に分かれておりますので、本件について、挙手により採決を行います。本件を採択とすることに賛成の方は挙手をお願いいたします。","voiceIndex":76,"id":"exchange-031"},{"speaker":"南委員","kind":"意見","question":"質疑終了後ということなんですけれども、私は、できたら質疑をするに当たって、ここに意思は垣間見られるんですけれども、直接請願者の方々から、質疑する前に聞いたほうがいいじゃないかなと思ったので、今、委員長が質疑終了後に諮るというお話だったので、前段に受けたほうがいいんじゃないかなという意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"今、申し上げましたこととそんなに差はないんですけれども、かなり青年の現状が厳しいと聞いておりますし、社会問題になっていると認識しているんです。ですから、この請願された方々が、どの程度そういう状態にあるのかということは、ちょっとわからないんですけれども、だからこそ、具体的な話を伺いたいと思いますので、審査の前に受けていただけるように、私はお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-033"},{"speaker":"土井委員","kind":"質問","question":"意見陳述以前に、いろいろな状況があるということで質問があれば皆さんやっていただければ結構なんだろうと思うんですけれども、意見陳述というお話だけに絞ってお話をするならば、この請願代表者の属されている団体等々を考慮すれば、少なくともその種のご意見をいつも発表されているところですから、我々としても、ある程度わかっておりますので、いらないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと今の発言は理解しがたいんです。ちょっとその発言は、私の物差しでは不適切だなと思いますし、ぜひ、そういう点で、受けていただけるように、皆さんにお願いをしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-035"},{"speaker":"堺委員","kind":"質問","question":"私も、今、お二方の委員がおっしゃっておられましたように、結論的には、意見陳述の必要性はない。理由は、今回の請願の紹介議員になっている３人のうちのお１人が、去る６月２２日の本会議の一般質問の中でも、同趣旨のことを取り上げておられましたので、その方の発言で意見の趣旨は取り上げられたのではないかなと理解をしますので、私どもは、その本会議の中で一般質問をお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"そういう状況で、やっぱり青年の方々の働く状況は厳しいと聞いているんですけれども、そことの関係で、やっぱり私はいろいろな働く立場の人たちの職業に対する認識とか、あるいは雇用主との関係の基本的な考え方というのを、やっぱり伝えていく必要があるんじゃないかなと思うんですけれども、そのあたりの認識はどういうふうに考えておられるのか、伺いたいと思います。","respondent":"金子産業振興課長","answer":"ここのところ回復基調がずっと続いておりますので、まず景気がよくなってきつつあるという中で、雇用の状況が改善してきている。もう一方で、２００７年問題に象徴されるように、団塊世代の大量の退職が見込まれる。","voiceIndex":96,"id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"産業振興課長の今の説明では、青年の方々が、２００７年問題等々でも、これからは改善にいくだろうという推測にすぎない、そういう状況にとどまらざるを得ないという事態だと思うんです。契約と違う仕事をさせられている。そういう状況で働かされている。その辺の形態をちょっと伺いたいのと、ぜひ問い合わせをして確認をしていただきたいと思うんです。港区でも、増刷を３,０００部ぐらいしていると。","respondent":"金子産業振興課長","answer":"他区の対応ですけれども、先ほど申し上げたとおり、承知しておりませんが、私どもとしましては、少なくとも、例えば増刷してから配るところを考えるとか、そんなような後先の順序が違うようなことは、当然、考えておりませんで、むしろ、先ほど申し上げたとおり。","voiceIndex":98,"id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"例えばリサイクルの問題でも、いろいろなところに出せるということが大事だというので、品川区が進めてきた経緯があると思うんです。東京都がやっているからいいよということではなくて、版権も無料ということになっているわけですから、ぜひここは、すぐさま調査をしていただいて、検討していただきたいと強く要請しておきたいと思います。","respondent":"金子産業振興課長","answer":"これを申し込んだ動機といいますか、区としての考え方ですけれども、私どもも、雇用について、労働法制の変更によりまして、区市町村の役割が少しずつ拡大してきておりますので、今後の労働情勢の情報収集等も鑑みて、実際の対象は、働いている人。","voiceIndex":100,"id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"終わりますが、最後に要望だけ。全国４０カ所のうち、昨年手を挙げて、今年ようやく該当したという点では、青年雇用の分野のところを、最近積極的に品川区も取り入れて実施しているというふうに、私は承知しておりまして、評価をしたいと思っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-040"},{"speaker":"土井委員","kind":"質問・要望","question":"この請願を出された代表者の方だと思いますけれども、お尋ねいただいて、ご説明をいただきました。そういう中で、この皆さんに申し上げました。ですから、きょうここに出されましたこの請願等々につきましても、やはり、そのような形で運動されるべきだろうと、したがって、これを採用することは、かえって若い人たちの芽をつむことになりかねないという気持ちでおるんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-041"},{"speaker":"堺委員","kind":"確認","question":"あるいはこの事業はいつまで続けられるのか、続けるのか、その辺も含めた、ヤングキャリア・ナビゲーションという事業そのものの概略を、ご説明いただけますでしょうか。この件についてはもう一遍、たしか、東京都のホームページで見れますということをどこかで聞いたような気がするんですけれども、その辺を確認で教えていただけますか。","respondent":"金子産業振興課長","answer":"この事業は、平成１７年６月１５日から始まっていまして、約３年間というふうに聞いてあります。ですので、私どもは今年度が１年目ですが、特に国のほうの事業等の変更がなければ、今年度に加えて来年度も可能ではあるという仕組みです。","voiceIndex":104,"id":"exchange-042"},{"speaker":"堺委員","kind":"質問・要望","question":"それからもう１点、確認で、これは３年間の事業で、区としては今年と来年、約２年間行われる。そんな意味で、実績を見た上でということが前提になるのかもしれませんが、希望としては、せっかく２年間できるということであれば、２年間そうやってチェックして、実施していただければなという気がいたしますけれども、それについてはいかがでしょうか、ご見解があれば、教えていただきたい。","respondent":"金子産業振興課長","answer":"来年の問題ですけれども、ご指摘のとおり、仮に実績が上がらない場合に、厚生労働省側がどう判断してくるかという問題がありますけれども、私どもとしましても、この事業は非常にいい事業で、希望しておったわけですから、そういう意味では、来年度に関しても。","voiceIndex":106,"id":"exchange-043"},{"speaker":"本田委員","kind":"質問","question":"一つお聞きしたいのは、この請願者のところから、区のほうに同様の申し入れ等はあったんですか、これまでに。この請願が議会に出て、初めてこのことを知ったということなんですか。","respondent":"金子産業振興課長","answer":"私の承知している範囲では、こういうような要望については、この請願で初めて知ったところです。","voiceIndex":108,"id":"exchange-044"},{"speaker":"本田委員","kind":"質問","question":"ですから、その辺の対応も十分に主張すべきところは、行政サイドで主張していただきながら、一般相談としてはいくらでも受け付けていただくということですから、その辺は少し徹底していないのであれば、区は、ホームページや広報等でやっているということでありますけれども、さらにわかりやすく皆さん方の目につくように対応してはいかがかなというふうに思います。意見を申し上げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-045"},{"speaker":"大沢委員","kind":"質問","question":"それからやはり、職業を選択、または選ぶ、就業する自由というものは確保されているわけですから、先ほども土井委員がおっしゃったように、職業選択、または働く上において、行政がそこまで手を差し伸べるものなのか、どうか。これはあくまで個人の選択、または考えであって、行政がそこまで入り込むべきものであろうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"結論を出すに当たっての意見を表明したいんですけれども。ですからぜひ、品川区の範囲で努力をしてくださっているところはあるけれども、ポケット労働法についての問題にしても、一つ目の問題にしても、不十分なところは、できるだけ視野を広く持ってやっていってあげたいなと思うので、ぜひ採択をしていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-047"},{"speaker":"本田委員","kind":"質問・要望","question":"私は、この請願は願意に沿わないという立場ですけれども、ただ１点、区のほうに要望しておきたいのは、高齢者の再雇用については、サポしながわなど、大変当事者の意欲が、ある意味では要望に沿ってできているというか、区内の各企業の皆さん方も、大分協力をしてくれて、雇用の促進を図っている方向に進んでおりますのは大変結構なことですが、青年層の雇用促進につきましても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"あまり聞き取れなかったんですけれども、今、委員長がおっしゃった２項目を、１年間かけて中心的に審査、調査をしていきましょうという項目に挙げたということでいいんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-049"},{"speaker":"堺委員","kind":"意見","question":"だから、可能ならば、そういったところも参考にどうかなと、そんな気がしたので、報告は終わっているんだけれども、この件について、また委員会の中でそれをやってみましょうということが、たしかあったかなと思うので、それに結びつけるわけではありませんが、そんなところもどうかなと、こんな気がしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-050"},{"speaker":"堺委員","kind":"質問","question":"第３回定例会が終わって、連休前、その間でよろしいんじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2462#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":46337,"voices":139}},{"id":"h18-20060627-7","meetingId":"h18-cm06","date":"2006年6月27日","dateIso":"2006-06-27","committee":"厚生委員会","time":"午前１０時０４分～午後２時０５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"三上委員","kind":"質問・要望","question":"交通事故、追突とか何とかという車だけの、当委員会じゃないけれども、清掃車の事故も何件かあるという報告が今回あって、専決処分が随分多いわけですよね。そういった関係の中にあって、こういったけがをしたとかという、こういうある意味では人命にかかわってくるような事実があったということになったときに、果たして今日までも、昨年の７月２６日に起きたことですから、ほぼ１年前の話ですよね。","respondent":"諸岡児童課長、古川児童保健事業部長","answer":"直ちに職員、そしてまた児童センターの館長、そしてまた児童課の課長、前任の課長ですが、直ちに保護者に連絡するとともに病院のほうに出向いたです。そのほか、何回かまたその後もお見舞いを兼ねてお伺いをしているです。私もさまざまな事業を実施していく中で、施設内あるいは外を問わず、事故については十分な配慮をしていますけれども、残念ながら事故が起きてしまっている実態がありますが、中でも事故の対応と申しましょうか。","voiceIndex":9,"id":"exchange-001"},{"speaker":"三上委員","kind":"意見","question":"当委員会でこういった話があったということで、やっぱり何らかのこういったいろんな事故があった場合の発表の仕方とかということについての、やっぱり助役をきちっと中心者として、全庁的にどう取り組むかというようなことが、１回きちっと話し合われていてもいいのかなと思いますので、福祉高齢事業部は関係ありませんという顔をしないでね、すべての事業部にわたって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それもいいのかなというのはちょっと気になるようなところも感じたところがあったんで、全館、新しい建物でコンクリートのところだと打てないというのもあるんでしょうけど、やっぱりけがをしないために、もう一回点検しておいてもらったほうが、遊具だけに限らず、全体的なもの、もちろん普段やっていると思いますよ、やっていると思うんですけど、再度これを機会に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の報告を聞いて、４７日間も入院されていたということで、こんなに重傷だったんだなというのを改めて思ったんですけど、後遺症とかはなくて済んだのかということを一つお聞きしたいのと、あと卓球台で遊ぶということは、日常的に児童センターでは行われていることだと思うんですけど、それがなぜ今回こういう重傷なけがに結びついてしまったのかということをどう考えられているのかということと、あと。","respondent":"諸岡児童課長","answer":"それを勝手に出さないようにということで児童に周知徹底を図るとともに、理解のできるような表示を行うこと。それから、転倒等で危険性のある遊具の出し入れにつきましても、職員が対応するということを徹底するです。","voiceIndex":14,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"後遺症がなかったということで、何よりだったなというふうに思うんですけれども、今のあれですと、今回は児童のみで勝手にやってけがをしたというわけではないので、そういうのは徹底するということは大事だと思うんですけれども、職員がしっかりと管理するということがすごく大事だと思うんですけれども、そういうところで。","respondent":"諸岡児童課長","answer":"この卓球台につきましても多少時間はかかりますが、１人で片づけることは可能でございました。たまたまその児童が手伝うということを申し出たために、職員もその気持ちを大事にしたいということで一緒にやってしまったです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"はい、わかりました。改めてこういう事故が起こったというふうなところは、本当にただ単にここの事故というだけじゃないというふうなところがいろいろあると思いますので、改めて総括をして、これを教訓にこういう事故が二度と起きないようにということで、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"何か親御さんのほうが納得いかれていないとか、そういうことはあったのかどうかという点と、それから損害賠償金が９３万６,１１０円ということですが、これは治療費と慰謝料いうことでトータルで書いてあるんですけど、その内訳といいますか、治療費等については全額支給されているものなのか、あとは慰謝料というのは、算定の方法か何かあるんでしょうか。その辺をお聞きしたいと思います。","respondent":"諸岡児童課長","answer":"親御さんとの和解等における対応なんですけれども、このお子さん、児童センターのほうへずっと通っていらして、親御さんのほうも児童センターのほうを大分ご信頼していただいていたということがございまして、また、事後の対応も館長。","voiceIndex":19,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"確かに遊具の出し入れについてはきちんと管理していかなければいけないという部分もありますけれども、職員がいないとそれが使えないとかということがないように、ぜひ子どもたちの遊びといいますか、午後の生活を保障する形で対処していただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"専門的な言葉になってくるのでよくわからない部分がかなりあったんですけど、例えば施行令、改正内容のところの平成１８年３月３１日以前の内容の「麻しん・風しんの単抗原ワクチン」というのは、この言葉と平成１８年４月１日のところに出てくる下の内容の「麻しんあるいは風しんの予防接種をすでに受けたもの」、これがイコールで、この予防接種というのは。","respondent":"倉橋品川区保健所保健サービス課長","answer":"したがいまして、麻しんも風しんも旧制度の方が、麻しんも風しんも二つやっておれば、両方とも接種は、たまたま２回針を刺したけれども、二つ免疫をつけているという状態ではありますけれども、片方しかやっていなかった、一つ忘れてしまったという方々に対しては。","voiceIndex":27,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"意見","question":"たぶん、ご説明でこの部分だろうと思ったんですけど、これはなぜ聞いたかというと、この後に区報、ホームページ、乳児健診等で周知するという中で、皆さん理解できるのかなというのが感じたんです。我々、こういう書類を見て説明を受けているから、ああそうなんだなと理解する部分はあるんですけど、もうちょっと何か出すときにわかりやすくお願いしたいなという、それの希望です。","respondent":"倉橋品川区保健所保健サービス課長","answer":"委員ご指摘の点、もっともです。その点は、区報の案も実は十分に考えまして、表現がわかりやすいように対応してまいっております。今後の広報等の周知につきましても、わかりやすい表現を心がけて周知を徹底させていきたいと考えております。","voiceIndex":29,"id":"exchange-010"},{"speaker":"木下委員","kind":"質問・要望","question":"既往のある人が２回接種を受けるのに安全性が確認された者は可とするというお話があったんですけれども、２回接種ということは、例えば破傷風というのは、何回か接種しないとその予防効果が得られないというのを一般的によく言われているんですけれども、１回だけじゃなくて、そういうふうに２回とか、もしくは３回とか、そういう形で接種すればするほどよくなるから。","respondent":"倉橋品川区保健所保健サービス課長","answer":"これに当初は時間がかかると言われていたんですが、専門家にお願いして、過去において集積していたデータを大急ぎで集めたということで、安全性が確認できたという厚生労働省の担当課長の説明でございました。","voiceIndex":31,"id":"exchange-011"},{"speaker":"木下委員","kind":"確認","question":"ということは、厚生労働省は安全は確認されたというふうに言っていると。何かさっきのご説明では、安全性を確認されたものは可とするということだったんで、まだその辺がはっきりしていないかなと思って、私のちょっと聞き違いなのかしら。要するに厚生労働省は、安全確認されたということで、２回目の接種も大丈夫だということの理解でよろしいんでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"私の説明で混乱したかもしれませんが、４月の時点では安全性が確認されないということでございましたが、今度６月の改正ではその間に今ご説明しましたように、専門家が過去のデータを集積していたものを大急ぎで集めたということで。","voiceIndex":33,"id":"exchange-012"},{"speaker":"西本委員","kind":"確認","question":"副作用がありますよね。この副作用というのは、今どういう形で皆さんに知らせているのか。ですから、十分な、国がそういう指針を出したということですから、安心していいのかなという部分もあるんですが、新たに臨床試験で、この２カ月の間、もしかしたらその２点でもいいんですけれども、新たにやった形跡があるのかという確認をしたいと思うんですが、副作用とあわせてお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"最近、春になるんですかね、麻しんがはやったりとかすると、話題に上がるんですね。ですから、この周知の方法の中に、やはり副作用等々、それから例えば体質上の問題等々ある場合に、医師会等々と協力していただくなり、相談窓口みたいなものがある程度明記されていると、安心して相談できることがあるのかなというふうに思いますが、そういう形まで告知の場合にしていただけるものなんでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"接種票といいますか、接種前の問診のところでも、それは十分に説明することになっておりますが、委員おっしゃるように保護者の方々のご不安に対応しなければならないというふうに考えております。","voiceIndex":38,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"ぜひ、よろしくお願いします。情報があるからこそ逆に迷うんですよね。いろいろ副作用があるとかというふうに聞きますと、非常に気になるらしいんですね。ですから、相談いただけるところはきちんと明記していただいて、自由にご心配なことがあったらどうぞという形でよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"訪問看護ステーションもそういう点で言えば２１カ所しかここには書かれていないんですけど、すごいたくさんの施設数が書かれているということが、ちょっとイメージがわかないので、どこら辺のところから、ここに書かれていないようなどういうふうなところに通われているのか、どういうところからサービスを受けているのかということをひとつ教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"６ページの利用施設に関するお尋ねですが、例えば3)の通所リハビリテーションについて申し上げますと、この表の下段に区内老健リハビリとあり、施設が１施設となっております。これは南大井の老健で、区内ではここ１カ所です。","voiceIndex":46,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２点お伺いします。老健施設についてお聞きしますが、利用を希望して利用できない、そういう方がいるかどうか。もう一点は、今回の医療制度改革に伴って療養病床の廃止が打ち出されましたが、今後施設運営事業者、あるいは施設の利用者がどうなるのか、区として今後どう対応していくことになるのでしょうか。","respondent":"蓼沼高齢福祉課長、木下福祉高齢事業部長","answer":"老健の利用について、利用できない方がいるかどうかという質問ですけど、今のところ、特段利用できない人がいるということは聞いてございません。ただ、まだ枠組みがはっきりしていない部分もありますので、経過措置の取り扱い等、まだ不透明でありますので、その辺も見ながら、区内にもそういう施設もありますので。","voiceIndex":48,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"療養病床については、本当にこれから社会的な問題が大きく起こってくるんじゃないかなというふうに思っているんですが、ぜひ受け皿の部分も含めて区としてもご検討いただきたいというふうに思います。とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけ確認させてください。６ページのところの4)短期入所、ショートステイのところなんですけど、これが延べ利用日数で出てくるんですよね。前の事務事業概要の２９ページにちょうど出ているんですけど、こっちは人数になっているんですよ。日数と人数の、そこのどういう計算をしているのか、ちょっとそこら辺だけ。","respondent":"蓼沼高齢福祉課長","answer":"ですから、ご利用いただいた延べの年間利用日数を１２カ月で割ったものが、この３,２９８日という数字になっております。ちょっとわかりにくいかもしれませんが。","voiceIndex":52,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"こっちの事務事業概要は人数を、こっちは月割りに平均してということで。何かちょっとよくわかりにくい部分があったんで。わかりました。ショートステイもなかなか入れないなんていう話もちょっと聞いたことがあった中で、ここで見ると９５.５％と、この枠というのは、まだある程度余裕は持っているというふうに判断していいんですか。","respondent":"蓼沼高齢福祉課長","answer":"西大井のロイヤルサニーのほうも９床ほど増えまして、それから、来年度になりますが、成幸ホームのほうもショートステイを増設する予定になっておりますので、それほど余裕があるような状況ではないと思いますけれども、満員に近いような状況で推移しているという状況です。","voiceIndex":54,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今定期的というお話があった中で、やはり我々もお聞きするのは、定期的にある程度何カ月ごとにと決めているというか、在宅の方がある程度めどをつけてはいるんですけど、逆に言うと、緊急にお願いしたいなというケースのときに、既に定期的になった方が入ってしまっているのが前提にあると、そういうところで入れないというケースがときどきお聞きするんですよ。","respondent":"蓼沼高齢福祉課長","answer":"今、基本的に予定してありますショートステイのほかに、特別養護老人ホームの空きベッドがあるとき、そういうところを活用して、なるべく調整をするようにやっておりますので、そのほかのことも勘案して。","voiceIndex":56,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これで最後にしますけど、ご相談に皆さんが行くと思うので、その辺をうまく調整していただいて、できるだけ無理のない範囲でそういうご要望にこたえていただきたいなと思いますので、よろしくこれからもご検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"それと最後に、２０ページのところの、生活支援事業、一番下のところの配食サービスなんですが、ここのところの平成１７年４月から１８年３月までの下に平均と書いてあるんですが、このちょっと数値の読み方がわからなくて、単純に人数で食数を割返すと６食から７食なんですが、この平均というのがどういう意味なのか教えていただきたいのと、この辺。","respondent":"蓼沼高齢福祉課長","answer":"希望者等につきましては、ちょっと数的なものは把握しておりませんので、ご容赦願いたいと思います。それから２０ページ、ちょっとすみません、後ほどお答えします。","voiceIndex":59,"id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そのことで、今までやっていただけていたのができない。なので、ぜひそういった面も利用者の声もそうですが、事業者のところの実態もぜひ把握しながらやっていただきたい、これは前にも１回お話ししたことがあるんですが、ぜひこれは要望なので、よろしくお願いいたします。水中運動のところは、たぶん今１カ所ですよね、対応しているのが。この点は、今後の見通しとしていかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"今、水中運動のご指摘いただいた中にも、設備の整備等で経費がかかるということもございまして、今のところ、具体的に箇所を増やすという計画はございませんけれども、いろいろあります社会資源、いろんな区立施設のプール等。","voiceIndex":64,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０ページの要介護度別のサービス利用割合というところが載せられているんですけれども、この中で、要介護１のところで、用具貸与というのが５０.９％というふうになっているんですけど、この中身がどういう用具貸与になっているのかというのを教えていただきたいんですね。というのも、要介護１の方は８割くらいの方になるんでしょうか、要支援になっていきますよね。","respondent":"蓼沼高齢福祉課長","answer":"今のところ、そういう意味では区の在宅介護支援センターが７割、８割を占めているような状況でございまして、特段ケアマネジャーがプランをつくるのに困っているというような状況にはないというふうに考えてあります。","voiceIndex":66,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５０.９％のほとんどが電動ベッドや車いすだということなんですけど、ということは、１,６９５人のうちの５０％ですので、８００人ぐらいの方はベッドや車いすをおおよそ使われているということになるんでしょうか、ちょっとそこら辺のところ、要支援になる方で、何人くらいの方が電動ベッドや車いすを使われているのかというふうなことがわかったら教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"福祉用具の関係ですけれども、要介護１から要支援に移行して引き続き利用されている方の数というのは、すみません、把握してございません。","voiceIndex":68,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護保険法が去年通って、施設でも、そして今度はまた在宅でも４月からは予防介護というふうなところでいろいろ矛盾も出てくると思うんですけれども、必要な方が、必要なサービスが本当に受けにくいというふうな状況が、この電動ベッドにしても、車いすにしても、それから先ほど飯沼委員が言われたように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、先ほど区市町村と都で２０名の準備委員会をつくっているというご報告があったと思うんですけど、２０名の構成についても、ちょっと教えてください。もう一つ、ここの中で、連合の議員を構成団体の議会で選挙していくということなんですけど、これはちょっと具体的にどれぐらいになるのかということと、どういう形で選んでいくのかというところを教えていただけないでしょうか。","respondent":"冨岡高齢事業課長","answer":"２番目の準備委員会とおっしゃいましたが、実は準備委員会は９月からできますので、今その前提の検討委員会というのを立ち上げておりますが、そちらのメンバーですけれども、２３区が８名、それから市町村が７名、都が２名、それから仕事の関連で国保団体連合会。","voiceIndex":76,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"準備委員会の検討委員会が２０名ということですけれども、それでは、準備委員会というのはどういう構成になっていくのかということをひとつ教えていただきたいのと、それとこの左側のページで、費用の負担というところが、今度は７５歳以上の方は高齢者からの保険料が１割というふうなことで、それぞれあとは負担割合が書かれていますけれども。","respondent":"冨岡高齢事業課長","answer":"検討会で決めます準備委員会の構成ですけれども、実は今まだ合同検討会で詰めておるところでございまして、その中でまだ決定をしていないものですから、今回ちょっと決めていない状況ですので、今の段階ではお答えできません。","voiceIndex":78,"id":"exchange-029"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"三上委員","kind":"質問・要望","question":"その他のところで結構なんですけども、今社会的に非常に問題になっているうつ病でしょうか、そういった精神の問題についてもちょっと加えていただければと要望したいと思います。","respondent":"須藤委員長","answer":"よろしくご理解のほど、お願いいたします。","voiceIndex":82,"id":"exchange-030"},{"speaker":"三村委員","kind":"質問","question":"私どもの会派としては、少子化対策ということで意見を出させていただいたんですけれども、そういったことで他の会派からのご意見とか、調査項目としてご意見等出なかったのか、また、今回調査項目の項に入らなかった理由について教えていただけますか。","respondent":"須藤委員長","answer":"そういったものが少子化対策の中でも、特に妊婦・乳幼児の健康というようなことで、食については既に品川区では始めているところですので、そういった面も含めて少子化対策につながっていけばいいかなというような思いで、今回特に少子化云々ということだけでなく。","voiceIndex":84,"id":"exchange-031"},{"speaker":"三村委員","kind":"質問","question":"先ほども質問させていただいたんですけれども、他の会派からはそういった少子化対策について、今回の所管事務調査について取り上げるべきという意見は出なかったんですかということだったんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-032"},{"speaker":"三村委員","kind":"質問・要望","question":"できれば、生活と健康というふうにくくられてしまうと、中に妊婦・乳幼児の健康についてという項目はあって、そういったところで多少、不妊治療だとか、そういった不妊も入るのかわからないですけど、多少そういう妊婦・乳幼児のところでは子育て関係のところも入るかと思うんですけれども、ぜひできれば、今特殊合計出生率も１.２５と大変低い状況にある中で。","respondent":"須藤委員長","answer":"その間で整理をしていこうということなので、その辺を勘案しながら、少子化というのは本当に本腰を入れてやっていかざるを得ないというと、ちょっとの時間でこうというようなことはなかなか難しいので、少子化云々というのは。","voiceIndex":88,"id":"exchange-033"},{"speaker":"三村委員","kind":"提案","question":"もちろん多岐にわたるというのは当然なんですけれども、私どもの会派としては、当然多岐にわたって重要な項目であるので、特別委員会の設置も提案をさせていただいたんですね。その特別委員会の設置の際には、こちらの厚生委員会のほうで検討していくべきということだったので、特別委員会の設置も見送られた経緯があるんですね。","respondent":"須藤委員長","answer":"委員会自体が１年でメンバーが変わってきますので、少子化対策はこの１年間でぱっと答えが出るものでは決してないと思うので、厚生委員会として実りある所管事務調査として、後でお話ししようと思ったんですけども、ある程度のまとめが委員会としてできれば。","voiceIndex":90,"id":"exchange-034"},{"speaker":"三村委員","kind":"意見","question":"これ以上、何か議論しても平行線だと思いますので、ぜひせめて視察項目の中にもそういったところも含めて、全くタッチしないのではなくて、ぜひ視察先の中にもそういった子育て支援、先進的にやっているところを入れるとか、そういったところで多少なりともぜひなるべく多くそういった調査の対象を、そういった視点も含めて検討していただければと思います。","respondent":"須藤委員長","answer":"先ほど来お答えしていますように、いろんな要望があった中に障害者の問題もあるし、それから神経的な精神障害、そういう問題も出てきています。それから高齢者福祉についてもご提案があります。","voiceIndex":92,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ということで、１年間やってどうだったかというふうなことも含めて、この厚生委員会にかかわる中身の次世代育成の問題に関しては、ぜひご報告をしていただくようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-036"},{"speaker":"西本委員","kind":"確認","question":"確認をちょっとさせてください。そこに入り込んでしまうと、今度文教委員会になっちゃうのかななんて思ったりしていて、ただ、食全体を考えたときには関連するのかなというふうに思ったりしている部分はあるんですが、そこら辺の仕切りはどういうふうにして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問","question":"所管事務調査について、議長に提言という言葉が先ほど出たんですけど、これは委員長会でそのような形で出たんですか、それとも委員長としてという、今まで所管事務調査は提言事項まで持っていっていなかったというのがあったので、その辺はどうかなと思って。","respondent":"須藤委員長","answer":"それが、難しいよとか、前例がないよという話になるかどうかわからないけど、いずれにしても、我々としては、厚生委員会としては１年間議論しながら、こういう方向性で持っていったほうが。","voiceIndex":98,"id":"exchange-038"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"三村委員","kind":"質問・要望","question":"先ほども申し述べたとおり、今回調査項目としてぜひ視察の際の項目として、少子化対策ということで、いろいろ先進的な事例ですとか、出生率の上がっている自治体等をぜひ視察対象にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"意見","question":"少子化については毎年厚生委員会、昨年も一昨年も見たとおり出ていると思うので、また、やはり参考にするべきものはあると思うんですが、逆に介護保険制度が今年改正になったところから考えていって、５段階が６段階になった、そこら辺もありますよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"原小学校の跡地が、これは行財政改革特別委員会で話があるんですが、老人福祉施設と、それから幼稚園・保育園という、そういう子ども施設というのが一体的に運営しているところがあれば、ちょっと具体的なところはわからないんですが、そういうところがあれば、一体的な運営をしている、それから地域のそういう福祉施設みたいなもの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-041"},{"speaker":"三上委員","kind":"質問","question":"どちらかというと、文教委員会の絡みから幼保一元という部分について、せっかくですから厚生委員会で所管になったということで、そういった面で幼保一元、先駆的な事例としてあるようなところについてぜひ調査したいなと。特に、ちょっと伺ってみるところによると、佐賀市あたりというのは、品川区の校長先生であったわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私たちとしても、少子化対策、子育て支援のところにぜひ出生率の対策をとって上がっているという自治体に行って、参考にできたらいいなというふうに思っているんですけれども、具体的なところも申し上げていいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"長野県の下條村というところは、ＮＨＫでも取り上げられて、５月２２日付の朝日新聞でも取り上げられたんですけども、村営住宅をつくって、それで出生率が１.９７まで上がっていまして、子育てサークルとか、それから若い人たちが住みやすいようなということで、図書館とかプールなどの施設を準備したり、それから中学校３年までの医療費の無料化もしているということなんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-044"},{"speaker":"木下委員","kind":"質問","question":"それと、生活習慣病の予防ですか、そういう部分で先進的な自治体ですとか、そういうのがあれば、そういうのを視察したいなと考えていますので、ちょっと皆様方、いろいろ視察したいというご希望があるんですけれども、できましたらひとつご検討のほう、よろしくお願いいたします。","respondent":"須藤委員長","answer":"日程的なところですけども、今お手元に１０月の予定表、議会のほうの予定表を配らせていただいておりますけども、一つは１０月３０日から１１月２日までかな、次の１１月がちょっとついていなかったので申しわけないんですが、１０月３０日から１１月２日の４日間のうちから選ぶ。","voiceIndex":114,"id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"意見","question":"日程的には、例えば１０月３１日から１日、２日、３日間ぐらいでというパターンを考えたとき、３１日、１日、２日という形がとれればなと。翌週になると、会派としてちょっとつらい状況が入っているので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"はい、３１日から１日、２日ぐらいという形で考えていただければというのが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-047"},{"speaker":"三村委員","kind":"質問・要望","question":"視察先のことで、当然いろいろあっちに行ったり、こっちに行ったりにはなると思うので、だめだったらだめで構わないんですけれども、要望として富山、先ほど西本委員がおっしゃっていたような高齢者から子どもまで全部障害者も含めて富山型と呼ばれる小規模多機能の施設が富山のほうにあるので、ぜひそこを場所として検討していただきたいなというのだけ、１点だけ。","respondent":"須藤委員長","answer":"今お話ししましたように、いろんなデータをとりながら地理的なものを整理して持っていきたいと思いますので、そういう参考資料がありましたら、我々も理事者にまたこれから聞かなきゃいけませんので、それより先にいい資料がありましたら。","voiceIndex":123,"id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3150#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":42276,"voices":124}},{"id":"h18-20060627-8","meetingId":"h18-cm06","date":"2006年6月27日","dateIso":"2006-06-27","committee":"建設委員会","time":"午後１０時０３分～午後４時１２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の東品川海上公園新設工事（南側：第５期）","agenda":"の東品川海上公園新設工事（南側：第５期）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ただ単に「水とみどりのネットワーク」という、海のところとか、そういうところがあるよということじゃなくて、水に親しめる空間というのは、噴水とかというところだけですか。","respondent":"松代管理工事課長","answer":"これはさかのぼること、平成５年ぐらいから計画をしておりまして、その後はこの入り江の部分、一番近づきやすいところ、そこはなるべく近づけるようにというようなことで、当初は計画をしてまいりました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"意見","question":"構造上、いろいろ大変なものだということなんですが、この図で水上バスの様なものがここにあるわけですが、これは計画として進めていくという、これは一番最初につくったときの図だと思うので、一部変更があったりしているんでしょうけれども、今のお話だと検討していくということが方針として残っているということで、どういう感じで進められていこうとするか。","respondent":"松代管理工事課長","answer":"そういったことも含めまして、「新・水とみどりのネットワーク」という構想を今、検討に入ってあります。その中では、これまでの計画を踏襲し、かつさらに我々行政側の計画のみにとどまらず、町場の動き、また民間等の動きということが出ております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"もちろん、いろいろな施設を借りてバスケットをやる施設ももちろんありますけれども、仕事帰りに少し時間が空いたから、スポーツを楽しみたいという、なかなかそういう気軽さというのがどうしてもそこにはなくて、ぜひこういうところにそれが盛り込めたらなという思いなんですけれども、そういう検討も含めて、計画を少し教えていただければと思います。","respondent":"松代管理工事課長","answer":"そういう中に、地域の方々の説明会等でのご要望等を少しでも取り入れる形をとったのが、今回の計画ですけれども、その中には残念ながらバスケットゴール等の部分、またはそれ以外のものでも要望等があったんですが、今回、ちょっと設置はできなかったという状況です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"ほかの公園にない感じがしますので、とにかくぜひ生かす形で、例えばスリー・オン・スリー一つとっても、そう場所をとるわけでもないですし、ポンプ所の壁もいろいろな使い方もあるでしょうけれども、ぜひそういうところをいろいろご検討いただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"今、この公園が野球場を含めると、５ｈａということですが、これは区民の利用状況をどのように人数的に見込んでいるんですか。","respondent":"松代管理工事課長","answer":"利用者数をカウントで調べた経緯はございません。賃貸の天王洲野球場等を含めた利用としましては、非常に高いものと承知しています。少なくとも天王洲野球場は土日は大体８０％、９０％の利用率となっていまして、平日でも大体６割ぐらい利用すると承知しています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"当然、ここは夜間も開放するんでしょうけれども、ポンプ所の上部にエレベーターをつけている部分も夜間開放するんですか。あれは夜間は開放しないという方針なんでしょうか。","respondent":"松代管理工事課長","answer":"今のところ考えていますのは、地域の方々といろいろとお話をしながら、朝の７時から夜の９時ぐらいまで開放し、その後は常駐している管理職員が閉鎖をして、上に上がれないような形を確認した後、引き上げるという計画で、詰めてあります。","voiceIndex":14,"id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"どう考えても、上は建物に死角ができますしね。あるいは近隣のマンションにしても夜９時、１０時過ぎに区民がそこで遊んでいるというのは、迷惑ですよね。それで、近隣からも利用するということで、駐車場の台数ですけれども、これで足りるということなのか、あるいはもう一つ駐車場の管理なんですけれども、これは有料の形をとるんですか、それとも無料ですか、あるいは今はやりのコインパーキングですか。","respondent":"松代管理工事課長","answer":"双方が使えるようなことで、少しでも利用者にご利用いただけるようなものを考えて、そういう趣旨で管理をしたいと考えているところです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"すると当然、野球場の利用者も来るということで、減免措置ということも考えているということですか。","respondent":"松代管理工事課長","answer":"残念ながら減免等は現在もございません。一般利用として、１時間３００円ということで、これは都内一律公共施設、私どもが管理しています駐車場の利用単価をお示ししてご利用いただいているところです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"区内の公園でいくと、戸越公園ですとか、区民公園とか、非常にキャパの大きい公園が多いんですけれども、ここの公園は区内で大きさ的には何番目ぐらいになるのか、その辺をちょっと教えていただきたいのと、今出ている駐車場の話なんですけれども、天王洲の方は５６台ということで、有料ですから、野球をやる方でもやらない方でも、当然ニーズがあって使うわけですから、いいと思うんですけれども。","respondent":"松代管理工事課長","answer":"地域からもそういった要望が出ましたので、そういったことを取り入れながら、当時の駐車場の活用というものをいろいろと検討してまいりました。そういうことで、これまで管理をしていました駐車場の体系的な部分として、料金を一定程度、それぞれ同一の料金にする。","voiceIndex":20,"id":"exchange-009"},{"speaker":"藤田委員","kind":"提案","question":"今、１つ提案なんですが、例えば香りの樹木を植えるというふうにいたしますと、その香りの木の性質とか、訪れた人が何か学べる、知る、楽しめるというような、そうした何かコンセプトというのを、視点を当てていくというのは大事じゃないかと思うんです。そうした学べるというような視点で、どのように今後取り組んでいかれるのか、お伺いしたいと思います。","respondent":"松代管理工事課長","answer":"最近、ユビキタスというのがいろいろと出ていますが、これも今後の検討になっていくと思いますけれども、そういったものも何か工夫として考えられないものか、そういったものでお知らせをする、もしくはまた重要な。","voiceIndex":22,"id":"exchange-010"},{"speaker":"藤田委員","kind":"質問・要望","question":"つくったらつくりっぱなしというふうにならないように、そういうのはないと思いますけれども、やはりそれからが大事だと思うんです。まちづくり事業部だけでは対応ができないところがありますね。例えば表示板に今月はどういうお話があるんだろうと、楽しみに来れるような工夫といいますか、ぜひお願いしたいと思います。何かそういう工夫もぜひお願いしたいと要望してまいります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"},{"speaker":"大西委員","kind":"質問","question":"ただ、今、南側に２０台というところで、果たしてこの２０台が必要とされるかどうかということと、この２０台を設けるということは、中に自転車をとめられないという問題もいずれ発生しようかと。ちょっと老婆心ながら思うことが少しあったんですが、その分も少し結構ですが、ただその健康遊具、複合遊具、駐輪場の部分に設けることによって、中途半端にならないかと思うんですが、どうでしょうか。","respondent":"松代管理工事課長","answer":"これも先般、委員会でご質問・ご指摘等がありまして、そういったことでいろいろと私ども検討しまして、平成１８年度、今年度から公園全体の公園バリアフリー、入口のバリアフリーをしていこうということで、既に取り組んでいるところです。","voiceIndex":25,"id":"exchange-012"},{"speaker":"大西委員","kind":"質問・要望","question":"理解できました。１点だけ、少し答弁がなかった部分としては、天王洲アイル駅を利用しての野球場にすぐ入ってくるところ、審判員だとかがいるところにも枠がはまっているので、そういうものを利用して来られた車いすの方もおられようかと思うので、あちらからの入場に際しても、バリアフリーとしての配慮をいただけることを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-013"},{"speaker":"井上委員","kind":"確認","question":"場所を決めて、駐車場があるかないかの確認ではなく、そこからスタートするという意味では、この障害者１台とりましたよということではなくて、きちっと使える駐車場でなければいけないと思うんですけど、そういうふうにきちっと、今、福栄会のお話も出ましたけれども、高齢者の人たちがそういうちょっと中型あるいはマイクロバスやなんかで来たときにも。","respondent":"松代管理工事課長、岩田まちづくり事業部次長","answer":"後段のマイクロバス等のことは今回のところでは考えてございません。しかし、一定の駐車場をつくる際には身障者の方への対応ということでスペースを設けてあります。この相反する部分をどうやって調整するかというのが非常に難しいところで、道路においても点字ブロックというのは、必要最小限の場所に設置することになっておりまして、連続設置というのがなかなかできない。","voiceIndex":28,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"運用後ということで、そこに一々問い合わせをして公園を利用するということではないと思いますので、そういうところを見ても、あの公園にはこういう駐車場があるなといえば、すぐ下見もそういう団体の方たちはするんですけれども、一々こうなったときにどうするの、ああするのということはしなくても、見ただけでできるということで、ある程度スペースのある。","respondent":"松代管理工事課長","answer":"今、委員がおっしゃるようなことは、通常のところでもそういったワゴン車とかが十分とまれるスペースで、かつ身障者対応のところは少し広めになっておりますので、当然身障者の方がとめて、車いすでおりたり、乗ったりするスペースがありますので。","voiceIndex":31,"id":"exchange-015"},{"speaker":"井上委員","kind":"意見","question":"おろして、乗せて、そこから３メートルバックしてからでないと、車いすは動けないという状況が、きちんと駐車場を把握した上で、基準どおりつくっているから問題ないでしょうという体制ではないところで取り組んでいただくことをぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-016"}]},{"id":"topic-02","title":"のしながわ水族館「アザラシ館」オープンと入館料の改定","agenda":"のしながわ水族館「アザラシ館」オープンと入館料の改定","exchanges":[{"speaker":"井上委員","kind":"質問","question":"昨年、建設委員会で下関の水族館を視察に行ったんですが、やっぱりいかにリピーターを増やすかということが利用率のアップにつながるということだったんですが、こういう料金改定のケースはサンシャインシティの方から、当区が認めるという形のようですけれども、ここによくある回数券システムというか、そういうものとか、どういうふうにリピーターを増やすのかということについての議論の中に。","respondent":"藤田道路公園課長","answer":"これまで水族館の方では、平成１６年に世論調査等でアンケートを行った結果、特に家族の成長前期、一番上のお子さんが小・中学生といったような家族では６４.９％が３回以上行っているという結果になってあります。","voiceIndex":39,"id":"exchange-017"},{"speaker":"井上委員","kind":"提案","question":"もう一点、すみません、４番目の無料バスの送迎についてなんですけれども、あのバスを今、基本的にはすべてサンシャインシティが運用しているものなのかどうかという、区はどういうかかわりを持っているかというのが１つ。平日に利用がないんじゃないかと、私は思うんですが、その実態はどうでしょうか。","respondent":"藤田道路公園課長","answer":"水族館の送迎バスの関係ですけれども、平成１７年度までは区の方が委託発注をして、バスの運行事業者の方で実施をしていたという形になってあります。","voiceIndex":41,"id":"exchange-018"},{"speaker":"井上委員","kind":"意見","question":"じゃ、平成１８年度から直営になったということで、今度バスを買い替えるときの費用負担の問題とか、あとサンシャインシティとの契約で、バスのことはすべて契約の中に含まれてしまうのか、その費用の負担の部分について、区との関係がどうなのか。","respondent":"藤田道路公園課長","answer":"今回、バスについては今、水族館で検討していますのは、バスの購入ということではなくて、リースという形でのバスの手当をするということで、トータル的な費用については、水族館の運営費の中から支出をしていくという考えです。","voiceIndex":43,"id":"exchange-019"},{"speaker":"中塚委員","kind":"意見","question":"今回、６億５,０００万円かけて「アザラシ館」をオープンなさって、その延長なのか、今後の安定した水族館経営のため、入館料の改定ということですけれども、今、現状どういう経営の状況なのか。今回の一般料金が２００円上げて、区民割引は限定から通年の変更ですけれども、料金変更の理由をもう少し詳しくご説明いただけますか。","respondent":"藤田道路公園課長","answer":"それともう一つとしては、その反面、「アザラシ館」ができることで、それに伴う費用が、また運営費的なものがかかってくるものです。そうしたことを考えながら、周辺の水族館の動向も踏まえ、料金の設定を今回変更するというふうに考えたものです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"初めにサンシャインシティの２００円のそれぞれの改定を現実的に区が評価して、必要だと言って、当然いろいろありましたけれども、サンシャインシティがなぜそうやって維持してきたというところがよく見えてこない部分もあるんです。本来、区民割引はある意味通年ですから、広がるわけですね。一般は上がるわけですね。トータル的に収入が上がるのか下がるのか、よく見えてこない部分があるんですね。","respondent":"藤田道路公園課長","answer":"その辺で勘案すると、区民の皆様にはこれまで以上にもう少し来ていただきたいと思う部分と、料金の設定の中で与える影響はそんなに大きくはないと考えているものです。","voiceIndex":47,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"区の場合、１割。伺いたいのは、何でこの改定なのか、そこがよくわからないんですね。要は実際、品川区は今回６億５,０００万円投資、サメやペンギン、そもそも水族館なんかもそれぞれ億単位のお金で購入しているかと思うんですけれども、その関係と、この今回の料金改定の関係が見えてこない、クリアになっていないんですね。そこをちょっと伺いたいんですけれども。","respondent":"藤田道路公園課長","answer":"その中で今回、料金設定として当然、周辺の施設との料金について、どういう関係にあるかというのを私どもはよく確認しながら、料金設定していかなければいけないんだろうということで、近隣の動向と合わせて考えたときに、おおむね近郊の水族館施設は１,８００円ぐらいから。","voiceIndex":49,"id":"exchange-022"},{"speaker":"中塚委員","kind":"意見","question":"本来のしながわ水族館の教育的施設、また集客施設、どんどん囲まれていくのではないかと思うんです。特に実態として今、区民の利用がまだ１割にとどまっている。周辺の状況を見て、ちょっと安いから２００円上げるという発想も、どうも私には理解しがたいと思っています。これは意見であります。お考えを聞かせてください。","respondent":"岩田まちづくり事業部次長","answer":"それで行きますと、６０万人ちょっと切ると、いわゆる見かけ上の黒字が赤字に転換してまいりますので、それを防ぐためには、この段階で料金の改定を図らざるを得ない。","voiceIndex":51,"id":"exchange-023"}]},{"id":"topic-03","title":"の「目黒川右岸低地部排水施設整備工事その２」の着手","agenda":"の「目黒川右岸低地部排水施設整備工事その２」の着手","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この近隣の方が、台風なりが来ると心配な中で、近隣の説明会やそういう状況は今までどういう感じだったのか、経過を教えていただけますか。","respondent":"原田下水道河川課長","answer":"その後、平成１８年３月に工事契約をした後、施工業者が決まりましたから、施工計画を立てまして、今年の４月に工事説明会を実施したということです。多くの方を集めての工事説明会はその２回ということで、あとは個別に町会長等にもご説明しながら、周知を図っているところです。","voiceIndex":58,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"説明会ではどんな声が寄せられたのかなと、そこだけ教えてください。","respondent":"原田下水道河川課長","answer":"それから工事説明会での質疑につきましては、実際に大型車両が通るところの安全性、もっと別のルートを回せないのかというご質問や、あるいは大崎五丁目遊園が多少お祭り等でも使っておりますから、そういうときには工事をやめてもらえるかといったことで、ご質問がありました。","voiceIndex":60,"id":"exchange-025"},{"speaker":"松澤委員","kind":"質問","question":"これは全体の中で、当然大きなものですから、貯留能力というのか、貯留管としての役割ということなんですけど、何トンぐらいたまるものになっているんですか。","respondent":"原田下水道河川課長","answer":"これは内径２,６００ミリの円形管で、延長分を掛ければ出てくるんですけど、ちょっとそこまでは数字は記憶していないです。","voiceIndex":62,"id":"exchange-026"},{"speaker":"松澤委員","kind":"質問","question":"数字を記憶していないということは、例えば下水道管関係の場合は、明らかに下水道貯留管として使うということの中で、当然何トン貯留できるのかと考えていますけれども、ここは貯留能力というものがもともと計算されていないということなんですか。それとも今回、ここの委員会に来る資料としては、調べてこなかったということなのか。","respondent":"原田下水道河川課長","answer":"今回、つくる管については、貯留管としてつくるということではなくて、あくまでも配水管としてつくるということで、ただどうしても形上、昔つくっていれば、浅いところに入ったんですけど、最近つくる場合は、いろいろな埋設物の下に行かざるを得ないということで。","voiceIndex":64,"id":"exchange-027"},{"speaker":"松澤委員","kind":"質問","question":"説明を聞いたら、ずうっとふだんは下水が流れているのを、ポンプアップしてあげるということですけれども、大雨のときにはそのポンプアップする能力を超えて、たまっていって、いっぱいになったのがずぶずぶと上がってきて流れると。当然、地上の方が高いですから、それは大丈夫なんですね。理論上はそうだけど、実際には水が上がらなかった、そんなことは絶対ないんですか。","respondent":"原田下水道河川課長","answer":"水そのものはどんどん降ればたまっていきますから、たまっていったら、あとは空間のある方向に流れるというので、既設の鮫洲幹線の方が位置的には低くなっていますから、低いところに流れるという意味で、大丈夫と考えております。","voiceIndex":66,"id":"exchange-028"}]},{"id":"topic-04","title":"の中原街道の沿道地区計画","agenda":"の中原街道の沿道地区計画","exchanges":[{"speaker":"藤田委員","kind":"質問","question":"私の小さいころは、この中原街道沿道の振動のすごさ、騒音のすごさの記憶がよみがえってきたんですけれども、今現在はこの中原街道はかなりマンションが左右にずうっと建設されています。ほとんどマンションですね。この対象になる基礎調査というんですか、本当にそれぐらいしか、私はないんじゃないかなと思うんです。５メートル以下の建築物なんですけれども。その辺ちょっとお伺いしたい。","respondent":"伊勢住環境整備担当課長","answer":"それからブルーのこの資料ですけれども、こちらのところに出ていますけれども、３月２２日の水曜日、それから３月２３日の木曜日、それぞれアンケート調査とか、あるいは基礎調査の内容について、基礎調査の内容まではあまり詳しくご説明できなかったんですけど。","voiceIndex":73,"id":"exchange-029"},{"speaker":"藤田委員","kind":"質問","question":"それは大体何人ぐらい対象になると考えていらっしゃるんですか。それしか私はわかりませんけれども、件数として、今、ほとんどがマンションですから。","respondent":"伊勢住環境整備担当課長","answer":"コンサルタントに委託して調査したわけですけれども、５メートル以下の建物についてはほとんどなかったというところで聞いてあります。ほとんどないと。","voiceIndex":75,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"地区計画で定められるのは、間口率を１０分の７が最低と、要するに建物との間をなくしてということと、周りに音が広がらないようにしているということだと思いますけれども、実際、現実にこの辺は建物が少ないということなんですけれども、建物を高くして、音を防ぐようですが、この辺のデータというのはどんなデータがあるんでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"もとになっているものは、先ほど申しました沿道法で、細かい指定は政令、省令にありますけれども、その中で５メートルという数字が出てくるわけなんですが、どこの研究機関でやったかわかりませんが、そういう実験データに基づきまして５メートル。","voiceIndex":77,"id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問・要望","question":"沿道法で５メートルと、これは根拠になったいろいろなデータがあるらしいということなんですけど、何か根拠がよくわからないなと。もう一つ、この一番最初の目的のところに、騒音の低減とあわせて、幹線道路沿道にふさわしい土地利用の誘導を図るということなんですけれども、このところがどういう意味なのか。もうちょっとわかりやすく教えていただきたい。","respondent":"伊勢住環境整備担当課長","answer":"例えば風営法絡みということで、段階があるわけですけれども、これぐらいのところまではいいですよとかどうだとか、この辺は説明会等でご説明したいと思います。それから建築物の形態や色彩、意匠。","voiceIndex":79,"id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ネオンだとか、色なんかの制限とか、それはそれでわかるんですけれども、こういうところであまり高層化させないでほしいという声もかなり多くありますけれども、ある意味ではこの地域では高さ制限はないと思うん出すけれども、こういう声を反映してもいいんじゃないかなと思うんですけれども、ここでは逆に５メートル以上というふうにしているんですけど。","respondent":"伊勢住環境整備担当課長","answer":"今、検討案の段階でございまして、これから７月に説明会を開きまして、他区の情報等を皆さんにお知らせしていく中で、そういうご意見があれば、それを取り入れるかどうか判断したいと考えています。","voiceIndex":81,"id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういうところが心配されることなんですけれども、今、東京の沿岸地域に壁ができると、これはほとんど道路沿いに屏風が建つようなものだと思うんですけれども、こういう通風だとか、環境だとかというのは、どういうふうに盛り込まれていくのか、どういうことが心配されているのか、そのことについてご説明いただきたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"そういう意味からも説明会の感触で、ここまでやったらどうかとか、多くの意見が出てくれば、それはそれでまた計画を立てるときに勉強していきたいと考えております。","voiceIndex":83,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"住民の合意だとか、地区計画ですから、それが前提になるということなのかと思うんですけれども、どうも現実に、ここの道路沿いに大きな屏風みたいなものがどーっとつくられると、そこの沿線のかなりの範囲のところに例えば通風の問題だとか、そういう影響が出てくるわけです。私たちは知りませんみたいになりかねないんじゃないかと、心配しています。","respondent":"伊勢住環境整備担当課長","answer":"ただ、この辺については、どのようなご意見が出てくるのか、その経過を見ながら検討していきたいと思います。","voiceIndex":85,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"地区計画が地域の住民の発意でというところで、これは逆バージョンなのかなと思って、東京都から沿道地区として、中原街道が指定されたことによって、この地区計画を品川区がつくっていかなければならないものというふうに思えるんですが、これはそういう流れの地区計画ですよねということも確認の答弁をいただきたいことと、あとこの４つ、騒音対策のためのルールというのが、今後どういうふうに。","respondent":"伊勢住環境整備担当課長、岩田まちづくり事業部次長","answer":"ただ、もう一つは良好な市街地の形成ということがありますので、それについてもほかの事例、環七とか、大田区とかほかの区でもやっていますけれども。先ほどから皆さん方が言われているような高さ制限ができるかどうかは別にしても、沿道の人たちがそれも話し合いながら、やっぱり高さ制限をやろうとか。それから間口率の状況ですけれども、沿道１列目の建物の計が２４８棟ですが、そのうち５０％未満のものが３.２％、それから５０から６０％が３.２％。","voiceIndex":87,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問","question":"じゃ、ピロティに壁を設けていないところにはやってくださいねということになるのか、建て替えのときにそうなのかということの関係はどういうことですか。","respondent":"伊勢住環境整備担当課長","answer":"この緩衝建築物の建築費の助成ですけれども、このような建物を建てるときに、その建築費用の一部を東京都が負担するということになってありますので、建てるとき、修繕は入っていないと、東京都のパンフレットでは読めます。要するに、これから建てるときに助成ができるです。","voiceIndex":91,"id":"exchange-037"}]},{"id":"topic-05","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"案件以外に例えば事前にもちろん委員長に連絡をしておくということで、このことについて間に合えば、次回の委員会で報告をいただきたいというような、今動いているケースがあるのでということもあるんですが、１カ月ぐらいたったときの委員会の場合には、前にもあったんですけれども、特にこのことが今問題になっているので、状況を説明していただきたいというような要望をしたときに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-038"},{"speaker":"宮崎委員","kind":"提案","question":"正副で、設置してやるというのが前提なんですけれども、うちの方も大きな開発のところは、議運のときに提案した際に、これは建設委員会だという意識を受けておりますので、ぜひそういうことも取り計らっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-039"},{"speaker":"井上委員","kind":"提案","question":"公明党から出ているまちづくりの専門家などを呼んで、委員会として研究していくというところは、できればこういうことを私たちだけで品川区の施策についてどうこうと言うよりも、そういった方のご意見も伺わせていただいて、議会として提案ができる、委員会の提案というのも議会改革で提案ができるという仕組みもできつつあるので、そういうことができることをしていきたいと要望したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-040"},{"speaker":"伊藤委員長","kind":"質問・要望","question":"先ほども言いましたように、委員会の回数の制約がありますし、それから理事者の皆さんにご協力いただかないとできない話でありますので、今、いただいた意見をもとにしながら、集約をさせていただいて、最終的には正副でまとめさせていただきまして、次回以降の委員会の中で、例えば今、井上委員がおっしゃったように、場合によってはできるかどうかは別としても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"資料請求という形で、ほかの各自治体で高さ規制に取り組んでいる事例とか、そういったものの把握をされているかと思うので、ぜひそこの調査項目に入れていただければ、当然そういう資料が出るんでしょうけれども、そうでない場合に、そのことについて、委員会としてぜひ資料請求をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-042"},{"speaker":"井上委員","kind":"意見","question":"個々のケースで言うと、いろいろな差がありまして、どういうふうに出していただけるか、よくわからないので、調査自体は委員会が調査権があるんだよというような仕組みがある中で、それをどう利用するかというのはメンバーそれぞれかもしれませんので、議論の案件になれば、それは当然、皆さんで協議をする材料になるんですが、その事前のことということでも、委員会でそれを共有して。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-043"},{"speaker":"宮崎委員","kind":"質問・要望","question":"その中身が、どういう中身が報告されたのかということをつかんでいないか、つかんでいたら、お知らせいただきたいということだったんですけど、昨日はちょっと戸越公園駅は急行がとまるとか、とまらないとか、そんなものがあったんですけれども、実際にとまらないと。それは以前からそういう計画であったんですけれども、あそこの地域住民の方は駅の高架化というのは、長い間の要望なんですね。","respondent":"阿部都市計画課長","answer":"国との関係もあり、あるいは東急としても計画的に事業を進めているという段階ですので、今すぐ、あそこの高架化に取りかかるとか、そういうのは、当面はかなり難しいという話をしたというふうに聞いております。","voiceIndex":117,"id":"exchange-044"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、これは一東急と地元住民のあれでということだけじゃなくて、区民の安全にもかかわってくる問題だと思いますので、ぜひ住民の方々の要望なんかもつかみながら、必要な対応をしていただければと思います。今日はこれで終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-045"},{"speaker":"藤田委員","kind":"質問","question":"そうすると、週の初めというのは道路渋滞が大変だと思うんですよね。前日が休みで、いきなり３０日の朝、出かけるとなってしまうというよりも、事務局が１日と３０日に準備をして、３１日の火曜日からスタートして、２泊３日なら２泊３日。場所についてはまたいろいろあると思いますけれども、そういう方が逆にいいんじゃないかなと思うんですが。いかがでしょうか。３０日だと大変だと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-046"},{"speaker":"松澤委員","kind":"質問","question":"私は平成１５年に区民委員会で９月１日から３日出たんですよ。区民委員会だけ、９月に行ったんですけど、これは名古屋に行ったんですが、暑くて、暑くて、まいりました。そのことから考えると、実際に視察ですから、どういうところでどんなものを視察したいかで、違うと思うんです。委員会の中で自由に決められるわけですから、何もこの時期に行くのではなくて、早い時期に行ってもいいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-047"},{"speaker":"藤田委員","kind":"意見","question":"まさに旭山動物園が、真冬でもやっているんですよ。むしろ、真冬の方が今、人気があるんですよ。恐らくその日が休園日なのか、たまたま改装日だったのか、それはわからないです。でも今、真冬の方が逆に人気がある。寒くなれば寒くなるほど人気があるんです。ただし、時期がちょっと制限されます。例えばの話。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-048"},{"speaker":"中塚委員","kind":"意見","question":"まだ今の時点で、ここが今、みんなで研究すべきテーマなのか、まだ私の中で見え切れていない部分があるので。ただ、今、委員長がおっしゃったように、この時期にこれを見るというのであれば、日程も、それは十分に１０月までに限らずに、時期はもちろん必要だと思いますけれども、まだ議論の中で、ここというのがまだ私の中では、というのが率直なところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"さっき若干、所管事務調査のところで議論、要望が出て、その延長にあるものがあれば非常にいいのかなと。それに必要な時期を調整した上で、相手の関係もあるでしょうから、そういうのがいいのかなと。同じことですけど。そういう点で、まだよくわからないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-050"},{"speaker":"大西委員","kind":"意見","question":"どうやって手を打たなきゃいけないのかということで、散々頭を悩ませて、少ししながわ水族館に似ているかなという気も若干していたんです。ちなみに、私もどうしてそんなに旭山動物園が人気なのか、先ほども藤田さんがいろいろ動物との接点ということも言っていたんですけど、利用料なんか大人が５８０円です。なおかつ中学生以下が無料という状態なんですね。そういう形で、どうして運営していけるのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-051"},{"speaker":"中塚委員","kind":"確認","question":"今の大西委員の意見も大事だと思うんですが、区切られた日程の中、建設委員会自体も１１回か１２回なのかな。もちろん建設の確認業務、私たちの開発もそうですけど、都市景観や、先ほど井上委員から話があった高さのこと一つとっても、まだまだ整理し切れていないと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-052"},{"speaker":"松澤委員","kind":"意見","question":"区民委員会のときかな、うだつも見たいということで、うだつに電車を乗り継いで、電車の中でお弁当を食べながら行ったんです。昔の藍の問屋のまちがあって、それがこうなっているわけで、防火壁で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-053"},{"speaker":"松澤委員","kind":"質問","question":"旭山動物園が休みじゃ、しようがないじゃない。いつまで休みなんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3854#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":43655,"voices":159}},{"id":"h18-20060627-9","meetingId":"h18-cm06","date":"2006年6月27日","dateIso":"2006-06-27","committee":"文教委員会","time":"午前１０時０３分～午前１１時３８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"原副委員長","kind":"質問","question":"それから宮崎のほうで、教育特区という話も聞こえておりますので、その辺のところをかけられたら、九州に行くのも一つの形なのかなと思います。そんなところはいかがでしょうかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"沢田委員","kind":"意見","question":"調査項目からすぽっと落ちちゃったから、多分採用されないかもしれないけれども、私は、愛知県の犬山市にぜひ行ってみたいなと、いろいろ参考になる点があるんじゃないかと思います。そこでよい教育実践をやっていますので、できればそこに行きたいと思っています。私は二度ほど行ってきたんですが、実際の授業の現場はなかなか見られなかったので、できれば見たいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-002"},{"speaker":"築舘委員","kind":"意見","question":"今、副委員長のほうからの話があったんですが、小中一貫教育ということで、平成１５年度は呉市に行っているんですよね。それから、平成１６年度は京都に行っている。それから、平成１７年度は北海道の三笠市に行っているので、奈良市にまだ行ってないということもあるし、その辺を中心に、もしできれば行ってみたいなと、今思っています。それは単なる希望で、皆さんの。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"いわゆる学校教育じゃない部分、生涯学習と言っていいのかあれなんだけれども、そういうものの事例のいいところ。やっぱりそれで、教育委員会も苦労されているんだろうけれども、もうちょっとフリーハンドで子どもが過ごせる場所とか、何かに取り組んでいるところがあったらと思っているんですけれども、どこというところがないから、抽象的なんだけれども。","respondent":"中島委員長","answer":"ほかにありますか。今の林委員のように、こういう内容で、というものもございましたら、ご提案いただければ、それでこちらで探すということもできるかと思います。そのとおりいくかどうかはわかりませんけれども。","voiceIndex":8,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"平成１６年度に中島委員長で、金沢で５番目の、教育プラザ富樫というところは非常に勉強になったんです。ああいう、いわゆる直接的ではないけれども、教育の施設として、品川区も教育センターを直すということが、そんなに遠くない時点であるんだろう、第一日野小学校のところも。同じところに行くわけにいかないから、何か同じような感じのものが、ほかでも取り組んでいるところがあれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-005"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"きょう、資料が出ておりますけれども、改めて、学校選択制を導入して７年目についにゼロになったということなんかも含めて、その原因と、区としてはそのことをどう見るのかということも合わせて、お考えを示していただければありがたいと思います。その前にきょうは、時間的にはいつぐらいまで余裕があるんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"そうですか、じゃああまりないんですね。できるところまでで結構ですので、特に、どういうことでそこに至ったのかという経過を中心に、とりあえず言ってもらえればありがたいんですが。","respondent":"古里学務課長","answer":"３０日、３１日の説明会ですが、保護者、地域の皆さんに初めて説明をするということ、それから、今までの学校選択制があったという経緯から、そうした５校のＰＴＡ会長の皆さんとの協議、それから、教育委員会としての考え方を前面に出さないで。","voiceIndex":17,"id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"学校の統廃合といいますか、それは歴史のある学校ほど大変難しいし、いろいろな意見が出てくる。八潮は比較的歴史が浅いという面もあるかもしれない。３０日と３１日にやったＰＴＡの説明会の参加者と、そのときの議事録みたいなものは何か取ってあるんでしょうか。","respondent":"古里学務課長","answer":"説明会は、３０日はＰＴＡでございまして、３１日は地域の自治会、それから防犯協会、防災協議会、地区委員等への説明でございました。説明会参加人数ですけれども、ＰＴＡのほうは、５校のＰＴＡ関係者９４名です。それから、地元関係者による説明会出席者は２７名です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は、現地の状況もわからないものですから、一貫校に統合するのはいいとか、悪いとかあれですけれども、ただ、そういう決断をするに当たっては、大方の住民の意見、合意があることが大切で、私が聞いたところによると、諸手を挙げて賛成したという人はそんなにいなかったと。きょうはちょっと時間がないところなので、一応一たんこれで打ち切って、また別の機会に質問させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4576#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":8490,"voices":33}},{"id":"h18-20060627-5","meetingId":"h18-cm06","date":"2006年6月27日","dateIso":"2006-06-27","committee":"総務委員会","time":"午前１０時０２分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１８年請願第８号 国際人道法に則り、国民保護協議会に自衛隊員を採用しない等の請願","agenda":"平成１８年請願第８号 国際人道法に則り、国民保護協議会に自衛隊員を採用しない等の請願","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"もう１点ですけれども、これからその保護計画をもとにして避難をするという計画を立てていくわけですけれども、品川区の昼間人口をこの間、お聞きをしたんですけれども、１０年前ぐらいの数字だったものですから、現状での昼間人口についても教えていただければと思います。","respondent":"桑村危機管理室長","answer":"その意味ではいわゆる人権侵害を行わないように十分配慮するというのはこれは当然考えなければいけないことだと考えていますし、つくる上では検討する必要があるだろうと思ってあります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"公開の問題なんですけれども、これから審議をするという話なんですかね。スケジュールを見ますと、実際にはもう５月の段階で第１回目の協議会を開催をしているのかなというふうになっていますけれども、ちょっとその辺、教えていただきたいんです。それから、先ほどもありましたけれども、防災会議の委員と国民保護協議会の委員を同一にする。この辺も１つ教えていただきたい。","respondent":"桑村危機管理室長","answer":"それからもう一つは、自衛隊自身が実際上そういう事態になったときに持つ役割ですけれども、１つは都道府県知事が、いわゆるそういう措置を円滑に実施するために自衛隊を要請することができることになっております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"予算議会のときの答弁ですと、戦争かどうかではなくて、被害を早くキャッチをして最小限に食い止める、それでなおかつ区民の生命、財産を守るのが国民保護計画だというふうに答弁をされているんですけれども、それだと災害対策のほうが自治体として判断ができるわけですから、よほど早く対応することが可能なんじゃないかと思うんですけれども、ちょっとその辺も教えていただければと思います。","respondent":"桑村危機管理室長","answer":"それは理由がわからないとしても、何らかの形で区民の方が安全を脅かされていくということになれば、それは本部という形態をどうとろうが、区を中心に区の職員が動くというのはこれは当たり前の考え方ですので、それは災害対策本部という名称になるのか。","voiceIndex":10,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問・要望","question":"先ほど自衛隊が実際の避難の中でどういう役割を持つのかというところで、明確にこういう役割だよという、ちょっと明確な答えがなかったように思うんですけれども、もう一度その辺を教えていただきたいんですけれども、自衛隊との関係で言えば、実際に戦争行為の中で軍隊が軍事作戦を後回しにするというのは、まずこれまでの歴史的な経過から見ても考えられないと思うんですけれども、もう一度その辺。","respondent":"桑村危機管理室長","answer":"自衛隊の役割ですけれども、先ほど申しましたとおり、国民の保護のための措置を円滑に実施するために、区市町村が特に必要であると認めるときは都道府県知事に対して要請を行うことができるということ、これは避難もあるでしょうし、いわゆる救援ということもあるでしょうし。","voiceIndex":12,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"そのことは今のイラクでの戦闘行為を見れば明らかですし、私たちの国自身がわずか６０年前に一般国民と軍隊との関係で悲惨な状況を沖縄で味わってきたわけですから、そのことを前提にしてやはりきちんと考えていかなければならないんではないかというふうに思うのと、それと自衛隊が避難住民を誘導していけば、そのテロ行為の当然攻撃対象になるというのは、これも明らかだと思うんですけれども。","respondent":"桑村危機管理室長","answer":"正直言って、いわゆる仮定の議論というようなことになるんだろうと思うんです。どういう行為を想定していて、私どもの区がその上で自衛隊に何の要請をするかということがない状態で、なかなかお答えするのは難しいお話なんだろうと思います。","voiceIndex":14,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"仮定の論議だから答えようがないというのは、どう考えてもちょっと納得ができないんですね。それで、要は仮定の、今、仮定の論議をしているから計画そのものを、何というんでしょう、これは仮定の論議だとすると計画そのものが必要ないのではないのかというふうに思うんですけれども、この辺はどうでしょうか。","respondent":"桑村危機管理室長","answer":"その意味では一定の考え方、その中でどういう役割を果たすかというのは、今のところ法律の中ではこういった自衛隊の役割というのは円滑な実施というのを市町村が要請を、都道府県知事を通じて特にそういう要請ができるという役割ですので。","voiceIndex":16,"id":"exchange-006"},{"speaker":"山村委員","kind":"質問・要望","question":"そうすると、あと自衛隊員の場合は、これは専門委員にしておくということも考えられると思うんですが、そこら辺は普通の委員にしておくべきなのか、専門委員にしておくべきなのかというような、何というんですか、考えがあるだろうと思いますが、そこら辺はどういうに思っているのか、教えていただきたいと思います。","respondent":"桑村危機管理室長","answer":"いわゆる専門委員というのは、特に区の中で私どもの中で知識がなかなか及ばないところ、私どもの中の区の中であるとすれば、東京電力の発電所があるわけですけれども、ああいうところの機構がもしも何かあったときにどうなるんだろうというのは。","voiceIndex":21,"id":"exchange-007"},{"speaker":"山村委員","kind":"意見","question":"必ず公開ということだと思うんですけれども、これは基本的に国民保護協議会というのはどういう避難経路を通ったらいいのか、そういう有事のときにどういう避難活動をとったらいいのかというようなことを協議するというふうに理解させていただいているので、逆にこれは公開すると、どういう経路で区民が逃げるのかわかったほうがテロはやりやすいと僕は思います。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、協議会を開催する中で、今回、自衛隊の方たちが保護協議会の構成員に入られておりますけど、そのときに何か自衛隊が入ることに対して協議会から何か意見が出たのかと思うんですけれども、それはまだ全然話はまるっきり出ていない状態でしょうか。","respondent":"桑村危機管理室長","answer":"１つは、この構成員自体が、先ほど少し３ページの中で触れたとおり、法の中でどういう委員構成にしろというのが基本的に決められておるものですので、その中で特に例えば私どもの区の中では、いわゆる国に関するものについてはほとんどないというような判断があれば。","voiceIndex":24,"id":"exchange-009"},{"speaker":"須貝委員","kind":"確認","question":"そこら辺、ちょっと確認だけお願いします。","respondent":"桑村危機管理室長","answer":"その意味では広く区民の意見を得られる構成にすべきだですので、当然町会長の方、それぞれの町会長の地域がやるわけですけれども、その中で区民の意見が、そこで得られるんだろうというふうに思ってあります。","voiceIndex":26,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、請願等出ておりますけれども、協議会の中で活発な議論をされて、区民にとってよりよいものになるように、ぜひいろんな関係機関と協力していいものをつくり上げていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"塚本委員","kind":"意見","question":"３ページの６の「国民保護法制に係る今後のスケジュール」というところを見ておりますが、第１回の会議は開かれたということですが、まだ。予定では５月ということなんですね。その経緯を、それからこのスケジュール、この表でいいのかどうか。","respondent":"桑村危機管理室長","answer":"その後８月、１１月というのは基本的にはほぼ変わらない状態で考えているものです。それから、２月というのはなかなか難しいかなと思いますが、３月ぐらいになるかと思いますけれども、策定する予定というものです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"おくれているということですけれども、品川区国民保護計画原案を協議会でつくってくれということですね。それから、各都市であるとか、農村部であるとか、危険物のぐあい、地形、それぞれいろんな要素があるわけですけれども、どの程度そういうものを勘案するという状況や考え方になっているのか、それを教えてください。","respondent":"桑村危機管理室長","answer":"その意味で、区の中で今後検討するとすれば、その意味では区の人口なりあるいは居住の構成、あるいは先ほども少し出ましたけれども、昼間人口あるいは商業あるいは工業といった集積の度合い。","voiceIndex":32,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"それで、その案をつくっていくというのがまず協議会の最初の仕事だと。その後、協議会というのはどういう権限を持っているのか。それから協議会というのは基本的にどの役割を果たしているか、ガイドラインをつくってこうしてください、これで、かくかくしかじかの権力のところでこうしてほしいよというふうにやるのか。どういう役割を協議会というのは担うのかということをお聞きしたいと思います。","respondent":"桑村危機管理室長","answer":"その意味では、ただ関係機関の代表者が入ってありますので、この国民保護計画に基づいてどういう各関係機関に役割をお願いするか、特に消防等については大きな役割がありますので、また消防庁としてもまた自分たちの計画を持ってありますので。","voiceIndex":34,"id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"そうしますと、協議会のメンバーに自衛隊が入っているということは、この専門的な知識をその協議会の場で生かしてください、現場に出て何かあったときに直ちにその人が誘導するとか、そういうことを想定しているということではないということですか。","respondent":"桑村危機管理室長","answer":"そのとおりです。","voiceIndex":36,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"先ほど協議会はまだ開催をされていない、私はてっきり開催をされて第１回目は終わったものだというふうに思っていたんですけれども、そうであると、前段、第１回目の協議会を招集をする際に、協議会を原則公開をするという文言というのは、これから付け加えていけるんですか。何らかの規則的なものの中に。その辺、ちょっとお聞かせ願えますか。","respondent":"桑村危機管理室長","answer":"その意味で、前に何らかの公開をするとかいうような規則をつくるような考え方は持ってございません。","voiceIndex":38,"id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"これから協議会で論議をされるものについて、議会へは策定後の報告というふうになっていますけれども、これから協議会が行われて、わずか３回で策定をしてしまうということになっていますけれども、１回１回について、１回１回かどうかは別ですけれども、案の段階で議会へ報告をするということは可能なのかどうか。その辺をちょっとお聞かせください。","respondent":"桑村危機管理室長","answer":"ここの今後のスケジュールの中で、区議会への報告の義務というのは基本的にできた後の報告の義務ですけれども、前々からご答弁しているとおり、原案をつくった段階で本会議等にかけさせていただいてご意見を伺うというつもりでおりますし。","voiceIndex":40,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"今、審議を伺っておりまして、その自衛隊が入っていることによって、指導的役割を担うということではないんだと、委員会に入ってプロの意見を聞くということだと。位置的に。ですから、あと航空自衛隊も委員として入っていただいてプロの意見は聞かないのか、陸上自衛隊だけでいいのかという不安が今出てまいりましたので、その辺についてはいかがでしょうか。","respondent":"桑村危機管理室長","answer":"例えば島ですとか、そういったところについてはまた違う考え方はあろうかと思いますけれども、２３区ではそういう考え方でいきたいというふうに思ってあります。","voiceIndex":42,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問・要望","question":"陸上だけで大丈夫だというのは、あまりにも危機感がないんじゃないですか。だって例えばテロというのは、ルールも何もないからテロでしょう。節度を守ったテロなんてないわけですよね。どうせだったら３自衛隊の方に委員会に入っていただいて、やっぱりプロの意見を、せっかくですから、会長が区長なんですから、３つの自衛隊にぜひ参加していただきたいと思うんですけれども、もう一回答弁をお願いします。","respondent":"桑村危機管理室長","answer":"そういう意味で違う構成でやるということになると、また１つの避難誘導あるいは救援といった活動についてのご意見を伺うという、違う方からご意見を伺って計画をつくってもらうと、やはり一定の整合性をとれないところもありますので。","voiceIndex":44,"id":"exchange-019"},{"speaker":"塚本委員","kind":"意見","question":"私もかなり同趣旨の内容を前期の委員会でやりました。問題の背景はそれなりに承知しておるつもりです。結論ですけれども、本日結論を出すべきでありますし、私どもは不採択が適当であるというふうに考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-020"},{"speaker":"山路委員","kind":"意見","question":"私のほうは、国民保護協議会条例を品川区も成立されたわけですので、その点と、この協議会は７月５日からスタートする、この中に含まれている、それからスタートするのではないかと思いますので、不採択で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"採択を要求します。ついでに意見もちょっと述べしますけれども、予算審議の際にも述べていますけれども、やはり国連を中心にして平和を追求する、このことが区民を守る一番大事な手だて、最大の手だてではないかというふうに思っております。私はこの請願を採択するのは当然ですし、国民保護法に基づいて今行われている計画全体を凍結をし、見直すということが必要だというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-022"},{"speaker":"山村委員","kind":"質問・要望","question":"不採択をするべきだと思います。避難のときですとか、そういうときとかに自衛隊の方がいるとリスクが増える、そういうことの話を特にこういう協議会で実際はどうなのか、そういう部分は実際によく検討していただいて、一番区民が安全な方法で避難できる方策を探していただきたいと思います。全面非公開も全面公開もやめたほうがいいと私は思います。私自身は、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-023"},{"speaker":"須貝委員","kind":"意見","question":"うちの会派のほうはさまざまな意見がありまして、それをちょっと申し述べておきます。私はそのような意見を述べて、本日結論を出していきたいと考えています。私の意見としては不採択ということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-024"}]},{"id":"topic-02","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"１つだけ教えてもらいたいんですけれども、これは小規模多機能型ということなんですけれども、これは予定価格に対して補助金というのがどの程度の割合でどういうふうに出てくるのか、ちょっと教えていただけますか。","respondent":"新美企画部長","answer":"こちらのグループホーム、それから小規模多機能居宅介護および介護予防拠点ですね、その３件とも今度申請されます地域・介護福祉空間整備交付金、従来の補助金が交付金化されますので、そちらの交付金対象になっております。","voiceIndex":61,"id":"exchange-025"},{"speaker":"山村委員","kind":"質問","question":"３ページにある関連別途工事、給排水と電気設備工事、これも両方とも今回の場合は山田建設ということなのかどうか。別なんでしょうか。","respondent":"中島経理課長、日下部企画財政課長","answer":"それと、もう一つの電気関係の契約ですけれども、こちらも別の形で発注をしてございまして、こちらの業者が東陽電気工事株式会社となってございまして、契約金額が１,３６９万８,０００円となっています。先ほど企画部長のほうからご答弁をちょっと申し上げましたけれども、国の補助金の関係ですけれども、新しく申請されました交付金がございまして、それで６,０００万円ほど見込んでいるところです。申しわけございません。","voiceIndex":63,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"昨日も基本的なことを伺って、今日も昨日、今日でちょっと基本的なことを、あとは個別でやりますのでちょっと教えていただきたいんですが、この６社申し込んであって所在地がみんな品川区となっていますけれども、いわゆる東京営業所とか品川支店とか東京支店となっておりますが、支店が品川区にあったりするわけですから、もちろんこれも区としては、地元業者、区内業者と考えるんでしょうか。","respondent":"中島経理課長","answer":"今回の入札の参加資格ということでは、区内業者で共同格付ＡからＣということになってあります。そういった意味では、支店等で、要するに品川区の中にきちっと事務所を構えているという会社であれば、対象になります。","voiceIndex":66,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"だけれども１回でも入らないと、入らないと公の仕事というのはゼロなわけですから、公の仕事に入りたくても、業績が民間のしかないという場合は結構あると思うんですけれども、その公に１回でも入ってどんどん回数を重ねていくと、公の業績がありますという企業と同じぐらいのレベルがあっても、公に１回も入れなかったから、民間の業績がいっぱいあっても公の業績がないからだめですよとなっちゃうと。","respondent":"中島経理課長","answer":"そういった中では、要するにこちらの今回たまたま２,９００万円ぐらいの規模ですけれども、そういったものから、あるいは五、六百万のもの、あるいは１０億、２０億のものもありますので、そういったそれぞれの工事の規模、内容によりまして。","voiceIndex":68,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこなんですけれども、昨日の委員会の中で、ある委員から１つのところにまとめてやったほうが、仕事を落としたほうがいいんじゃないかという意見が出ていましたけれども、私は大反対なんですよ。ですから、そこは要望なんですけれども、もしできるのであるならば、品川区、特になぜ区というかといいますと、価格の問題もそうなんですけれども、必ずみずほ銀行ですよね。必ず入るじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-029"},{"speaker":"山村委員","kind":"質問","question":"私も質問になっちゃって申しわけないんですけれども、これとまた違う。そういうのは監視されているのかどうかというのは、もしやられているのだったらやっている、やっていないならやっていないで教えてください。","respondent":"宍戸施設担当課長","answer":"区といたしましても、その辺しっかり見るために、どういう下請けの人を使って、きちっとした契約を取り結んでいるかどうかというところまで報告させておりますので、細かい契約金額まで具体的に口を挟むというふうなことに関しましては一定限界がありますけれども。","voiceIndex":71,"id":"exchange-030"},{"speaker":"山村委員","kind":"質問・要望","question":"今のご説明ですと、契約というもの自体はちゃんと監視していると理解させていただいたんですが、このお金の支払いについてというのはまた別ではなかろうかなということで理解しているわけですよね。今後は何かしらそういうのを考えていただければいいと思います。そういう孫請けとかやっているのは、逆に特に品川区の地元のやはり会社ということもあると思うので、どうかよろしくお願いいたします。要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"すみません、私も関連して質問をちょっとさせていただきたいと思うんですけれども、今所在地が品川区ということで、山田建設も本店は大田区だと思うんですけれども、基本的に、品川区の企業に仕事をできるだけ配分したいという趣旨なんですけれども、ちょっとおかしいんじゃないかなと思うのは、実際はほとんどが例えば品川区に支店はあっても、じゃあその下請け、２次下請け。","respondent":"中島経理課長","answer":"そういった中で、例えば支店のあった場合に、その支店の従業員がどこに住んでいるのかというところまで考えるというご意見でしょうけれども、少なくとも現在そういった、実際にその会社に対して干渉するというんですか、品川区に支店があるんだったら。","voiceIndex":74,"id":"exchange-032"},{"speaker":"須貝委員","kind":"質問","question":"だから品川区にそのお金が還元しない、区民に還元するとか、そういう意味合いではないというようなことで、よろしいですか。","respondent":"本間総務部長","answer":"自治体を構成するのは区民だけではなくて企業も団体も構成員になっているということから、先ほど来経理課長から申し述べておりますとおり、区内にあります中小零細企業の振興ということから、品川区としていろいろと工夫をしながら、例えば大きな工事でもＪＶを組んで。","voiceIndex":76,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"今回の旧亀田邸跡地の施設なんですけれども、実際に２階建てということで階数がなっておるんですけれども、ほんとうにいい場所で広いところだと思うんですけれども、ほんとうにこういう高齢者の先の施設というのはますますこれから区民の高齢者に対する需要がすごく多いと思うんですけれども、実際にその、建てるならば、せっかく鉄筋で立派なものを建てるならば、逆に効率のいい３階とかそういうふうにして。","respondent":"中島経理課長","answer":"後段の用途の関係だけ申し上げますと、こちらの地域は第一種低層住宅専用地域ということでありまして容積率１００％、建ぺい率５０％ということですので、そんな大きな建物は建てられないということです。","voiceIndex":79,"id":"exchange-034"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"山村委員","kind":"質問","question":"簡単な言い方をすれば、投票したほうが何かしら特典があるというわけですけれども、得というかですね。投票率のこの低さに関しては。もう少し区も投票というか、選挙を盛り上げるように手助けというんですか、そういうことをやっていくべきだと思うので、何かしらそういう仕組み、イベントというか、そういうものを考えていくべきじゃないかと品川区民連合では結論に至りましたので、出させていただきました。","respondent":"石田委員長","answer":"衆議院議員の選挙はやっぱり興味があるから行くわけで、区議会議員のレベルだと、なんだ、区議会議員の選挙はつまらないから行かないというのは現実で投票率が低いのかなというのがありますが、そこら辺をあまり商店街とかどこかと連携は連携として、だけれども。","voiceIndex":83,"id":"exchange-035"},{"speaker":"須貝委員","kind":"意見","question":"やはりこれだけ政治離れしてきて、その中でも頑張っている議員もいらっしゃる。それが区のほうでどういうふうに干渉する、どういうふうに啓発事業を進めるということじゃなくて、やはり我々一人ひとり議員の自覚なり運動だと思いますので、これは入れなくてもいいんじゃないかなというふうに、調査事項に入れなくていいんじゃないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-036"},{"speaker":"須貝委員","kind":"質問","question":"もう１点いいですか。その中で、じゃあさらに一歩進めて、よそでそうなって、じゃあ品川区で果たしてそれができるかどうかはわかりませんが、やはりそういう入札予定価格、入札価格のもっと差を広げられて、広げていけるのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-037"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"山村委員","kind":"意見","question":"それを１回見てすごくおもしろかったので、そういうのは総務になるかどうかわからないんですけれども、それを見てみたいなと考えています。あやふやな話で申しわけない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-038"},{"speaker":"山路委員","kind":"意見","question":"私は団塊の世代の、来年の社会に問題あるところをいろいろ考えて、今年は平和事業というのを、イラク撤退もありますし、平和事業、平成１４年度に広島に、この総務委員会で行った状況があるんですけれども。長崎もありますし、平和事業をもう一度見直す。行ってもっともっと深く平和に対する認識を新たにしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-039"},{"speaker":"須貝委員","kind":"意見","question":"今回入札制度改革の成果ということで、長野県で入札制度改革の成果ということが出ております。入札予定価格に対して下がった、またさらにいろいろな中小企業に対してもきめ細かい入札制度を構築したようなんですけれども、ぜひそこを見たいなと思っているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1724#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":33410,"voices":108}},{"id":"h18-20060628-11","meetingId":"h18-cm06","date":"2006年6月28日","dateIso":"2006-06-28","committee":"自治制度特別委員会","time":"午前１０時０２分～午前１１時３５分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"ありがとうございました。全体的な話を伺いましたけれども、抜けているのがありますよね。何百億か。ここで話して、これは向こうがつくったものだから、課長が資料に基づいて説明をくれているので、いや、それはこうなっていますというような話にはならないかもわからないけれども、そういうプラント更新なんかについては、どういうふうにとらえていると聞いているのでしょうか。","respondent":"中山資源循環推進課長","answer":"それで、その一般廃棄物処理基本計画の中で、委員のご指摘があった平成２２年度以降の、世田谷工場以降の建て替えなり、更新の計画が含まれておりまして、それについてはここの先ほどの財政フレームの中に入れ込まれております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"平成２４年度は、杉並と練馬。平成２６年度は、杉並と光が丘。複数になってきている。言っている意味はわかります。今までの大規模なものと小規模なものを織り交ぜているんだということなんでしょう。（５）、真ん中のIIの行財政システムの改革の中の３番の（５）で、低入札価格調査制度の導入、これはどういう入札制度なんですか。","respondent":"中山資源循環推進課長","answer":"従来のいろいろなプラントメーカーによる説明等を入札の中でやっておるんですが、いろいろな方法があるのではないかということで、今申し上げた１つはＰＦＩなんですけれども、そういうことに視野を広げて情報をとろうというところがありますので。","voiceIndex":14,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"いろいろ改革という、そういうくくりで聞いておきます。ちょっと話が細かい話になるかもしれませんけれども、前回のときにもらったリサイクル２００５のほうの資料から、いわゆる入札のこの間談合が新聞に出ていましたよね。ずっとこれ、日本鋼管からいろいろな形、ガスまで含めたんだけれども、あそこの会社は２３区にかかわっていないですか。毎年大規模修理を２カ月かけてやるわけです。","respondent":"中山資源循環推進課長、岩崎環境清掃事業部長","answer":"この前のというのが、ちょっと私、実は２３区の中にも相当のメーカー数がここに入ってありますから、いろいろ入札談合ということでメーカーとして指摘されて、一時的に入札参加の停止があってというようなことは。だから、そういう意味で、横浜の談合事件につきましては、一組のほうもかなり神経をとがらせて対応しているはずです。","voiceIndex":16,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"これは議長にもお願いしておきたい。それが２１工場全部にかかわってくる仕事なわけね。ですから、できるだけの数字を、最初の３年ぐらいはまるっきり出てこなかった一組の財政問題だけれども、ここへ来てこういう資料を出してくれるということは、もっともっと出てくるはずだと僕は思いますので、議長にもお願いしておきたいし、できるだけそういう資料を集めていただきたい。それを今度教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-004"},{"speaker":"土井委員","kind":"質問","question":"経営計画、あるいは経営改革プランということには、組織変革や人的な問題、アウトソーシング等もそういう改革の１つなんですけれども、これらのものに対しては、そこに働いている皆さん等々も含めて、どういう理解と了解のもとに進めていくかということがなければ、具体的には進まない部分もあるのではないかと思えるんですけれども、その辺についての流れ。","respondent":"中山資源循環推進課長","answer":"実際、この辺をきっちり進めていくための区と、それといわゆる一組側の理解、あるいは認識ですけれども、正直、平成１２年度移管以降においては、なかなか仕組みは手探りであったところもありますけれども、全体についても明確でなかったし。","voiceIndex":28,"id":"exchange-005"},{"speaker":"土井委員","kind":"質問","question":"そうすると、これはずっと先ほどの話で行くと、また１０年かいと、１０年出ていると、また２０年かいという話が当分なってしまうので、その辺がどうなのかなという思いでちょっとお伺いをしたんですが、どうもそんな感じにしか見えない、聞こえないなというところでしたので、逆に我々はそのころいるかどうかわからんけれども、堅持をしていかなければいけない部分があるのかなというふうにも思って。","respondent":"中山資源循環推進課長","answer":"とりあえずは４係中の１係は職員部分を残しながら、その他の部分についてはアウトソーシングしていく、こういう整理をしていくわけですから、これを実際に進めながら論議をしていくということを続けていく。","voiceIndex":30,"id":"exchange-006"},{"speaker":"土井委員","kind":"質問・要望","question":"それだけではなくて、大きな流れの中がこうなっているんだということについても、一定程度、常にオーケーというふうになるかどうかは別としても、しっかりと話し合い等を進めておいていただかないと難しい部分が出てくるのではないかなという思いがするものですからそのように申し上げているので、ぜひ、これ以上言ってもしようがありませんから、そういう方向性等もしっかり考えていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"私は一般質問で全体的なことはもう伺っているので、きょうはやめて、教えていただきたいというか、勉強させていただきたい項目を。その下に財政調整基金の残高の推移が書いてあるんですけれども、この金額が減っていくと合わないじゃないですか。積み立てで分担金とかもあるんだけれども、じゃあ、どういう仕組みになっているのかがよくわからないので、そこを教えていただきたい。","respondent":"中山資源循環推進課長","answer":"安全性の問題であるとか、その辺は十分もう区としても認識しておるので、それは伝えていけばいいと思うんですが、多分、それだけのものですからどうぞという、お店を広げて待っている発想ではいけないというところがやっぱり、十分まだ認識は弱いところがあると思いますので。","voiceIndex":34,"id":"exchange-008"},{"speaker":"石田委員","kind":"質問・要望","question":"今の最後の基金の話なんですが、もちろん積みながら使っているのはわかるんだけれども、この計画でどうしてどこのだれがということを教えていただきたいんだけれども。どうしてこんなことを聞いたかというと、何となく決定されるのが区長会みたいな気がしてならないんだよな。ここら辺の話を。","respondent":"中山資源循環推進課長","answer":"それについては、基本的な先ほどの施設整備の方針とか、それを大枠で一廃計画で確認して、それをまた数値化している。確かにそこの部分は分担しております。","voiceIndex":36,"id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"１つだけちょっと確認をさせていただきたいんですが、先ほどからずっとアウトソーシングの話が出ていましたが、これ、行財政システムの改革の中ではアウトソーシングの推進を続けていくということですが、現状の中で具体的に推進のプランみたいなものが示されているのではないかと思うんだけれども、その辺のところはどの辺まで発表できるというか、話ができる段階なのか、ちょっと教えていただきたい。","respondent":"岩崎環境清掃事業部長","answer":"実は、あした、部長会が予定されておりますが、そこである程度の説明があるというふうには聞いております。","voiceIndex":38,"id":"exchange-010"},{"speaker":"沢田委員","kind":"意見","question":"それと、財政上からアウトソーシングをするということは、下手をすると事故につながりかねない、さっきの説明ですと炉を燃焼させる２４時間勤務のここの部分をアウトソーシングしていくというふうにおっしゃっていたんですけれども、実際的にはどんな企業をこれから、いわゆるベテラン部分をこういうところに、炉心の近いところに配置しているんじゃないかなと。","respondent":"中山資源循環推進課長","answer":"今年度２工場で既に今、実施しているというのが、ご説明申し上げたように、運転の中で、４係というのは大体２４時間で交代していくわけですが、基本形として、日中の部分を多分職員がやっているというふうに思います。","voiceIndex":42,"id":"exchange-011"},{"speaker":"沢田委員","kind":"質問・要望","question":"あれの具体化をする場合に、このプラント更新なんかと絡むんですが、具体的にこの清掃工場で何％見なさいみたいな国のあれがある、部長は専門ですから、あるのかないのかということと、それから、もしそれが達成できなかった場合には、ほかの余剰分を他国から買うという場合に、システムとして企業レベル、国レベルで買ってしまうということなのか、ちょっとそこらがわからないので。","respondent":"中山資源循環推進課長、岩崎環境清掃事業部長","answer":"いわゆる事故等の対応という部分で言えば、今申し上げたような経験職員等もあわせてやっていくという部分でありますけれども、一定の他の自治体でもそういった方法を行いながら。ですから、マイナス６％を達成するためには、どうしてもそういうふうにしてＣＯ２をよその国で減らした部分をカウントしてマイナス６にするとかというようなことをしないといけないものですから。","voiceIndex":44,"id":"exchange-012"},{"speaker":"沢田委員","kind":"意見","question":"だけど、実際に排出しているのは企業であり、こういう清掃工場も含めたところであって、そこらの詳細は一体どうなのかなということがわからないので聞かせてもらったんですが、私がわからないのをこれ以上やってもこの委員会に合わないので、とりあえず終わりにしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-013"},{"speaker":"三村委員","kind":"質問","question":"先ほどのアウトソーシングのところで、ちょっとお聞きしたいんですけれども、７ページの表によると、７億円ぐらいマイナスというふうに出ているんですけれども、４ページのほうの職員費と工場等運営費のところの差額は、平成１７年度と比較するとどうなんでしょう。","respondent":"中山資源循環推進課長","answer":"４ページの人件費になりますと、率直に申し上げて、例えば、職員の退職金の経費等が出てまいりますので、例えば、人員削減、特に平成１７年、平成１８年の間で職員が減って、そういう部分がありますので。","voiceIndex":49,"id":"exchange-014"},{"speaker":"三村委員","kind":"質問","question":"済みません、経営改革プラン、カラー刷りのところで、行財政の見直しということで、スラグの有効利用量の拡大と、競争入札による売電などというふうに書いてあるんですけれども、この競争入札によって売電するのはどういったことでしょうか。","respondent":"中山資源循環推進課長","answer":"いわゆる従来、特に電気については、東京電力にしか売却できなかったものが、規制緩和の流れの中で、非常に電力の関係事業者が増えてまいりますので、そういうところと入札も可能になってきたということで、一部既に実績もありますけれども。","voiceIndex":53,"id":"exchange-015"},{"speaker":"三村委員","kind":"質問","question":"競争入札というところも含めて、これは廃プラを燃やして、その電力を売却するんですか。","respondent":"中山資源循環推進課長","answer":"いわゆる入札で売却するかどうかというのは、これは売却の方法の問題ですから、廃プラスチックの焼却によるカロリー増による総売電量が伸びるということと、この入札方法とは一致するというか、次元が違うものということです。","voiceIndex":55,"id":"exchange-016"},{"speaker":"三村委員","kind":"意見","question":"この廃プラスチックの、先ほどから２３区一部事務組合との関係性の問題だと思うんですけれども、こういう廃プラスチックを燃やすということに対して、本来は二十三区一部事務組合で廃プラスチックを燃やすという決定の前に、２３区でどういうふうに各区で取り扱うかというふうに検討していくものだと思うんですけれども、２３区に一部清掃事務組合のほうから意見を出して。","respondent":"岩崎環境清掃事業部長","answer":"個々の区は、それと若干おくれておりますけれども、やっぱり一般廃棄物処理計画上の扱いをどうするかということは、これから決定していくということでありまして、廃プラスチックの熱利用をしようということについては、もう既に区長会で確認されているということで、各部長。","voiceIndex":57,"id":"exchange-017"},{"speaker":"三村委員","kind":"質問","question":"区長会のほうで決定されたということだったんですけれども、今回、廃プラスチック、一般質問でもさせていただいたんですけれども、今回、区長の回答として、リサイクルや何かは今後検討していくということになっていたんですけれども、各区事項として廃プラスチックの有効利用については２３区共通できちんとリサイクルしていくというふうな決定については、その辺についてはどうなんでしょう。","respondent":"中山資源循環推進課長","answer":"今回、中間方針からもともと平成１６年の段階で最終処分場延命のために、廃プラスチックサーマルリサイクルを検討していくとありまして、それを踏まえて、平成１７年１０月の決定の中で、平成２０年に本格実施するということですから、それを踏まえて、今、部長の説明のように。","voiceIndex":59,"id":"exchange-018"},{"speaker":"三村委員","kind":"意見","question":"済みません、２３区の清掃一部事務組合に関わってくると思うんですけれども、各区のほうで進めていくというところで、品川区としては、今後検討というさっきのお答えだったんですけれども、どのような今後の方針、方向性としては考えているのか。","respondent":"中山資源循環推進課長","answer":"基本的にこれは区民委員会の話になると思いますけれども、いずれにしても可能性について、これは検討していくという考え方であります。リサイクルが可能なものはやっていく。","voiceIndex":61,"id":"exchange-019"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひ拡大の方向で検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-020"},{"speaker":"三村委員","kind":"質問","question":"先ほど談合のお話があったかと思うんですけれども、今回、売電をしていこう、廃プラスチックを活用していこうという、その改革のほうだと思うんですけれども、今後の計画というのは、どういうふうに考えているのでしょうか。","respondent":"中山資源循環推進課長","answer":"その辺については、先ほど申し上げたように、情報のいろいろな確認を当方でもしていって、秋口までに一定の結論をという話を聞いておりますけれども、現状はそのような形です。","voiceIndex":65,"id":"exchange-021"},{"speaker":"本田委員","kind":"確認","question":"一般的にこういう経営改革を進めていく中で、当然、各区の持ち出し分も入ってくるというふうに考えるんですけれども、ごみ減量が進む中で、その辺はどういうふうにお考えでしょうか。","respondent":"中山資源循環推進課長","answer":"これは現状で見込まれるアウトソーシングがあるとかを含めて、運営を効率化して分担金を調整基金の活用も含めて圧縮しようというフレームですけれども、この後、より効率化を図っていく。","voiceIndex":68,"id":"exchange-022"},{"speaker":"本田委員","kind":"質問","question":"それで特定財源を増やしていく。このごみの処理に当たって、大きな負荷を受けているところ、受けていないところ、いろいろ２３区の中にはあるわけでして、一組のレベルでも分担金については、さらに区の考え方といいますか、ここに安住するということではなくて、区の考え方があっていいのではないかというふうに思うんですけれども、その辺はどうですか。的外れなことを言っているのかどうか。","respondent":"岩崎環境清掃事業部長","answer":"そういう意味で、違うところで話が盛り上がっておりますけれども、やはり基本はそういう分担金というようなところで区がどのようにかかわっていくべきなのかということを追求していくということが重要なことではないかというふうに私は思っております。","voiceIndex":70,"id":"exchange-023"},{"speaker":"本田委員","kind":"質問・要望","question":"全体の問題だと思うんですよね。２０００年に基礎的自治体になって、どう責任を持ってやっていくのかという物の考え方が基本になければならない。先ほど来の説明の中で分担金を何となくさらりと言っているものですから、基本的な問題がこの中には入っているというふうに私は思っているんですけれども、一組の中でここのところの問題はもっと真剣に煮詰めておいていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5598#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":26968,"voices":78}}]);
